import bisect
import time

INF = 10 ** 9
OFFT = ("write", "checkpoint", "commit")


def _sig(e):
    return (e.get("node"), e.get("type"), e.get("off"), e.get("len"))


def _estimate(E):
    n = len(E)
    g = 1.0
    if n >= 2:
        g = (E[-1]["t"] - E[0]["t"]) / float(n - 1)
    if g <= 0:
        g = 1.0
    seen = set()
    isd = [False] * n
    crash_pos = {}
    for p, e in enumerate(E):
        s = _sig(e)
        if e["type"] not in ("open", "crash") and s in seen:
            isd[p] = True
        seen.add(s)
        if e["type"] == "crash":
            crash_pos.setdefault(e["node"], []).append(p)
    bysid = {}
    for p, e in enumerate(E):
        if e.get("sid") and e["type"] in OFFT and e.get("off") is not None and not isd[p]:
            bysid.setdefault(e["sid"], []).append(p)
    inv = 0
    for sid in bysid:
        lst = bysid[sid]
        for k in range(1, len(lst)):
            pb = lst[k]
            b = E[pb]
            for k2 in range(max(0, k - 4), k):
                pa = lst[k2]
                a = E[pa]
                if a["node"] != b["node"]:
                    continue
                dt = b["t"] - a["t"]
                if dt > 15 * g or dt <= inv:
                    continue
                if b["type"] == "write":
                    ok = b["off"] + (b.get("len") or 0) <= a["off"]
                else:
                    ok = b["off"] < a["off"]
                if not ok:
                    continue
                cp = crash_pos.get(a["node"], [])
                j = bisect.bisect_left(cp, pa - 3)
                if j < len(cp) and cp[j] <= pb:
                    continue
                inv = dt
    if inv > 0:
        W = max(inv * 1.5 + 1.0, 2.0 * g)
    else:
        W = 4.0 * g
    W = min(W, 20.0 * g)
    return W, g


def _sim(E, known, W, skip_abort):
    n = len(E)
    S = {}
    order = []
    assign = {}
    isdup = {}
    snaps = {}
    kpos = {}
    for p in sorted(known):
        kpos.setdefault(known[p], []).append(p)
    pending = []
    deadline = {}
    cur = [0]
    first_sid = None
    for e in E:
        if e["type"] == "open" and e.get("sid"):
            first_sid = e["sid"]
            break

    def base_cost(sid, e):
        x = S[sid]
        T = e["type"]
        N = e["node"]
        O = e.get("off")
        st = x["st"]
        c = INF
        m = "n"
        if st == "active" or st == "down":
            if T in OFFT:
                if O is None:
                    O = x["off"]
                if st == "active":
                    if x["node"] == N:
                        if O == x["off"]:
                            c = 0
                        elif O > x["off"]:
                            c = 2
                        elif T != "write" and O >= x["dur"]:
                            c = 3
                        else:
                            c = 7
                    else:
                        c = 9
                else:
                    pre = x["pre"]
                    if pre is not None and pre[0] == N and e["t"] <= pre[2] + W and O == pre[1]:
                        c, m = 0.2, "pre"
                    elif O == x["dur"]:
                        c, m = (3 if T == "write" else 4), "imp"
                    elif O > x["dur"]:
                        c, m = 8, "imp"
                    else:
                        c, m = 12, "imp"
            elif T == "abort":
                if st == "active":
                    c = 0 if x["node"] == N else 5
                else:
                    pre = x["pre"]
                    if pre is not None and pre[0] == N and e["t"] <= pre[2] + W:
                        c, m = 0.2, "pre"
                    else:
                        c = 6
            elif T == "recover":
                if st == "down":
                    if O is None or O == x["dur"]:
                        c = 0
                    elif O > x["dur"]:
                        c = 2
                    else:
                        c = 6
                else:
                    c = 10
        else:
            c, m = 50, "dup"
        if c > 1 and _sig(e) in x["sigs"]:
            c, m = 1, "dup"
        return c, m

    def lookahead(sid, e):
        lst = kpos.get(sid)
        if not lst:
            return 0.0
        j = bisect.bisect_right(lst, cur[0])
        if j >= len(lst):
            return 0.0
        f = E[lst[j]]
        T = e["type"]
        N = e["node"]
        O = e.get("off")
        fT = f["type"]
        adj = 0.0
        if T in OFFT:
            if T == "commit":
                return 0.3
            if O is None:
                return 0.0
            end = O + (e.get("len") or 0)
            if fT in OFFT and f.get("off") is not None:
                if f["node"] != N:
                    adj += 0.2
                elif f["off"] == end:
                    adj -= 0.15
                elif f["off"] > end:
                    adj -= 0.05
                else:
                    adj += 0.4
            elif fT == "abort" and f["node"] != N:
                adj += 0.2
        elif T == "recover":
            if fT != "recover":
                adj += -0.1 if f["node"] == N else 0.2
                if f.get("off") is not None and O is not None:
                    adj += -0.05 if f["off"] >= O else 0.2
        return adj

    def apply(sid, p, m):
        e = E[p]
        assign[p] = sid
        x = S.get(sid)
        if x is None:
            return
        if m == "dup":
            isdup[p] = True
            return
        T = e["type"]
        N = e["node"]
        O = e.get("off")
        Ln = e.get("len") or 0
        x["sigs"].add(_sig(e))
        if O is None and T in OFFT:
            O = x["off"]
        if m == "pre":
            pre = x["pre"]
            if T == "write":
                pre[1] = max(pre[1], O + Ln)
            elif T == "checkpoint":
                x["dur"] = O
                x["off"] = O
                pre[1] = max(pre[1], O)
            elif T == "commit":
                x["st"] = "committed"
                x["dur"] = O
                x["off"] = O
                x["pre"] = None
            elif T == "abort":
                x["st"] = "aborted"
                x["pre"] = None
            return
        if m == "imp":
            x["st"] = "active"
            x["node"] = N
            x["pre"] = None
        if T == "write":
            if x["st"] == "active":
                x["node"] = N
            if O >= x["off"]:
                x["off"] = O + Ln
            else:
                x["off"] = max(x["off"], O + Ln)
        elif T == "checkpoint":
            if x["st"] == "active":
                x["node"] = N
            x["dur"] = O
            if O > x["off"]:
                x["off"] = O
        elif T == "commit":
            x["st"] = "committed"
            x["dur"] = O
            x["off"] = O
            x["pre"] = None
        elif T == "abort":
            x["st"] = "aborted"
            x["abnode"] = N
            x["off"] = x["dur"]
            x["pre"] = None
        elif T == "recover":
            x["st"] = "active"
            x["node"] = N
            if O is not None:
                x["off"] = O
                x["dur"] = O
            x["pre"] = None

    def choose(p, force):
        e = E[p]
        if p in known:
            sid = known[p]
            if sid not in S:
                if force:
                    assign[p] = sid
                    return True
                return False
            c, m = base_cost(sid, e)
            if c <= 1 or force:
                apply(sid, p, m)
                return True
            return False
        best = None
        for sid in order:
            c, m = base_cost(sid, e)
            if c >= INF:
                continue
            if not force and c > 1:
                continue
            tot = c + lookahead(sid, e)
            if best is None or tot < best[0]:
                best = (tot, c, sid, m)
        if best is None:
            if not force:
                return False
            sid = None
            for q in range(p - 1, -1, -1):
                if q in assign and E[q]["node"] == e["node"]:
                    sid = assign[q]
                    break
            if sid is None:
                sid = order[0] if order else first_sid
            assign[p] = sid
            isdup[p] = True
            return True
        apply(best[2], p, best[3])
        return True

    t_start = time.process_time()

    def retry():
        if time.process_time() - t_start > 0.33:
            return
        changed = True
        while changed and pending:
            changed = False
            for q in list(pending):
                if choose(q, False):
                    pending.remove(q)
                    changed = True

    for p in range(n):
        cur[0] = p
        e = E[p]
        t = e["t"]
        while pending:
            exp = None
            for q in pending:
                if deadline[q] < t:
                    exp = q
                    break
            if exp is None:
                break
            pending.remove(exp)
            choose(exp, True)
            retry()
        T = e["type"]
        if T == "crash":
            N = e["node"]
            for sid in order:
                x = S[sid]
                if x["st"] == "active" and x["node"] == N:
                    x["st"] = "down"
                    x["pre"] = [N, x["off"], t]
                    x["off"] = x["dur"]
        elif T == "open" and e.get("sid"):
            sid = e["sid"]
            if sid not in S:
                S[sid] = {"st": "active", "node": e["node"], "off": 0, "dur": 0, "pre": None,
                          "sigs": set(), "abnode": None}
                order.append(sid)
            assign[p] = sid
        elif T == "abort" and skip_abort and p not in known:
            N = e["node"]
            act = []
            ab = []
            for sid in order:
                x = S[sid]
                if x["st"] == "active" and x["node"] == N:
                    act.append(sid)
                elif x["st"] == "down" and x["pre"] is not None and x["pre"][0] == N and t <= x["pre"][2] + W:
                    act.append(sid)
                elif x["st"] == "aborted" and x["abnode"] == N:
                    ab.append(sid)
            snaps[p] = (act, ab)
        else:
            if not choose(p, False):
                pending.append(p)
                deadline[p] = t + W
        retry()
    cur[0] = n
    while pending:
        q = pending.pop(0)
        choose(q, True)
        retry()
    return {"S": S, "order": order, "assign": assign, "isdup": isdup, "snaps": snaps}


def _assign_aborts(E, r1, W, g):
    assign = r1["assign"]
    isdup = r1["isdup"]
    snaps = r1["snaps"]
    tend = E[-1]["t"] if E else 0
    evs = {}
    for p in sorted(assign):
        if not isdup.get(p):
            evs.setdefault(assign[p], []).append(p)
    out = {}
    aborted = set()
    extra_ab = {}
    for p in sorted(snaps):
        a = E[p]
        N = a["node"]
        act, ab = snaps[p]
        best = None
        for sid in act:
            if sid in aborted:
                continue
            lst = evs.get(sid, [])
            j = bisect.bisect_right(lst, p)
            sc = 0.0
            for q in lst[j:]:
                sc += 5.0 if E[q]["t"] > a["t"] + W else 1.0
            prior = lst[:j]
            if prior:
                last_t = E[prior[-1]]["t"]
                span = last_t - E[prior[0]]["t"]
                gap_s = span / float(max(1, len(prior) - 1)) if len(prior) > 1 else 4.0 * g * max(1, len(act))
            else:
                last_t = a["t"]
                gap_s = 4.0 * g * max(1, len(act))
            if j >= len(lst) and tend - a["t"] < 3.0 * gap_s:
                sc += 0.5
            sc += 0.001 * (a["t"] - last_t) / max(g, 1e-9)
            if best is None or sc < best[0]:
                best = (sc, sid, False)
        for sid in ab + extra_ab.get(N, []):
            if best is None or 0.8 < best[0]:
                best = (0.8, sid, True)
        if best is None:
            sid = None
            for q in range(p - 1, -1, -1):
                if q in assign and E[q]["node"] == N:
                    sid = assign[q]
                    break
            if sid is None:
                for q in range(p - 1, -1, -1):
                    if q in assign:
                        sid = assign[q]
                        break
            if sid is None:
                for e in E:
                    if e["type"] == "open" and e.get("sid"):
                        sid = e["sid"]
                        break
            if sid is None:
                continue
            out[p] = sid
            continue
        out[p] = best[1]
        if not best[2]:
            aborted.add(best[1])
            extra_ab.setdefault(N, []).append(best[1])
    return out


def solve(state, params):
    inp = state["input"]
    raw = list(inp.get("events", []))
    E = sorted(raw, key=lambda e: (e.get("t", 0), e.get("i", 0)))
    sessions_order = []
    for e in E:
        if e["type"] == "open" and e.get("sid") and e["sid"] not in sessions_order:
            sessions_order.append(e["sid"])
    if not E:
        state["output"] = {"assignments": {}, "sessions": {}}
        return state
    anon = [p for p, e in enumerate(E) if e["type"] != "crash" and not e.get("sid")]
    W, g = _estimate(E)
    known = {}
    for p, e in enumerate(E):
        if e.get("sid") and e["type"] != "crash":
            known[p] = e["sid"]
    r1 = _sim(E, known, W, True)
    ab = _assign_aborts(E, r1, W, g)
    known2 = dict(known)
    known2.update(ab)
    r2 = _sim(E, known2, W, False)
    assign = r2["assign"]
    S = r2["S"]
    fallback = sessions_order[0] if sessions_order else "s0"
    out_a = {}
    for p in anon:
        sid = assign.get(p)
        if sid is None:
            sid = r1["assign"].get(p, fallback)
        if sid is None:
            sid = fallback
        out_a[str(E[p]["i"])] = sid
    out_s = {}
    for sid in sessions_order:
        x = S.get(sid)
        if x is None:
            out_s[sid] = {"status": "active", "durable": 0}
        else:
            st = x["st"]
            if st not in ("committed", "aborted", "active", "down"):
                st = "active"
            out_s[sid] = {"status": st, "durable": int(x["dur"])}
    state["output"] = {"assignments": out_a, "sessions": out_s}
    return state

strategy:
The solver runs one deterministic beam search over the log in timestamp order, with no language model. Each beam state keeps, for every session, its status, node, stream offset, durable offset, offset "holes", pre-crash offset and the signatures it has already applied. Every session event is tried against each session as one of several explanations, each with a cost:
- an exact offset match (free);
- a gap from missing writes or jitter, and a later write that fills that gap (refunded);
- an implicit recover where the recover event is missing;
- a late event that really happened just before a crash or commit;
- a duplicate of a signature that session already applied (state unchanged).

