import time


def _fallback(state):
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    lastnode = {}
    status = {s: "active" for s in sids}
    dur = {s: 0 for s in sids}
    out_a = {}
    for e in events:
        if e["type"] == "crash":
            continue
        s = e.get("sid")
        if s is None:
            s = lastnode.get(e["node"], sids[0] if sids else "")
            out_a[str(e["i"])] = s
        if s in status:
            lastnode[e["node"]] = s
            if e["type"] == "commit":
                status[s] = "committed"
                if e["off"] is not None:
                    dur[s] = e["off"]
            elif e["type"] == "abort":
                status[s] = "aborted"
            elif e["type"] in ("checkpoint", "recover") and e["off"] is not None:
                dur[s] = max(dur[s], e["off"])
    state["output"] = {"assignments": out_a,
                       "sessions": {s: {"status": status[s], "durable": int(dur[s])} for s in sids}}
    return state


def _core(state):
    t0 = time.process_time()
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    sidx = {s: k for k, s in enumerate(sids)}
    S = len(sids)
    ts = [e["t"] for e in events]
    gaps = sorted(ts[k + 1] - ts[k] for k in range(len(ts) - 1)) or [1]
    med = gaps[len(gaps) // 2]
    W = max(4.0, 3.0 * max(med, 1))

    seen = {}
    posdup = [False] * len(events)
    for k, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        sig = (e["node"], e["type"], e["off"], e["len"])
        if sig in seen:
            posdup[k] = True
        seen[sig] = k
    lastknown = [-10 ** 9] * S
    for k, e in enumerate(events):
        if e.get("sid") is not None and e["type"] != "open" and not posdup[k]:
            j = sidx[e["sid"]]
            if e["t"] > lastknown[j]:
                lastknown[j] = e["t"]

    GAP, BAD, REC, DUP, LATE, UNC = 2.0, 9.0, 3.0, 1.6, 1.0, 3.5
    FILL = -1.0
    lk = [0]

    # session tuple: (st, node, pos, dur, holes, pre, tcrash)  (+ sigs appended in beam)
    def fresh(se, e, t):
        ty = e["type"]; nd = e["node"]; o = e["off"]; ln = e["len"]
        st, node, pos, dur, holes, pre, tc = se[0], se[1], se[2], se[3], se[4], se[5], se[6]
        res = []
        if st == "P":
            if ty == "open":
                res.append((0.0, ("A", nd, 0, 0, (), 0, 0)))
            return res
        if ty == "open":
            return res
        if ty == "write":
            if o is None or ln is None:
                return res
            end = o + ln
            if st == "A":
                if node != nd:
                    return res
                if o == pos:
                    res.append((0.0, ("A", node, end, dur, holes, pre, tc)))
                elif o > pos:
                    res.append((GAP, ("A", node, end, dur, holes + ((pos, o),), pre, tc)))
                else:
                    done = False
                    for hk in range(len(holes)):
                        a, b = holes[hk]
                        if a <= o and end <= b:
                            nh = list(holes[:hk])
                            if a < o:
                                nh.append((a, o))
                            if end < b:
                                nh.append((end, b))
                            nh.extend(holes[hk + 1:])
                            c = FILL if a == o else 0.5
                            res.append((c, ("A", node, pos, dur, tuple(nh), pre, tc)))
                            done = True
                            break
                    if not done:
                        if o >= dur:
                            res.append((BAD, ("A", node, end, dur, (), pre, tc)))
                        else:
                            res.append((BAD + 2, ("A", node, end, dur, (), pre, tc)))
            elif st == "D":
                if o == dur:
                    res.append((REC, ("A", nd, end, dur, (), pre, tc)))
                elif o > dur:
                    res.append((REC + GAP + 1, ("A", nd, end, dur, ((dur, o),), pre, tc)))
                if node == nd and o == pre and o != dur:
                    dt = max(0.0, t - tc)
                    res.append((LATE + dt / W, ("D", node, pos, dur, holes, end, tc)))
                    res.append((UNC, ("A", node, end, dur, (), pre, tc)))
            else:
                if node == nd:
                    for (a, b) in holes:
                        if a <= o and end <= b:
                            res.append((0.5 if a == o else 1.0, se[:7]))
                            break
            return res
        if ty == "checkpoint" or ty == "commit":
            if o is None:
                return res
            nst = "C" if ty == "commit" else "A"
            if st == "A":
                if node != nd:
                    return res
                if o == pos:
                    res.append((0.0, (nst, node, o, o, holes, pre, tc)))
                elif o > pos:
                    res.append((GAP, (nst, node, o, o, holes + ((pos, o),), pre, tc)))
                elif o >= dur:
                    if ty == "commit":
                        res.append((LATE + 1, (nst, node, o, o, (), pre, tc)))
                    else:
                        res.append((LATE, ("A", node, pos, o, holes, pre, tc)))
                else:
                    res.append((BAD, (nst, node, o, o, (), pre, tc)))
            elif st == "D":
                if node == nd and dur <= o <= pre:
                    dt = max(0.0, t - tc)
                    if ty == "commit":
                        res.append((LATE + dt / W, ("C", node, o, o, (), pre, tc)))
                    else:
                        res.append((LATE + dt / W, ("D", node, o, o, (), pre, tc)))
                if o == dur:
                    res.append((REC + 0.5, (nst, nd, o, o, (), pre, tc)))
                elif o > dur:
                    res.append((REC + GAP + 1, (nst, nd, o, o, (), pre, tc)))
            else:
                if node == nd and o <= pos:
                    if st == "X" and o > dur:
                        res.append((LATE + 0.5, ("X", node, pos, o, holes, pre, tc)))
                    else:
                        res.append((LATE + 0.5, se[:7]))
                elif node == nd and st == "C" and ty == "checkpoint":
                    for (a, b) in holes:
                        if a < o <= b:
                            res.append((LATE + 1, se[:7]))
                            break
            return res
        if ty == "abort":
            pen = 6.0 if lk[0] > t + W else 0.0
            if st == "A" and node == nd:
                res.append((0.3 + pen, ("X", node, dur, dur, (), pre, tc)))
            elif st == "D":
                if node == nd:
                    res.append((LATE + max(0.0, t - tc) / W + pen, ("X", node, dur, dur, (), pre, tc)))
                res.append((REC + 1 + pen, ("X", nd, dur, dur, (), pre, tc)))
            return res
        if ty == "recover":
            if o is None:
                return res
            if st == "D":
                if o == dur:
                    res.append((0.0, ("A", nd, o, o, (), pre, tc)))
                elif dur < o <= pre:
                    res.append((GAP, ("A", nd, o, o, (), pre, tc)))
                else:
                    res.append((BAD - 2, ("A", nd, o, max(o, dur), (), pre, tc)))
            elif st == "A":
                if node == nd and o == dur and pos >= o:
                    res.append((1.0, se[:7]))
                else:
                    res.append((REC + 1.5, ("A", nd, o, max(o, dur), (), pos, t)))
            return res
        return res

    init = tuple(("P", None, 0, 0, (), 0, 0, frozenset()) for _ in range(S))
    beam = [(0.0, init, None)]
    nev = len(events)
    B = 24 if nev <= 200 else 16
    budget = 0.55
    for k in range(nev):
        e = events[k]
        ty = e["type"]; t = e["t"]
        el = time.process_time() - t0
        if k > 10 and B > 1 and el > budget * (float(k) / nev) * 1.1:
            B = max(1, B // 2)
        if el > 0.85:
            B = 1
        if ty == "crash":
            nb = []
            for cost, stt, hist in beam:
                ls = list(stt)
                for j in range(S):
                    se = ls[j]
                    if se[0] == "A" and se[1] == e["node"]:
                        ls[j] = ("D", se[1], se[3], se[3], (), se[2], t, se[7])
                nb.append((cost, tuple(ls), hist))
            beam = nb
            continue
        sig = (e["node"], ty, e["off"], e["len"])
        known = e.get("sid") is not None and e["sid"] in sidx
        cands = [sidx[e["sid"]]] if known else range(S)
        cand = []
        for cost, stt, hist in beam:
            got = False
            for j in cands:
                se = stt[j]
                if se[0] == "P" and ty != "open":
                    continue
                lk[0] = lastknown[j]
                if ty != "open" and sig in se[7]:
                    cand.append((cost + DUP, stt, (k, j, hist)))
                    got = True
                for c, ns in fresh(se, e, t):
                    nsigs = (se[7] | frozenset([sig])) if ty != "open" else se[7]
                    ls = list(stt)
                    ls[j] = ns + (nsigs,)
                    cand.append((cost + c, tuple(ls), (k, j, hist)))
                    got = True
            if not got:
                if known:
                    fb = list(cands)
                else:
                    fb = [j for j in range(S) if stt[j][1] == e["node"] and stt[j][0] != "P"] or \
                         [j for j in range(S) if stt[j][0] != "P"] or list(range(S))
                if fb:
                    cand.append((cost + 25.0, stt, (k, fb[0], hist)))
        if not cand:
            continue
        cand.sort(key=lambda x: x[0])
        nb = []
        seenk = set()
        for c in cand:
            key = tuple(se[:7] for se in c[1])
            if key in seenk:
                continue
            seenk.add(key)
            nb.append(c)
            if len(nb) >= B:
                break
        beam = nb
    cost, stt, hist = beam[0]
    assign = {}
    while hist is not None:
        k, j, hist = hist
        assign[k] = sids[j]
    out_a = {}
    for k in range(nev):
        e = events[k]
        if e.get("sid") is None and e["type"] != "crash":
            out_a[str(e["i"])] = assign.get(k, sids[0] if sids else "")
    smap = {"A": "active", "D": "down", "C": "committed", "X": "aborted", "P": "active"}
    sess = {}
    for j in range(S):
        se = stt[j]
        sess[sids[j]] = {"status": smap[se[0]], "durable": int(se[3])}
    state["output"] = {"assignments": out_a, "sessions": sess}
    return state


def solve(state, params):
