import time
import bisect

GAP = 2.5
MREC = 2.5
JIT = 1.0
JITC = 1.5
FB = 5.0
DUP = 2.0


def _opts(s, typ, en, o, l):
    st, node, off, dur, poff, pnode, gaps, inf = s
    res = []
    if typ == 'open':
        if st == 0:
            res.append((0.0, (1, en, 0, 0, 0, en, (), 0)))
        return res
    if st == 0:
        return res
    if typ == 'write':
        if (st == 1 or st == 5) and node == en:
            if o == off:
                res.append((0.0, (st, node, o + l, dur, poff, pnode, gaps, inf)))
            elif o > off:
                g2 = (gaps + ((off, o),))[-3:]
                res.append((GAP, (st, node, o + l, dur, poff, pnode, g2, inf)))
            else:
                for k, g in enumerate(gaps):
                    if g[0] == o and o + l <= g[1]:
                        if o + l < g[1]:
                            g2 = gaps[:k] + ((o + l, g[1]),) + gaps[k + 1:]
                            res.append((JIT - 0.5 * GAP, (st, node, off, dur, poff, pnode, g2, inf)))
                        else:
                            g2 = gaps[:k] + gaps[k + 1:]
                            res.append((JIT - GAP, (st, node, off, dur, poff, pnode, g2, inf)))
                        break
        if st == 5 and pnode == en and o == dur:
            res.append((JIT, (1, en, o + l, dur, poff, pnode, (), 0)))
        if st == 2:
            if o == dur:
                res.append((MREC, (1, en, o + l, dur, poff, en, (), 1)))
            elif o > dur:
                res.append((MREC + GAP, (1, en, o + l, dur, poff, en, (), 1)))
            if pnode == en and o == poff:
                res.append((JITC, (st, node, off, dur, o + l, pnode, gaps, inf)))
    elif typ == 'checkpoint':
        if (st == 1 or st == 5) and node == en:
            if o == off:
                res.append((0.0, (st, node, off, o, poff, pnode, gaps, inf)))
            elif o > off:
                res.append((GAP, (st, node, o, o, poff, pnode, (), inf)))
            elif o >= dur:
                res.append((JIT + 0.5, (st, node, off, o, poff, pnode, gaps, inf)))
        if st == 2:
            if pnode == en and o == poff:
                res.append((JITC, (2, node, o, o, o, pnode, (), 0)))
            if o == dur:
                res.append((MREC, (1, en, o, o, poff, en, (), 1)))
            elif o > dur:
                res.append((MREC + GAP, (1, en, o, o, poff, en, (), 1)))
    elif typ == 'commit':
        if (st == 1 or st == 5) and node == en:
            if o == off:
                res.append((0.0, (3, node, o, o, poff, pnode, (), 0)))
            elif o > off:
                res.append((GAP, (3, node, o, o, poff, pnode, (), 0)))
        if st == 5 and pnode == en and o == dur:
            res.append((JIT, (3, en, o, o, poff, pnode, (), 0)))
        if st == 2:
            if pnode == en and o == poff:
                res.append((JITC, (3, node, o, o, o, pnode, (), 0)))
            if o == dur:
                res.append((MREC, (3, en, o, o, poff, en, (), 0)))
            elif o > dur:
                res.append((MREC + GAP, (3, en, o, o, poff, en, (), 0)))
    elif typ == 'abort':
        if (st == 1 or st == 5) and node == en:
            res.append((0.2, (4, node, dur, dur, poff, pnode, (), 0)))
        if st == 2:
            if pnode == en:
                res.append((JITC, (4, node, dur, dur, poff, pnode, (), 0)))
            res.append((MREC, (4, en, dur, dur, poff, en, (), 0)))
    elif typ == 'recover':
        if st == 2:
            if o == dur:
                res.append((0.0, (1, en, o, o, poff, en, (), 0)))
            elif o > dur:
                res.append((GAP, (1, en, o, o, poff, en, (), 0)))
            else:
                res.append((GAP + 1.0, (1, en, o, o, poff, en, (), 0)))
        elif st == 1:
            if inf and node == en and o == dur:
                res.append((JIT - MREC, (1, node, off, dur, poff, pnode, gaps, 0)))
            elif o == dur and not inf:
                res.append((JIT + 1.0, (5, node, off, dur, poff, en, gaps, 0)))
    if not res and (node == en or pnode == en):
        res.append((FB, None))
    return res


def solve(state, params):
    t0 = time.process_time()
    inp = state.get("input") or {}
    evs = sorted(inp.get("events", []) or [], key=lambda e: (e.get("t", 0) or 0, e.get("i", 0) or 0))
    sids = []
    for e in evs:
        if e.get("type") == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in evs:
        s = e.get("sid")
        if s is not None and s not in sids:
            sids.append(s)
    sidx = {s: k for k, s in enumerate(sids)}
    n = len(evs)
    NS = len(sids)

    # duplicate-original candidates
    sig_prev = {}
    dupcand = [[] for _ in range(n)]
    is_orig = [False] * n
    last_ref = [-1] * n
    # look-ahead index: (node, off) -> positions of write/checkpoint/commit events
    cont = {}
    last_known = [-1] * NS
    for p, e in enumerate(evs):
        typ = e.get("type")
        s = e.get("sid")
        if s is not None and s in sidx and typ != "open":
            last_known[sidx[s]] = p
        if typ in ("write", "checkpoint", "commit"):
            cont.setdefault((e.get("node"), e.get("off")), []).append(p)
        if typ in ("crash", "open"):
            continue
        sig = (typ, e.get("node"), e.get("off"), e.get("len"))
        lst = sig_prev.get(sig)
        if lst:
            dupcand[p] = lst[-4:]
            for q in dupcand[p]:
                is_orig[q] = True
                last_ref[q] = p
        sig_prev.setdefault(sig, []).append(p)

    def abort_pen(p, k, s):
        pen = 0.0
        if last_known[k] > p + 2:
            pen += 3.0
        lst = cont.get((s[1], s[2]))
        if lst:
            j = bisect.bisect_right(lst, p)
            while j < len(lst):
                sd = evs[lst[j]].get("sid")
                if sd is None or sd == sids[k]:
                    pen += 2.5
                    break
                j += 1
        return pen

    init_s = tuple((0, None, 0, 0, 0, None, (), 0) for _ in range(NS))
    beam = [(0.0, init_s, (), None)]
    B = 48
    budget = 0.8
    for p, e in enumerate(evs):
        typ = e.get("type")
        en = e.get("node")
        o = e.get("off")
        l = e.get("len") or 0
        if o is None:
            o = 0
        if typ == "crash":
            nb = []
            for (c, ss, memo, path) in beam:
                lst = list(ss)
                ch = False
                for k, s in enumerate(lst):
                    if s[1] == en:
                        if s[0] == 1:
                            lst[k] = (2, en, s[3], s[3], s[2], en, (), 0)
                            ch = True
                        elif s[0] == 5:
                            lst[k] = (1, s[5], s[3], s[3], s[4], s[5], (), 0)
                            ch = True
                nb.append((c, tuple(lst) if ch else ss, memo, path))
            beam = nb
            continue
        known = e.get("sid")
        if known is not None and known in sidx:
            cands = [sidx[known]]
        else:
            known = None
            cands = list(range(NS))
        nxt = {}
        order = []
        for (c, ss, memo, path) in beam:
            if memo:
                memo = tuple(m for m in memo if last_ref[m[0]] >= p)
            exp = []
            for k in cands:
                for (dc, ns) in _opts(ss[k], typ, en, o, l):
                    if ns is None:
                        exp.append((c + dc, ss, k))
                    else:
                        if typ == "abort" and known is None:
                            dc += abort_pen(p, k, ss[k])
                        exp.append((c + dc, ss[:k] + (ns,) + ss[k + 1:], k))
            if dupcand[p] and memo:
                md = dict(memo)
                for q in dupcand[p]:
                    if q in md:
                        k = md[q]
                        if known is None or sidx[known] == k:
                            exp.append((c + DUP, ss, k))
            if not exp:
                k = cands[0] if (known is not None and cands) else -1
                exp.append((c + FB * 2, ss, k))
            for (nc, nss, k) in exp:
                nm = memo
                if is_orig[p] and k >= 0:
                    nm = memo + ((p, k),)
                key = (nss, nm)
                old = nxt.get(key)
                if old is None or nc < old[0]:
                    if old is None:
                        order.append(key)
                    nxt[key] = (nc, nss, nm, (p, k, path))
        cand = [nxt[k] for k in order]
        cand.sort(key=lambda x: x[0])
        el = time.process_time() - t0
        rem = n - p
        if el > budget:
            B = 1
        elif p > 10:
            per = el / (p + 1)
            if per * rem > (budget - el):
                B = max(2, int(B * 0.7))
        if cand:
            beam = cand[:B]

    best = beam[0]
    asg = {}
    path = best[3]
    while path is not None:
        p, k, path = path
        if k >= 0:
            asg[p] = sids[k]
    assignments = {}
    for p, e in enumerate(evs):
        if e.get("type") != "crash" and e.get("sid") is None:
            s = asg.get(p)
            if s is None:
                s = sids[0] if sids else ""
            assignments[str(e.get("i"))] = s
    sessions = {}
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted", 5: "active"}
    for k, s in enumerate(sids):
        st = best[1][k]
        sessions[s] = {"status": names[st[0]], "durable": int(st[3])}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state

import time


def solve(state, params):
    t0 = time.process_time()
    inp = state.get("input") or {}
    evs = sorted(inp.get("events") or [], key=lambda e: (e.get("t") or 0, e.get("i") or 0))
    node_ids = {}
    for nm in inp.get("nodes") or []:
        node_ids.setdefault(nm, len(node_ids))
    sids = []
    sidx = {}
    for e in evs:
        node_ids.setdefault(e.get("node"), len(node_ids))
        s = e.get("sid")
        if s is not None and s not in sidx:
            sidx[s] = len(sids)
            sids.append(s)
    NS = len(sids)
    E = []
    for e in evs:
        typ = e.get("type")
        off = e.get("off")
        ln = e.get("len")
        E.append((e.get("i"), e.get("t") or 0, node_ids[e.get("node")], typ,
                  off if isinstance(off, int) else 0, ln if isinstance(ln, int) else 0,
                  sidx.get(e.get("sid"), -1)))
    n = len(E)

    # ---- duplicate candidates
    sigs = {}
    P = [()] * n
    Dset = set()
    for k in range(n):
        i, t, nd, typ, off, ln, sk = E[k]
        if typ in ("open", "crash"):
            continue
        key = (nd, typ, off, ln)
        prev = sigs.get(key)
        if prev:
            cand = []
            for p in reversed(prev):
                psk = E[p][6]
                if sk >= 0 and psk >= 0 and psk != sk:
                    continue
                cand.append(p)
                if len(cand) >= 3:
                    break
            if cand:
                P[k] = tuple(cand)
                for p in cand:
                    Dset.add(p)
            prev.append(k)
        else:
            sigs[key] = [k]

    # ---- jitter window estimate from sid-known events (ignoring possible duplicates)
    byS = {}
    for k in range(n):
        i, t, nd, typ, off, ln, sk = E[k]
        if sk >= 0 and typ in ("write", "checkpoint", "commit") and not P[k]:
            byS.setdefault(sk, []).append((off, t))
    maxinv = 0
    for lst in byS.values():
        for a in range(len(lst)):
            for b in range(a + 1, min(len(lst), a + 8)):
                if lst[b][0] < lst[a][0]:
                    maxinv = max(maxinv, lst[b][1] - lst[a][1])
    if n > 1:
        avg = (E[-1][1] - E[0][1]) / max(1, n - 1)
    else:
        avg = 1.0
    W = max(2.0 * maxinv, 3.0 * avg, 3.0)

    CG = 3.0     # missing write / checkpoint (gap)
    CR = 3.5     # missing recover
    CD = 0.7     # duplicate
    BIG = 40.0

    def addb(b, x):
        if len(b) >= 5:
            b = b[1:]
        return b + (x,)

    def addgap(g, a, b):
        if len(g) >= 4:
            g = g[1:]
        return g + ((a, b),)

    def fillgap(g, a, b):
        for j in range(len(g)):
            x, y = g[j]
            if x <= a and b <= y:
                ng = list(g[:j])
                if x < a:
                    ng.append((x, a))
                if b < y:
                    ng.append((b, y))
                ng.extend(g[j + 1:])
                return tuple(ng)
        return None

    def late_pen(t, ct):
        d = t - ct - W
        return 0.3 * d if d > 0 else 0.0

    # session tuple: (st, node, stream, dur, pre, cn, ct, gaps, bounds, origs, skipnode, skipt)
    # st: 0 unopened, 1 active, 2 down, 3 committed, 4 aborted
    def trans(s, typ, N, off, ln, t):
        st = s[0]
        out = []
        if st == 1:
            same = s[1] == N
            cur = s[2]
            if typ == "write":
                end = off + ln
                if same:
                    if off == cur:
                        out.append((0.0, (1, N, end, s[3], s[4], s[5], s[6], s[7], addb(s[8], end), s[9], s[10], s[11])))
                    elif off > cur:
                        out.append((CG, (1, N, end, s[3], s[4], s[5], s[6], addgap(s[7], cur, off), addb(s[8], end), s[9], s[10], s[11])))
                    elif end <= cur:
                        g = fillgap(s[7], off, end)
                        if g is not None:
                            out.append((1.0 - CG, (1, N, cur, s[3], s[4], s[5], s[6], g, s[8], s[9], s[10], s[11])))
                        else:
                            out.append((4.0, s))
                    else:
                        out.append((20.0, (1, N, end, s[3], s[4], s[5], s[6], s[7], addb(s[8], end), s[9], s[10], s[11])))
                elif s[5] == N and off <= s[4] and t <= s[6] + 2 * W:
                    out.append((4.0, s))
            elif typ == "checkpoint":
                if same:
                    if off == cur:
                        out.append((0.0, (1, N, cur, off, s[4], s[5], s[6], s[7], s[8], s[9], s[10], s[11])))
                    elif off > cur:
                        out.append((CG, (1, N, off, off, s[4], s[5], s[6], addgap(s[7], cur, off), addb(s[8], off), s[9], s[10], s[11])))
                    else:
                        c = 1.5 if off in s[8] else 4.5
                        out.append((c, (1, N, cur, max(s[3], off), s[4], s[5], s[6], s[7], s[8], s[9], s[10], s[11])))
                elif s[5] == N and off <= s[4] and t <= s[6] + 2 * W:
                    out.append((4.0, s))
            elif typ == "commit":
                if same:
                    if off == cur:
                        c = 0.0
                    elif off > cur:
                        c = CG
                    else:
                        c = 8.0
                    out.append((c, (3, N, off, off, s[4], s[5], s[6], (), s[8], s[9], -1, 0)))
            elif typ == "abort":
                if same:
                    out.append((0.0, (4, N, s[3], s[3], s[4], s[5], s[6], (), s[8], s[9], -1, 0)))
            elif typ == "recover":
                c = 8.0 + (0.0 if off == s[3] else CG)
                out.append((c, (1, N, off, off, s[4], s[5], s[6], (), (off,), s[9], s[1], t)))
        elif st == 2:
            dur = s[3]
            pre = s[4]
            lateok = (N == s[5])
            lp = late_pen(t, s[6]) if lateok else 0.0
            if typ == "write":
                end = off + ln
                if lateok:
                    if off == pre:
                        out.append((1.0 + lp, (2, s[1], dur, dur, end, s[5], s[6], s[7], s[8], s[9], s[10], s[11])))
                    elif end <= pre:
                        out.append((3.0 + lp, s))
                if off == dur:
                    out.append((CR, (1, N, end, dur, pre, s[5], s[6], (), (dur, end), s[9], -1, 0)))
                elif off > dur:
                    out.append((CR + CG, (1, N, end, dur, pre, s[5], s[6], ((dur, off),), (dur, end), s[9], -1, 0)))
            elif typ == "checkpoint":
                if lateok and dur <= off <= pre:
                    c = (1.0 if off == pre else 2.5) + lp
                    out.append((c, (2, s[1], off, off, pre, s[5], s[6], s[7], s[8], s[9], s[10], s[11])))
                if off >= dur:
                    c = CR + (CG if off > dur else 0.0)
                    out.append((c, (1, N, off, off, pre, s[5], s[6], (), (off,), s[9], -1, 0)))
            elif typ == "commit":
                if off >= dur:
                    best = None
                    if lateok:
                        best = 1.5 + lp + (0.0 if off == pre else (CG if off > pre else 6.0))
                    c2 = CR + (CG if off > dur else 0.0)
                    if best is None or c2 < best:
                        best = c2
                    out.append((best, (3, N, off, off, pre, s[5], s[6], (), (), s[9], -1, 0)))
            elif typ == "abort":
                c = CR
                if lateok:
                    c = min(c, 1.5 + lp)
                out.append((c, (4, N, dur, dur, pre, s[5], s[6], (), (), s[9], -1, 0)))
            elif typ == "recover":
                if off == dur:
                    c = 0.0
                elif off > dur:
                    c = CG
                else:
                    c = 10.0
                out.append((c, (1, N, off, off, pre, s[5], s[6], (), (off,), s[9], -1, 0)))
        elif st == 3:
            if s[1] == N:
                if typ == "write" and off + ln <= s[2]:
                    out.append((3.0, s))
                elif typ == "checkpoint" and off <= s[2]:
                    out.append((3.0, s))
                elif typ == "abort":
                    out.append((12.0, s))
        elif st == 4:
            if s[1] == N and typ in ("write", "checkpoint"):
                out.append((4.0, s))
        return out

    init = tuple((0, -1, 0, 0, 0, -1, 0, (), (0,), (), -1, 0) for _ in range(NS))
    beams = [(0.0, init, None)]
    K = 20
    KMAX = 32
    budget = 0.6
    for k in range(n):
        i, t, N, typ, off, ln, sk = E[k]
        el = time.process_time() - t0
        frac = (k + 1) / n
        if el > budget * 0.15 and el / frac > budget:
            K = max(2, K * 2 // 3)
        elif el / frac < budget * 0.4 and K < KMAX:
            K += 1
        if el > budget * 1.3:
            K = 1
        if typ == "crash":
            nb = []
            for cost, ss, h in beams:
                lst = list(ss)
                ch = False
                for j in range(NS):
                    s = lst[j]
                    if s[0] == 1 and s[1] == N:
                        if s[10] == N and t <= s[11] + 3 * W:
                            lst[j] = s[:10] + (-1, 0)
                        else:
                            g = tuple(x for x in s[7] if x[1] <= s[3])
                            lst[j] = (2, N, s[3], s[3], s[2], N, t, g, s[8], s[9], -1, 0)
                        ch = True
                    elif s[0] == 1 and s[10] >= 0 and t > s[11] + 3 * W:
                        lst[j] = s[:10] + (-1, 0)
                        ch = True
                nb.append((cost, tuple(lst) if ch else ss, h))
            beams = nb
            continue
        if typ == "open":
            if sk < 0:
                continue
            nb = []
            for cost, ss, h in beams:
                s = ss[sk]
                if s[0] == 0:
                    ns = (1, N, 0, 0, 0, -1, 0, (), (0,), (k,) if k in Dset else (), -1, 0)
                    nb.append((cost, ss[:sk] + (ns,) + ss[sk + 1:], h))
                else:
                    nb.append((cost + BIG, ss, h))
            beams = nb
            continue
        cand = {}
        isD = k in Dset
        Pk = P[k]
        for cost, ss, h in beams:
            found = False
            rng = (sk,) if sk >= 0 else range(NS)
            for j in rng:
                s = ss[j]
                if s[0] == 0:
                    continue
                if Pk:
                    org = s[9]
                    for p in Pk:
                        if p in org:
                            c = cost + CD
                            old = cand.get(ss)
                            if old is None or c < old[0]:
                                cand[ss] = (c, (k, j, h))
                            found = True
                            break
                st = s[0]
                if st != 2 and s[1] != N and not (st == 1 and (s[5] == N or typ == "recover")):
                    continue
                for c, ns in trans(s, typ, N, off, ln, t):
                    if isD:
                        ns = ns[:9] + (ns[9] + (k,),) + ns[10:]
                    key = ss[:j] + (ns,) + ss[j + 1:]
                    cc = cost + c
                    old = cand.get(key)
                    if old is None or cc < old[0]:
                        cand[key] = (cc, (k, j, h))
                    found = True
            if not found:
                bestj = -1
                bestc = None
                for j in rng:
                    s = ss[j]
                    if s[0] == 0:
                        continue
                    c = 0 if s[1] == N else 1
                    if bestc is None or c < bestc:
                        bestc = c
                        bestj = j
                if bestj < 0 and sk >= 0:
                    bestj = sk
                cc = cost + BIG
                old = cand.get(ss)
                if old is None or cc < old[0]:
                    cand[ss] = (cc, (k, bestj, h) if bestj >= 0 else h)
        if not cand:
            continue
        items = sorted(cand.items(), key=lambda x: x[1][0])[:K]
        beams = [(v[0], key, v[1]) for key, v in items]
    beams.sort(key=lambda b: b[0])
    cost, ss, h = beams[0]
    assign = {}
    while h is not None:
        k, j, h = h
        assign[k] = j

    lastt = [None] * NS
    firstt = [None] * NS
    cnt = [0] * NS
    for k in range(n):
        if E[k][3] == "crash":
            continue
        j = assign.get(k)
        if j is None and E[k][6] >= 0:
            j = E[k][6]
        if j is None:
            continue
        t = E[k][1]
        if firstt[j] is None:
            firstt[j] = t
        lastt[j] = t
        cnt[j] += 1
    tend = E[-1][1] if n else 0
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted"}
    outA = {}
    for k in range(n):
        i, t, N, typ, off, ln, sk = E[k]
        if typ == "crash" or sk >= 0:
            continue
        j = assign.get(k)
        if j is None or j < 0:
            j = 0
        if NS:
            outA[str(i)] = sids[j]
    outS = {}
    for j in range(NS):
        s = ss[j]
        st = s[0]
        status = names[st]
        if st == 1 and lastt[j] is not None and cnt[j] >= 4:
            gap = (lastt[j] - firstt[j]) / max(1, cnt[j] - 1)
            if tend - lastt[j] > max(8.0 * gap, 10.0 * W, 12.0 * avg):
                status = "aborted"
        outS[sids[j]] = {"status": status, "durable": int(s[3])}
    state["output"] = {"assignments": outA, "sessions": outS}
    return state

import time


def _fallback(state):
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    lastnode = {}
    status = {s: "active" for s in sids}
    dur = {s: 0 for s in sids}
    out_a = {}
    for e in events:
        if e["type"] == "crash":
            continue
        s = e.get("sid")
        if s is None:
            s = lastnode.get(e["node"], sids[0] if sids else "")
            out_a[str(e["i"])] = s
        if s in status:
            lastnode[e["node"]] = s
            if e["type"] == "commit":
                status[s] = "committed"
                if e["off"] is not None:
                    dur[s] = e["off"]
            elif e["type"] == "abort":
                status[s] = "aborted"
            elif e["type"] in ("checkpoint", "recover") and e["off"] is not None:
                dur[s] = max(dur[s], e["off"])
    state["output"] = {"assignments": out_a,
                       "sessions": {s: {"status": status[s], "durable": int(dur[s])} for s in sids}}
    return state


def _prep(inp):
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e["type"] == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    sidx = {s: k for k, s in enumerate(sids)}
    ts = [e["t"] for e in events]
    gaps = sorted(ts[k + 1] - ts[k] for k in range(len(ts) - 1)) or [1]
    med = gaps[len(gaps) // 2]
    W = max(4.0, 3.0 * max(med, 1))
    seen = {}
    posdup = [False] * len(events)
    for k, e in enumerate(events):
        if e["type"] in ("open", "crash"):
            continue
        sig = (e["node"], e["type"], e["off"], e["len"])
        if sig in seen:
            posdup[k] = True
        seen[sig] = k
    lastknown = [-10 ** 9] * len(sids)
    for k, e in enumerate(events):
        if e.get("sid") is not None and e["type"] != "open" and not posdup[k]:
            j = sidx[e["sid"]]
            if e["t"] > lastknown[j]:
                lastknown[j] = e["t"]
    return events, sids, sidx, W, lastknown


def _make_fresh(W):
    GAP, BAD, REC, DUP, LATE, UNC = 2.0, 9.0, 3.0, 1.6, 1.0, 3.5
    FILL = -1.0
    lk = [0]

    def fresh(se, e, t):
        ty = e["type"]; nd = e["node"]; o = e["off"]; ln = e["len"]
        st, node, pos, dur, holes, pre, tc = se[0], se[1], se[2], se[3], se[4], se[5], se[6]
        res = []
        if st == "P":
            if ty == "open":
                res.append((0.0, ("A", nd, 0, 0, (), 0, 0)))
            return res
        if ty == "open":
            return res
        if ty == "write":
            if o is None or ln is None:
                return res
            end = o + ln
            if st == "A":
                if node != nd:
                    return res
                if o == pos:
                    res.append((0.0, ("A", node, end, dur, holes, pre, tc)))
                elif o > pos:
                    res.append((GAP, ("A", node, end, dur, holes + ((pos, o),), pre, tc)))
                else:
                    done = False
                    for hk in range(len(holes)):
                        a, b = holes[hk]
                        if a <= o and end <= b:
                            nh = list(holes[:hk])
                            if a < o:
                                nh.append((a, o))
                            if end < b:
                                nh.append((end, b))
                            nh.extend(holes[hk + 1:])
                            c = FILL if a == o else 0.5
                            res.append((c, ("A", node, pos, dur, tuple(nh), pre, tc)))
                            done = True
                            break
                    if not done:
                        if o >= dur:
                            res.append((BAD, ("A", node, end, dur, (), pre, tc)))
                        else:
                            res.append((BAD + 2, ("A", node, end, dur, (), pre, tc)))
            elif st == "D":
                if o == dur:
                    res.append((REC, ("A", nd, end, dur, (), pre, tc)))
                elif o > dur:
                    res.append((REC + GAP + 1, ("A", nd, end, dur, ((dur, o),), pre, tc)))
                if node == nd and o == pre and o != dur:
                    dt = max(0.0, t - tc)
                    res.append((LATE + dt / W, ("D", node, pos, dur, holes, end, tc)))
                    res.append((UNC, ("A", node, end, dur, (), pre, tc)))
            else:
                if node == nd:
                    for (a, b) in holes:
                        if a <= o and end <= b:
                            res.append((0.5 if a == o else 1.0, se[:7]))
                            break
            return res
        if ty == "checkpoint" or ty == "commit":
            if o is None:
                return res
            nst = "C" if ty == "commit" else "A"
            if st == "A":
                if node != nd:
                    return res
                if o == pos:
                    res.append((0.0, (nst, node, o, o, holes, pre, tc)))
                elif o > pos:
                    res.append((GAP, (nst, node, o, o, holes + ((pos, o),), pre, tc)))
                elif o >= dur:
                    if ty == "commit":
                        res.append((LATE + 1, (nst, node, o, o, (), pre, tc)))
                    else:
                        res.append((LATE, ("A", node, pos, o, holes, pre, tc)))
                else:
                    res.append((BAD, (nst, node, o, o, (), pre, tc)))
            elif st == "D":
                if node == nd and dur <= o <= pre:
                    dt = max(0.0, t - tc)
                    if ty == "commit":
                        res.append((LATE + dt / W, ("C", node, o, o, (), pre, tc)))
                    else:
                        res.append((LATE + dt / W, ("D", node, o, o, (), pre, tc)))
                if o == dur:
                    res.append((REC + 0.5, (nst, nd, o, o, (), pre, tc)))
                elif o > dur:
                    res.append((REC + GAP + 1, (nst, nd, o, o, (), pre, tc)))
            else:
                if node == nd and o <= pos:
                    if st == "X" and o > dur:
                        res.append((LATE + 0.5, ("X", node, pos, o, holes, pre, tc)))
                    else:
                        res.append((LATE + 0.5, se[:7]))
                elif node == nd and st == "C" and ty == "checkpoint":
                    for (a, b) in holes:
                        if a < o <= b:
                            res.append((LATE + 1, se[:7]))
                            break
            return res
        if ty == "abort":
            pen = 6.0 if lk[0] > t + W else 0.0
            if st == "A" and node == nd:
                res.append((0.3 + pen, ("X", node, dur, dur, (), pre, tc)))
            elif st == "D":
                if node == nd:
                    res.append((LATE + max(0.0, t - tc) / W + pen, ("X", node, dur, dur, (), pre, tc)))
                res.append((REC + 1 + pen, ("X", nd, dur, dur, (), pre, tc)))
            return res
        if ty == "recover":
            if o is None:
                return res
            if st == "D":
                if o == dur:
                    res.append((0.0, ("A", nd, o, o, (), pre, tc)))
                elif dur < o <= pre:
                    res.append((GAP, ("A", nd, o, o, (), pre, tc)))
                else:
                    res.append((BAD - 2, ("A", nd, o, max(o, dur), (), pre, tc)))
            elif st == "A":
                if node == nd and o == dur and pos >= o:
                    res.append((1.0, se[:7]))
                else:
                    res.append((REC + 1.5, ("A", nd, o, max(o, dur), (), pos, t)))
            return res
        return res

    return fresh, lk


def _core(state):
    t0 = time.process_time()
    state["_t0"] = t0
    inp = state["input"]
    events, sids, sidx, W, lastknown = _prep(inp)
    S = len(sids)
    fresh, lk = _make_fresh(W)
    DUP = 1.6
    init = tuple(("P", None, 0, 0, (), 0, 0, frozenset()) for _ in range(S))
    beam = [(0.0, init, None)]
    nev = len(events)
    B = 24 if nev <= 200 else 16
    budget = 0.42
    for k in range(nev):
        e = events[k]
        ty = e["type"]; t = e["t"]
        el = time.process_time() - t0
        if k > 10 and B > 1 and el > budget * (float(k) / nev) * 1.1:
            B = max(1, B // 2)
        if el > 0.6:
            B = 1
        if ty == "crash":
            nb = []
            for cost, stt, hist in beam:
                ls = list(stt)
                for j in range(S):
                    se = ls[j]
                    if se[0] == "A" and se[1] == e["node"]:
                        ls[j] = ("D", se[1], se[3], se[3], (), se[2], t, se[7])
                nb.append((cost, tuple(ls), hist))
            beam = nb
            continue
        sig = (e["node"], ty, e["off"], e["len"])
        known = e.get("sid") is not None and e["sid"] in sidx
        cands = [sidx[e["sid"]]] if known else range(S)
        cand = []
        for cost, stt, hist in beam:
            got = False
            for j in cands:
                se = stt[j]
                if se[0] == "P" and ty != "open":
                    continue
                lk[0] = lastknown[j]
                if ty != "open" and sig in se[7]:
                    cand.append((cost + DUP, stt, (k, j, hist)))
                    got = True
                for c, ns in fresh(se, e, t):
                    nsigs = (se[7] | frozenset([sig])) if ty != "open" else se[7]
                    ls = list(stt)
                    ls[j] = ns + (nsigs,)
                    cand.append((cost + c, tuple(ls), (k, j, hist)))
                    got = True
            if not got:
                if known:
                    fb = list(cands)
                else:
                    fb = [j for j in range(S) if stt[j][1] == e["node"] and stt[j][0] != "P"] or \
                         [j for j in range(S) if stt[j][0] != "P"] or list(range(S))
                if fb:
                    cand.append((cost + 25.0, stt, (k, fb[0], hist)))
        if not cand:
            continue
        cand.sort(key=lambda x: x[0])
        nb = []
        seenk = set()
        for c in cand:
            key = tuple(se[:7] for se in c[1])
            if key in seenk:
                continue
            seenk.add(key)
            nb.append(c)
            if len(nb) >= B:
                break
        beam = nb
    cost, stt, hist = beam[0]
    assign = {}
    while hist is not None:
        k, j, hist = hist
        assign[k] = sids[j]
    out_a = {}
    for k in range(nev):
        e = events[k]
        if e.get("sid") is None and e["type"] != "crash":
            out_a[str(e["i"])] = assign.get(k, sids[0] if sids else "")
    smap = {"A": "active", "D": "down", "C": "committed", "X": "aborted", "P": "active"}
    sess = {}
    for j in range(S):
        se = stt[j]
        sess[sids[j]] = {"status": smap[se[0]], "durable": int(se[3])}
    state["output"] = {"assignments": out_a, "sessions": sess}
    state["_ba"] = [(sidx[assign[k]] if k in assign else -1) for k in range(nev)]
    return state


def _sim(ks, crashes, events, fresh, lk, lkj, WID, need_inc):
    DUP = 1.6
    merged = []
    a = 0
    b = 0
    while a < len(ks) or b < len(crashes):
        if b >= len(crashes) or (a < len(ks) and ks[a] < crashes[b]):
            merged.append(ks[a]); a += 1
        else:
            merged.append(crashes[b]); b += 1
    beam = [(0.0, ("P", None, 0, 0, (), 0, 0, frozenset()))]
    incs = {}
    lk[0] = lkj
    for k in merged:
        e = events[k]
        ty = e["type"]; t = e["t"]
        if ty == "crash":
            nb = []
            for cost, se in beam:
                if se[0] == "A" and se[1] == e["node"]:
                    se = ("D", se[1], se[3], se[3], (), se[2], t, se[7])
                nb.append((cost, se))
            beam = nb
            continue
        sig = (e["node"], ty, e["off"], e["len"])
        cand = []
        for cost, se in beam:
            if se[0] == "P" and ty != "open":
                continue
            if ty != "open" and sig in se[7]:
                cand.append((cost + DUP, se))
            for c, ns in fresh(se, e, t):
                nsigs = (se[7] | frozenset([sig])) if ty != "open" else se[7]
                cand.append((cost + c, ns + (nsigs,)))
        if not cand:
            cand = [(cost + 25.0, se) for cost, se in beam]
        cand.sort(key=lambda x: x[0])
        if need_inc:
            incs[k] = cand[0][0] - beam[0][0]
        nb = []
        seenk = set()
        for c in cand:
            key = c[1][:7]
            if key in seenk:
                continue
            seenk.add(key)
            nb.append(c)
            if len(nb) >= WID:
                break
        beam = nb
    return beam[0][0], beam[0][1], incs


def _refine_core(state):
    if "_ba" not in state:
        return state
    t0 = state.get("_t0", time.process_time())
    deadline = t0 + 0.8
    inp = state["input"]
    events, sids, sidx, W, lastknown = _prep(inp)
    S = len(sids)
    if S == 0:
        return state
    fresh, lk = _make_fresh(W)
    nev = len(events)
    A = list(state["_ba"])
    if len(A) != nev:
        return state
    fixed = [False] * nev
    crashes = []
    for k, e in enumerate(events):
        if e["type"] == "crash":
            crashes.append(k); A[k] = -1
            continue
        if e.get("sid") is not None and e["sid"] in sidx:
            A[k] = sidx[e["sid"]]; fixed[k] = True
        elif A[k] < 0:
            A[k] = 0
    WID = 6
    members = [[] for _ in range(S)]
    for k in range(nev):
        if A[k] >= 0:
            members[A[k]].append(k)
    opent = [None] * S
    for k, e in enumerate(events):
        if e["type"] == "open" and e.get("sid") in sidx and opent[sidx[e["sid"]]] is None:
            opent[sidx[e["sid"]]] = e["t"]
    sigof = [(e["node"], e["type"], e["off"], e["len"]) for e in events]
    cost = [0.0] * S
    best = [None] * S
    incs = [None] * S
    for j in range(S):
        c, b, inc = _sim(members[j], crashes, events, fresh, lk, lastknown[j], WID, True)
        cost[j] = c; best[j] = b; incs[j] = inc
    if time.process_time() > deadline:
        return _emit(state, events, sids, A, best)
    tried = set()
    for it in range(6):
        sus = set()
        for j in range(S):
            for k, v in incs[j].items():
                if v > 0.25:
                    sus.add(k)
        cand = set()
        for k in sus:
            tk = events[k]["t"]; nd = events[k]["node"]
            lo = k
            while lo > 0 and events[lo - 1]["t"] >= tk - 2 * W:
                lo -= 1
            hi = k
            while hi + 1 < nev and events[hi + 1]["t"] <= tk + 2 * W:
                hi += 1
            for m in range(lo, hi + 1):
                if not fixed[m] and A[m] >= 0 and events[m]["node"] == nd and events[m]["type"] != "open":
                    cand.add(m)
        improved = False
        for m in sorted(cand):
            if time.process_time() > deadline:
                break
            a = A[m]
            key = (m, a, tuple(cost))
            if key in tried:
                continue
            tried.add(key)
            group = [x for x in members[a] if not fixed[x] and sigof[x] == sigof[m]]
            gs = set(group)
            rest = [x for x in members[a] if x not in gs]
            ca, ba_, ia = _sim(rest, crashes, events, fresh, lk, lastknown[a], WID, True)
            tm = events[m]["t"]
            bestd = -0.05
            bestb = None
            for b in range(S):
                if b == a:
                    continue
                if opent[b] is None or opent[b] > tm:
                    continue
                nm = sorted(members[b] + group)
                cb, bb, ib = _sim(nm, crashes, events, fresh, lk, lastknown[b], WID, True)
                d = ca + cb - cost[a] - cost[b]
                if d < bestd:
                    bestd = d; bestb = (b, nm, cb, bb, ib)
                if time.process_time() > deadline:
                    break
            if bestb is None and time.process_time() < deadline:
                nd = events[m]["node"]
                for x in range(nev):
                    if abs(events[x]["t"] - tm) > 2 * W:
                        continue
                    if fixed[x] or A[x] < 0 or A[x] == a or events[x]["node"] != nd or events[x]["type"] == "open":
                        continue
                    b = A[x]
                    if opent[b] is None or opent[b] > tm or opent[a] is None or opent[a] > events[x]["t"]:
                        continue
                    xa = sorted(rest + [x])
                    xb = sorted([y for y in members[b] if y != x] + group)
                    c1, b1, i1 = _sim(xa, crashes, events, fresh, lk, lastknown[a], WID, True)
                    c2, b2, i2 = _sim(xb, crashes, events, fresh, lk, lastknown[b], WID, True)
                    d = c1 + c2 - cost[a] - cost[b]
                    if d < bestd:
                        bestd = d
                        members[a] = xa; cost[a] = c1; best[a] = b1; incs[a] = i1
                        members[b] = xb; cost[b] = c2; best[b] = b2; incs[b] = i2
                        for y in group:
                            A[y] = b
                        A[x] = a
                        improved = True
                        break
                    if time.process_time() > deadline:
                        break
            if bestb is not None:
                b, nm, cb, bb, ib = bestb
                members[a] = rest; cost[a] = ca; best[a] = ba_; incs[a] = ia
                members[b] = nm; cost[b] = cb; best[b] = bb; incs[b] = ib
                for x in group:
                    A[x] = b
                improved = True
        if not improved or time.process_time() > deadline:
            break
    return _emit(state, events, sids, A, best)


def _emit(state, events, sids, A, best):
    out_a = {}
    for k, e in enumerate(events):
        if e.get("sid") is None and e["type"] != "crash":
            j = A[k] if A[k] >= 0 else 0
            out_a[str(e["i"])] = sids[j]
    smap = {"A": "active", "D": "down", "C": "committed", "X": "aborted", "P": "active"}
    sess = {}
    for j in range(len(sids)):
        se = best[j]
        sess[sids[j]] = {"status": smap[se[0]], "durable": int(se[3])}
    state["output"] = {"assignments": out_a, "sessions": sess}
    return state


def solve(state, params):
    try:
        return _core(state)
    except Exception:
        return _fallback(state)


def refine(state, params):
    keep = state.get("output")
    try:
        state = _refine_core(state)
    except Exception:
        state["output"] = keep
    for k in ("_ba", "_t0"):
        if k in state:
            state.pop(k)
    return state

import time
import bisect

GAP = 2.0
BAD = 9.0
REC = 3.0
DUP = 1.8
LATE = 1.0
UNC = 3.5
FILL = -1.0
JIT = 1.0
FB = 6.0

# session: (st, node, pos, dur, holes, pre, tc, inf, pn)
# st: 0 pending, 1 active, 2 down, 3 committed, 4 aborted, 5 active w/ pending recover to pn


def _opts(s, typ, en, o, l, t, W, pen):
    st, node, pos, dur, holes, pre, tc, inf, pn = s
    res = []
    if typ == 'open':
        if st == 0:
            res.append((0.0, (1, en, 0, 0, (), 0, 0, 0, None)))
        return res
    if st == 0:
        return res
    act = (st == 1 or st == 5)
    dt = max(0.0, t - tc) / W if st == 2 else 0.0
    if typ == 'write':
        end = o + l
        if act and node == en:
            if o == pos:
                res.append((0.0, (st, node, end, dur, holes, pre, tc, inf, pn)))
            elif o > pos:
                res.append((GAP, (st, node, end, dur, (holes + ((pos, o),))[-4:], pre, tc, inf, pn)))
            else:
                hit = False
                for hk in range(len(holes)):
                    a, b = holes[hk]
                    if a <= o and end <= b:
                        nh = list(holes[:hk])
                        if a < o:
                            nh.append((a, o))
                        if end < b:
                            nh.append((end, b))
                        nh.extend(holes[hk + 1:])
                        res.append((FILL if a == o else 0.5,
                                    (st, node, pos, dur, tuple(nh), pre, tc, inf, pn)))
                        hit = True
                        break
                if not hit:
                    res.append((BAD if o >= dur else BAD + 2,
                                (st, node, end, dur, (), pre, tc, inf, pn)))
        if st == 5 and pn == en and o == dur:
            res.append((JIT, (1, en, end, dur, (), pre, tc, 0, None)))
        if st == 2:
            if o == dur:
                res.append((REC, (1, en, end, dur, (), pre, tc, 1, None)))
            elif o > dur:
                res.append((REC + GAP + 1, (1, en, end, dur, ((dur, o),), pre, tc, 1, None)))
            if node == en and o != dur:
                if o == pre:
                    res.append((LATE + dt, (2, node, pos, dur, (), end, tc, 0, None)))
                    res.append((UNC, (1, node, end, dur, (), pre, tc, 0, None)))
                elif dur < o and end <= pre:
                    res.append((LATE + 0.5 + dt, s))
        if (st == 3 or st == 4) and node == en:
            for (a, b) in holes:
                if a <= o and end <= b:
                    res.append((0.5 if a == o else 1.0, s))
                    break
    elif typ == 'checkpoint' or typ == 'commit':
        com = (typ == 'commit')
        if act and node == en:
            nst = 3 if com else st
            npn = pn if nst == 5 else None
            ninf = 0 if com else inf
            if o == pos:
                res.append((0.0, (nst, node, o, o, holes, pre, tc, ninf, npn)))
            elif o > pos:
                res.append((GAP, (nst, node, o, o, (holes + ((pos, o),))[-4:], pre, tc, ninf, npn)))
            elif o >= dur:
                if com:
                    res.append((LATE + 1, (3, node, o, o, (), pre, tc, 0, None)))
                else:
                    res.append((LATE, (st, node, pos, o, holes, pre, tc, inf, pn)))
            else:
                res.append((BAD, (nst, node, o, o, (), pre, tc, ninf, npn)))
        if st == 5 and pn == en and o == dur:
            res.append((JIT, (3 if com else 1, en, o, o, (), pre, tc, 0, None)))
        if st == 2:
            if node == en and dur <= o <= pre:
                if com:
                    res.append((LATE + dt, (3, node, o, o, (), pre, tc, 0, None)))
                else:
                    res.append((LATE + dt, (2, node, o, o, (), pre, tc, 0, None)))
            if o == dur:
                res.append((REC + 0.5, (3 if com else 1, en, o, o, (), pre, tc, 0 if com else 1, None)))
            elif o > dur:
                res.append((REC + GAP + 1, (3 if com else 1, en, o, o, (), pre, tc, 0 if com else 1, None)))
        if (st == 3 or st == 4) and node == en:
            if o <= pos:
                if st == 4 and o > dur and not com:
                    res.append((LATE + 0.5, (4, node, pos, o, holes, pre, tc, 0, None)))
                else:
                    res.append((LATE + 0.5, s))
            elif st == 3 and not com:
                for (a, b) in holes:
                    if a < o <= b:
                        res.append((LATE + 1, s))
                        break
    elif typ == 'abort':
        if act and node == en:
            res.append((0.3 + pen, (4, node, dur, dur, (), pre, tc, 0, None)))
        if st == 2:
            if node == en:
                res.append((LATE + dt + pen, (4, node, dur, dur, (), pre, tc, 0, None)))
            res.append((REC + 1 + pen, (4, en, dur, dur, (), pre, tc, 0, None)))
    elif typ == 'recover':
        if st == 2:
            if o == dur:
                res.append((0.0, (1, en, o, o, (), pre, tc, 0, None)))
            elif dur < o <= pre:
                res.append((GAP, (1, en, o, o, (), pre, tc, 0, None)))
            else:
                res.append((BAD - 2, (1, en, o, max(o, dur), (), pre, tc, 0, None)))
        elif st == 1:
            if inf and node == en and o == dur:
                res.append((JIT - REC, (1, node, pos, dur, holes, pre, tc, 0, None)))
            elif (not inf) and o == dur:
                res.append((JIT + 1, (5, node, pos, dur, holes, pre, tc, 0, en)))
            res.append((REC + 1.5, (1, en, o, max(o, dur), (), pos, t, 0, None)))
    if not res and (node == en or pn == en):
        res.append((FB, s))
    return res


def _fallback(state):
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    lastnode = {}
    status = {s: "active" for s in sids}
    dur = {s: 0 for s in sids}
    out_a = {}
    for e in events:
        if e["type"] == "crash":
            continue
        s = e.get("sid")
        if s is None:
            s = lastnode.get(e["node"], sids[0] if sids else "")
            out_a[str(e["i"])] = s
        if s in status:
            lastnode[e["node"]] = s
            if e["type"] == "commit":
                status[s] = "committed"
                if e["off"] is not None:
                    dur[s] = e["off"]
            elif e["type"] == "abort":
                status[s] = "aborted"
            elif e["type"] in ("checkpoint", "recover") and e["off"] is not None:
                dur[s] = max(dur[s], e["off"])
    state["output"] = {"assignments": out_a,
                       "sessions": {s: {"status": status[s], "durable": int(dur[s])} for s in sids}}
    return state


def _core(state):
    t0 = time.process_time()
    inp = state.get("input") or {}
    evs = sorted(inp.get("events", []) or [], key=lambda e: (e.get("t", 0) or 0, e.get("i", 0) or 0))
    sids = []
    for e in evs:
        if e.get("type") == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in evs:
        s = e.get("sid")
        if s is not None and s not in sids:
            sids.append(s)
    sidx = {s: k for k, s in enumerate(sids)}
    n = len(evs)
    NS = len(sids)
    ts = [(e.get("t", 0) or 0) for e in evs]
    gl = sorted(ts[k + 1] - ts[k] for k in range(n - 1)) or [1]
    med = gl[len(gl) // 2]
    W = max(4.0, 3.0 * max(med, 1))

    sig_prev = {}
    dupcand = [[] for _ in range(n)]
    is_orig = [False] * n
    last_ref = [-1] * n
    cont = {}
    last_known = [-1] * NS
    for p, e in enumerate(evs):
        typ = e.get("type")
        s = e.get("sid")
        if s is not None and s in sidx and typ != "open":
            last_known[sidx[s]] = p
        if typ in ("write", "checkpoint", "commit"):
            cont.setdefault((e.get("node"), e.get("off")), []).append(p)
        if typ in ("crash", "open"):
            continue
        sig = (typ, e.get("node"), e.get("off"), e.get("len"))
        lst = sig_prev.get(sig)
        if lst:
            dupcand[p] = lst[-4:]
            for q in dupcand[p]:
                is_orig[q] = True
                last_ref[q] = p
        sig_prev.setdefault(sig, []).append(p)

    def abort_pen(p, k, s):
        pen = 0.0
        if last_known[k] > p + 2:
            pen += 3.0
        lst = cont.get((s[1], s[2]))
        if lst:
            j = bisect.bisect_right(lst, p)
            while j < len(lst):
                sd = evs[lst[j]].get("sid")
                if sd is None or sd == sids[k]:
                    pen += 2.5
                    break
                j += 1
        return pen

    init_s = tuple((0, None, 0, 0, (), 0, 0, 0, None) for _ in range(NS))
    beam = [(0.0, init_s, (), None)]
    work = n * max(NS, 1)
    if work < 3000:
        B0 = 64
    elif work < 8000:
        B0 = 40
    else:
        B0 = 28
    B = B0
    budget = 0.75
    for p, e in enumerate(evs):
        typ = e.get("type")
        en = e.get("node")
        o = e.get("off")
        l = e.get("len") or 0
        t = e.get("t", 0) or 0
        if o is None:
            o = 0
        if typ == "crash":
            nb = []
            for (c, ss, memo, path) in beam:
                lst = list(ss)
                ch = False
                for k, s in enumerate(lst):
                    if s[1] == en:
                        if s[0] == 1:
                            lst[k] = (2, en, s[3], s[3], (), s[2], t, 0, None)
                            ch = True
                        elif s[0] == 5:
                            lst[k] = (1, s[8], s[3], s[3], (), s[2], t, 0, None)
                            ch = True
                nb.append((c, tuple(lst) if ch else ss, memo, path))
            beam = nb
            continue
        known = e.get("sid")
        if known is not None and known in sidx:
            cands = [sidx[known]]
        else:
            known = None
            cands = list(range(NS))
        nxt = {}
        order = []
        for (c, ss, memo, path) in beam:
            if memo:
                memo = tuple(m for m in memo if last_ref[m[0]] >= p)
            exp = []
            for k in cands:
                sk = ss[k]
                if sk[0] == 0 and typ != "open":
                    continue
                pen = 0.0
                if typ == "abort" and known is None:
                    pen = abort_pen(p, k, sk)
                for (dc, ns) in _opts(sk, typ, en, o, l, t, W, pen):
                    if ns is sk:
                        exp.append((c + dc, ss, k))
                    else:
                        exp.append((c + dc, ss[:k] + (ns,) + ss[k + 1:], k))
            if dupcand[p] and memo:
                md = dict(memo)
                for q in dupcand[p]:
                    if q in md:
                        k = md[q]
                        if known is None or sidx[known] == k:
                            exp.append((c + DUP, ss, k))
            if not exp:
                if known is not None:
                    k = cands[0]
                else:
                    fb = [j for j in range(NS) if ss[j][1] == en and ss[j][0] != 0] or \
                         [j for j in range(NS) if ss[j][0] != 0] or list(range(NS))
                    k = fb[0] if fb else -1
                exp.append((c + 25.0, ss, k))
            for (nc, nss, k) in exp:
                nm = memo
                if is_orig[p] and k >= 0:
                    nm = memo + ((p, k),)
                key = (nss, nm)
                old = nxt.get(key)
                if old is None or nc < old[0]:
                    if old is None:
                        order.append(key)
                    nxt[key] = (nc, nss, nm, (p, k, path))
        cand = [nxt[kk] for kk in order]
        cand.sort(key=lambda x: x[0])
        if cand:
            beam = cand[:B]
        el = time.process_time() - t0
        if el > budget:
            B = 1
        elif p > 8:
            proj = el / (p + 1) * n
            if proj > budget:
                B = max(2, int(B * 0.75))
            elif proj < 0.4 * budget and B < B0:
                B = min(B0, B + 2)

    best = beam[0]
    asg = {}
    path = best[3]
    while path is not None:
        p, k, path = path
        if k >= 0:
            asg[p] = sids[k]
    assignments = {}
    for p, e in enumerate(evs):
        if e.get("type") != "crash" and e.get("sid") is None:
            s = asg.get(p)
            if s is None:
                s = sids[0] if sids else ""
            assignments[str(e.get("i"))] = s
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted", 5: "active"}
    sessions = {}
    for k, s in enumerate(sids):
        st = best[1][k]
        sessions[s] = {"status": names[st[0]], "durable": int(st[3])}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state


def solve(state, params):
    try:
        return _core(state)
    except Exception:
        return _fallback(state)

import bisect
from collections import defaultdict


def _hungarian(cost, n, m):
    INF = float("inf")
    u = [0.0] * (n + 1)
    v = [0.0] * (m + 1)
    p = [0] * (m + 1)
    way = [0] * (m + 1)
    for i in range(1, n + 1):
        p[0] = i
        j0 = 0
        minv = [INF] * (m + 1)
        used = [False] * (m + 1)
        while True:
            used[j0] = True
            i0 = p[j0]
            delta = INF
            j1 = 0
            row = cost[i0 - 1]
            ui0 = u[i0]
            for j in range(1, m + 1):
                if not used[j]:
                    cur = row[j - 1] - ui0 - v[j]
                    if cur < minv[j]:
                        minv[j] = cur
                        way[j] = j0
                    if minv[j] < delta:
                        delta = minv[j]
                        j1 = j
            for j in range(m + 1):
                if used[j]:
                    u[p[j]] += delta
                    v[j] -= delta
                else:
                    minv[j] -= delta
            j0 = j1
            if p[j0] == 0:
                break
        while True:
            j1 = way[j0]
            p[j0] = p[j1]
            j0 = j1
            if j0 == 0:
                break
    res = [-1] * n
    for j in range(1, m + 1):
        if p[j]:
            res[p[j] - 1] = j - 1
    return res


def _match(edges, limit=40):
    """edges: dict (r,c)->w ; negative w = beneficial. Max-benefit matching, each row/col once."""
    if not edges:
        return {}
    par = {}

    def find(x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x
    for (r, c) in edges:
        a = ("r", r)
        b = ("c", c)
        if a not in par:
            par[a] = a
        if b not in par:
            par[b] = b
        ra, rb = find(a), find(b)
        if ra != rb:
            par[ra] = rb
    comp = defaultdict(list)
    for (r, c), w in edges.items():
        comp[find(("r", r))].append((r, c, w))
    result = {}
    for key in sorted(comp.keys(), key=lambda k: str(k)):
        lst = comp[key]
        rs = sorted(set(x[0] for x in lst))
        cs = sorted(set(x[1] for x in lst))
        if len(rs) <= limit and len(cs) <= 2 * limit:
            ri = {r: k for k, r in enumerate(rs)}
            ci = {c: k for k, c in enumerate(cs)}
            n = len(rs)
            m = len(cs) + n
            big = 1e6
            mat = [[big] * m for _ in range(n)]
            for k in range(n):
                mat[k][len(cs) + k] = 0.0
            for r, c, w in lst:
                if w < mat[ri[r]][ci[c]]:
                    mat[ri[r]][ci[c]] = w
            asg = _hungarian(mat, n, m)
            for k, j in enumerate(asg):
                if 0 <= j < len(cs) and mat[k][j] < 0:
                    result[rs[k]] = cs[j]
        else:
            usedr = set()
            usedc = set()
            for r, c, w in sorted(lst, key=lambda x: (x[2], x[0], x[1])):
                if w >= 0:
                    break
                if r in usedr or c in usedc:
                    continue
                usedr.add(r)
                usedc.add(c)
                result[r] = c
    return result


def solve(state, params):
    inp = state["input"]
    raw = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    n = len(raw)
    E = []
    for pos, e in enumerate(raw):
        ty = e["type"]
        off = e.get("off")
        ln = e.get("len")
        inn = None
        out = None
        if ty == "open":
            out = 0
        elif ty == "write":
            inn = off if off is not None else 0
            out = inn + (ln or 0)
        elif ty in ("checkpoint", "commit", "recover"):
            inn = off
            out = off
        E.append({"pos": pos, "i": e["i"], "t": e["t"], "node": e["node"], "type": ty,
                  "off": off, "len": ln, "sid": e.get("sid"), "inn": inn, "out": out,
                  "term": ty in ("commit", "abort"),
                  "sig": (e["node"], ty, off, ln)})
    crashes = defaultdict(list)
    for e in E:
        if e["type"] == "crash":
            crashes[e["node"]].append(e["t"])
    for k in crashes:
        crashes[k].sort()
    opens = {}
    for e in E:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in opens:
            opens[e["sid"]] = e
    SE = [e for e in E if e["type"] != "crash"]
    tmin = raw[0]["t"] if raw else 0
    tmax = raw[-1]["t"] if raw else 1
    spacing = max(1.0, (tmax - tmin) / max(1, n - 1))
    open_t = {sid: e["t"] for sid, e in opens.items()}

    # ---- estimate jitter and per-session gap from labelled events
    bysid = defaultdict(list)
    for e in SE:
        if e["sid"] is not None:
            bysid[e["sid"]].append(e)
    inv = []
    gaps = []
    for sid, lst in bysid.items():
        seen_sig = set()
        firsts = []
        for x in lst:
            if x["sig"] in seen_sig:
                continue
            seen_sig.add(x["sig"])
            firsts.append(x)
        for a in firsts:
            if a["type"] != "write":
                continue
            for b in firsts:
                if a is b or b["inn"] is None:
                    continue
                if b["inn"] == a["out"] and a["node"] == b["node"]:
                    d = b["t"] - a["t"]
                    if d < 0:
                        inv.append(-d)
                    else:
                        gaps.append(d)
    J = 3.0 * spacing
    if inv:
        inv.sort()
        q = inv[min(len(inv) - 1, int(0.9 * len(inv)))]
        J = max(J, q * 1.4)
    if gaps:
        gaps.sort()
        gs = gaps[len(gaps) // 2]
    else:
        gs = spacing * max(2, len(opens)) / 2.0
    gs = max(gs, spacing)

    def tc(dt):
        if dt >= 0:
            return 0.6 * dt / gs
        return 0.4 + 0.6 * (-dt) / J

    def crash_in(node, t1, t2):
        lst = crashes.get(node)
        if not lst:
            return []
        a = bisect.bisect_right(lst, t1)
        b = bisect.bisect_left(lst, t2)
        return lst[a:b]

    # ---------------- Stage 1: exact offset links ----------------
    byin = defaultdict(list)
    for e in SE:
        if e["type"] in ("write", "checkpoint", "commit") and e["inn"] is not None:
            byin[(e["node"], e["inn"])].append(e)
    K1 = 3.0
    edges = {}
    for e in SE:
        if e["term"] or e["out"] is None:
            continue
        for f in byin.get((e["node"], e["out"]), []):
            if f is e:
                continue
            dt = f["t"] - e["t"]
            if dt < -J:
                continue
            if f["inn"] == f["out"] and e["inn"] == e["out"] and f["pos"] <= e["pos"]:
                continue
            if e["inn"] is not None and f["out"] == e["inn"] and f["inn"] == e["out"] and f["pos"] <= e["pos"]:
                continue
            if e["sid"] and f["sid"] and e["sid"] != f["sid"]:
                continue
            if e["type"] == "open" and f["t"] < e["t"]:
                continue
            if f["sid"] in open_t and e["t"] < open_t[f["sid"]]:
                continue
            if e["sid"] in open_t and f["t"] < open_t[e["sid"]]:
                continue
            if crash_in(e["node"], e["t"], f["t"]):
                continue
            w = tc(dt)
            if w >= K1:
                continue
            edges[(e["pos"], f["pos"])] = w - K1
    m1 = _match(edges)
    succ = dict(m1)
    pred = {c: r for r, c in m1.items()}
    bypos = {e["pos"]: e for e in E}
    tracks = []
    seen = set()
    for e in SE:
        if e["pos"] in pred:
            continue
        chain = [e["pos"]]
        seen.add(e["pos"])
        cur = e["pos"]
        while cur in succ and succ[cur] not in seen:
            cur = succ[cur]
            chain.append(cur)
            seen.add(cur)
        tracks.append(chain)
    for e in SE:
        if e["pos"] not in seen:
            tracks.append([e["pos"]])
            seen.add(e["pos"])
    newtracks = []
    for ch in tracks:
        cur = []
        lab = None
        for p in ch:
            s = bypos[p]["sid"]
            if s is not None and lab is not None and s != lab:
                newtracks.append(cur)
                cur = []
                lab = None
            cur.append(p)
            if s is not None:
                lab = s
        if cur:
            newtracks.append(cur)
    tracks = newtracks

    def tinfo(ch):
        evs = [bypos[p] for p in ch]
        h = evs[0]
        z = evs[-1]
        lab = None
        for x in evs:
            if x["sid"]:
                lab = x["sid"]
        dur = 0 if h["type"] == "open" else None
        for x in evs:
            if x["type"] in ("checkpoint", "commit", "recover") and x["off"] is not None:
                dur = x["off"] if dur is None else max(dur, x["off"])
        return {"ch": ch, "h": h, "z": z, "lab": lab, "dur": dur,
                "tmin": min(x["t"] for x in evs), "tmax": max(x["t"] for x in evs)}
    T = [tinfo(ch) for ch in tracks]

    # ---------------- Stage 2: tracklet stitching ----------------
    C_GAP = 3.0
    C_REC_EX = 0.3
    C_REC_MISSCP = 2.5
    C_REC_UNK = 1.2
    C_MISSREC = 4.5
    C_ABORT = 1.0
    C_DUP = 1.2
    C_END = 2.0
    H_ORPH = 9.0
    sigidx = defaultdict(list)
    for k, tr in enumerate(T):
        for p in tr["ch"]:
            x = bypos[p]
            if x["type"] not in ("open", "crash"):
                sigidx[x["sig"]].append((x["t"], k, x["sid"]))
    DUPW = max(12 * J, 40 * spacing)
    heads = [k for k, tr in enumerate(T) if tr["h"]["type"] != "open"]
    tails = [k for k, tr in enumerate(T) if not tr["z"]["term"]]

    def stitch(forbid):
        edges2 = {}
        dupopt = {}
        for b in heads:
            hb = T[b]["h"]
            best = None
            for (tt, k, s) in sigidx.get(hb["sig"], []):
                if k == b or tt >= hb["t"] or hb["t"] - tt > DUPW:
                    continue
                if T[b]["lab"] and T[k]["lab"] and T[b]["lab"] != T[k]["lab"]:
                    continue
                if ("d", k, b) in forbid:
                    continue
                c = C_DUP + 0.3 * (hb["t"] - tt) / DUPW
                if best is None or c < best[0]:
                    best = (c, k)
            if best is not None:
                dupopt[b] = best
        for a in tails:
            ta = T[a]
            za = ta["z"]
            for b in heads:
                if a == b:
                    continue
                tb = T[b]
                hb = tb["h"]
                if ("l", a, b) in forbid:
                    continue
                if ta["lab"] and tb["lab"] and ta["lab"] != tb["lab"]:
                    continue
                dt = hb["t"] - za["t"]
                if dt < -J:
                    continue
                if tb["tmin"] < ta["tmin"]:
                    continue
                if ta["h"]["type"] == "open" and tb["tmin"] < ta["h"]["t"]:
                    continue
                if tb["lab"] in open_t and ta["tmin"] < open_t[tb["lab"]]:
                    continue
                if ta["lab"] in open_t and tb["tmin"] < open_t[ta["lab"]]:
                    continue
                cr = crash_in(za["node"], za["t"] - J, hb["t"])
                crs = crash_in(za["node"], za["t"], hb["t"])
                ty = hb["type"]
                w = None
                if ty == "recover":
                    if not cr:
                        continue
                    o = hb["off"]
                    out = za["out"]
                    if o is None or out is None or o > out:
                        continue
                    dur = ta["dur"]
                    if dur is not None:
                        if o == dur:
                            w = C_REC_EX
                        elif o > dur:
                            w = C_REC_MISSCP
                        else:
                            continue
                    else:
                        w = C_REC_UNK
                    w += 0.15 * max(0, dt) / gs
                elif ty == "abort":
                    if crs:
                        w = C_ABORT + C_MISSREC + tc(dt)
                    elif hb["node"] == za["node"]:
                        w = C_ABORT + tc(dt)
                    else:
                        continue
                else:
                    x = hb["inn"]
                    out = za["out"]
                    if out is None or x is None:
                        continue
                    if not crs and hb["node"] == za["node"]:
                        if x == out:
                            w = 0.5 + tc(dt)
                        elif x > out:
                            w = C_GAP + tc(dt) + 0.3 * min(3.0, (x - out) / 2048.0)
                        else:
                            continue
                    elif crs:
                        cands = []
                        if hb["node"] == za["node"] and x == out and hb["t"] - crs[0] <= J:
                            cands.append(1.0 + tc(dt))
                        dur = ta["dur"]
                        if dur is not None:
                            if x == dur:
                                cands.append(C_MISSREC + 0.1 * max(0, dt) / gs)
                            elif dur < x <= out:
                                cands.append(C_MISSREC + 2.0)
                        elif x <= out:
                            cands.append(C_MISSREC + 1.0)
                        if not cands:
                            continue
                        w = min(cands)
                    else:
                        continue
                own = min(H_ORPH, dupopt[b][0]) if b in dupopt else H_ORPH
                red = w - own - C_END
                if red < 0:
                    edges2[(a, b)] = red
        m2 = _match(edges2, limit=40)
        parent = {}
        for a, b in m2.items():
            parent[b] = ("l", a)
        for b, (c, k) in dupopt.items():
            if b not in parent and c < H_ORPH:
                parent[b] = ("d", k)
        return parent, edges2

    def resolve_roots(parent):
        root = {}
        for k0 in range(len(T)):
            if k0 in root:
                continue
            path = []
            seenk = set()
            cur = k0
            r = None
            while True:
                if cur in root:
                    r = root[cur]
                    break
                if cur in seenk:
                    r = None
                    break
                seenk.add(cur)
                path.append(cur)
                if T[cur]["h"]["type"] == "open":
                    r = cur
                    break
                if cur not in parent:
                    r = None
                    break
                cur = parent[cur][1]
            for q in path:
                root[q] = r
        return root

    forbid = set()
    parent = {}
    root = {}
    for it in range(4):
        parent, edges2 = stitch(forbid)
        root = resolve_roots(parent)
        newf = False
        for k, tr in enumerate(T):
            r = root.get(k)
            if r is None or not tr["lab"]:
                continue
            rs = T[r]["h"]["sid"]
            if rs != tr["lab"]:
                cur = k
                worst = None
                steps = 0
                while cur != r and cur in parent and steps < 1000:
                    steps += 1
                    kind, pa = parent[cur]
                    c = edges2.get((pa, cur), -0.1) if kind == "l" else 0.0
                    if worst is None or c > worst[0]:
                        worst = (c, kind, pa, cur)
                    cur = pa
                if worst is not None:
                    key = (worst[1], worst[2], worst[3])
                    if key not in forbid:
                        forbid.add(key)
                        newf = True
        if not newf:
            break

    sess_of_tr = {}
    for k, tr in enumerate(T):
        r = root.get(k)
        if r is not None:
            s = T[r]["h"]["sid"]
            if tr["lab"] and tr["lab"] != s:
                s = tr["lab"]
            sess_of_tr[k] = s
        else:
            # nearest labelled tracklet up the parent chain
            cur = k
            steps = 0
            visited = set()
            while cur is not None and cur not in visited and steps < 1000:
                visited.add(cur)
                steps += 1
                if T[cur]["lab"]:
                    sess_of_tr[k] = T[cur]["lab"]
                    break
                if cur in parent:
                    cur = parent[cur][1]
                else:
                    cur = None
    sess_events = defaultdict(list)
    for k, s in sess_of_tr.items():
        for p in T[k]["ch"]:
            sess_events[s].append(bypos[p])
    sids = sorted(opens.keys(), key=lambda s: (opens[s]["t"], opens[s]["pos"]))
    for k, tr in enumerate(T):
        if k in sess_of_tr:
            continue
        h = tr["h"]
        best = None
        for s in sids:
            if opens[s]["t"] > tr["tmin"]:
                continue
            evs = sess_events[s]
            sc = 50.0
            for x in evs:
                if x["node"] == h["node"] and x["t"] <= h["t"] + J:
                    if x["out"] is not None and h["inn"] is not None and x["out"] == h["inn"]:
                        sc = min(sc, tc(h["t"] - x["t"]))
                    elif x["sig"] == h["sig"]:
                        sc = min(sc, 1.0 + tc(h["t"] - x["t"]))
                    else:
                        sc = min(sc, 3.0 + tc(abs(h["t"] - x["t"])))
            if any(x["term"] and x["t"] < h["t"] - J for x in evs):
                sc += 5
            if best is None or sc < best[0]:
                best = (sc, s)
        if best is None and sids:
            best = (0, sids[0])
        if best is not None:
            sess_of_tr[k] = best[1]
            for p in tr["ch"]:
                sess_events[best[1]].append(bypos[p])

    assignments = {}
    for k, s in sess_of_tr.items():
        for p in T[k]["ch"]:
            x = bypos[p]
            if x["sid"] is None and x["type"] != "crash":
                assignments[str(x["i"])] = s
    for e in SE:
        if e["sid"] is None and str(e["i"]) not in assignments and sids:
            assignments[str(e["i"])] = sids[0]

    sessions = {}
    for s in opens:
        evs = sorted(sess_events.get(s, []), key=lambda x: (x["t"], x["pos"]))
        if not any(x["type"] == "open" for x in evs):
            evs = [opens[s]] + evs
        seen_sig = set()
        uniq = []
        for x in evs:
            if x["type"] != "open" and x["sig"] in seen_sig:
                continue
            seen_sig.add(x["sig"])
            uniq.append(x)
        dur = 0
        for x in uniq:
            if x["type"] in ("checkpoint", "commit", "recover") and x["off"] is not None:
                dur = max(dur, x["off"])
        com = [x for x in uniq if x["type"] == "commit"]
        ab = [x for x in uniq if x["type"] == "abort"]
        if com or ab:
            last = max(com + ab, key=lambda x: (x["t"], x["pos"]))
            status = "committed" if last["type"] == "commit" else "aborted"
            if status == "committed" and last["off"] is not None:
                dur = max(dur, last["off"])
        else:
            last = uniq[-1]
            node = last["node"]
            cs = crash_in(node, last["t"] - J, tmax + 1)
            status = "active"
            if cs:
                after = [c for c in cs if c >= last["t"]]
                if after:
                    status = "down"
                elif last["type"] not in ("recover", "open"):
                    prev = [x for x in uniq if x is not last]
                    cur_out = max([x["out"] for x in prev if x["out"] is not None] or [0])
                    if last["inn"] is not None and last["inn"] == cur_out and last["inn"] > dur:
                        status = "down"
                    elif last["type"] == "write" and last["inn"] is not None and last["inn"] > dur:
                        status = "down"
        sessions[s] = {"status": status, "durable": int(dur)}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state

import time
import bisect

GAP = 2.5
MREC = 2.5
JIT = 1.0
JITC = 1.5
FB = 5.0
DUP = 2.0
DEF = 0.7
MAXP = 3
WIN = 15
EXACT_TOL = 0.25


def _opts(s, typ, en, o, l):
    st, node, off, dur, poff, pnode, gaps, inf = s
    res = []
    if typ == 'open':
        if st == 0:
            res.append((0.0, (1, en, 0, 0, 0, en, (), 0)))
        return res
    if st == 0:
        return res
    if typ == 'write':
        if (st == 1 or st == 5) and node == en:
            if o == off:
                res.append((0.0, (st, node, o + l, dur, poff, pnode, gaps, inf)))
            elif o > off:
                g2 = (gaps + ((off, o),))[-3:]
                res.append((GAP, (st, node, o + l, dur, poff, pnode, g2, inf)))
            else:
                for k, g in enumerate(gaps):
                    if g[0] == o and o + l <= g[1]:
                        if o + l < g[1]:
                            g2 = gaps[:k] + ((o + l, g[1]),) + gaps[k + 1:]
                            res.append((JIT - 0.5 * GAP, (st, node, off, dur, poff, pnode, g2, inf)))
                        else:
                            g2 = gaps[:k] + gaps[k + 1:]
                            res.append((JIT - GAP, (st, node, off, dur, poff, pnode, g2, inf)))
                        break
        if st == 5 and pnode == en and o == dur:
            res.append((JIT, (1, en, o + l, dur, poff, pnode, (), 0)))
        if st == 2:
            if o == dur:
                res.append((MREC, (1, en, o + l, dur, poff, en, (), 1)))
            elif o > dur:
                res.append((MREC + GAP, (1, en, o + l, dur, poff, en, (), 1)))
            if pnode == en and o == poff:
                res.append((JITC, (st, node, off, dur, o + l, pnode, gaps, inf)))
    elif typ == 'checkpoint':
        if (st == 1 or st == 5) and node == en:
            if o == off:
                res.append((0.0, (st, node, off, o, poff, pnode, gaps, inf)))
            elif o > off:
                res.append((GAP, (st, node, o, o, poff, pnode, (), inf)))
            elif o >= dur:
                res.append((JIT + 0.5, (st, node, off, o, poff, pnode, gaps, inf)))
        if st == 2:
            if pnode == en and o == poff:
                res.append((JITC, (2, node, o, o, o, pnode, (), 0)))
            if o == dur:
                res.append((MREC, (1, en, o, o, poff, en, (), 1)))
            elif o > dur:
                res.append((MREC + GAP, (1, en, o, o, poff, en, (), 1)))
    elif typ == 'commit':
        if (st == 1 or st == 5) and node == en:
            if o == off:
                res.append((0.0, (3, node, o, o, poff, pnode, (), 0)))
            elif o > off:
                res.append((GAP, (3, node, o, o, poff, pnode, (), 0)))
        if st == 5 and pnode == en and o == dur:
            res.append((JIT, (3, en, o, o, poff, pnode, (), 0)))
        if st == 2:
            if pnode == en and o == poff:
                res.append((JITC, (3, node, o, o, o, pnode, (), 0)))
            if o == dur:
                res.append((MREC, (3, en, o, o, poff, en, (), 0)))
            elif o > dur:
                res.append((MREC + GAP, (3, en, o, o, poff, en, (), 0)))
    elif typ == 'abort':
        if (st == 1 or st == 5) and node == en:
            res.append((0.2, (4, node, dur, dur, poff, pnode, (), 0)))
        if st == 2:
            if pnode == en:
                res.append((JITC, (4, node, dur, dur, poff, pnode, (), 0)))
            res.append((MREC, (4, en, dur, dur, poff, en, (), 0)))
    elif typ == 'recover':
        if st == 2:
            if o == dur:
                res.append((0.0, (1, en, o, o, poff, en, (), 0)))
            elif o > dur:
                res.append((GAP, (1, en, o, o, poff, en, (), 0)))
            else:
                res.append((GAP + 1.0, (1, en, o, o, poff, en, (), 0)))
        elif st == 1:
            if inf and node == en and o == dur:
                res.append((JIT - MREC, (1, node, off, dur, poff, pnode, gaps, 0)))
            elif o == dur and not inf:
                res.append((JIT + 1.0, (5, node, off, dur, poff, en, gaps, 0)))
    if not res and (node == en or pnode == en):
        res.append((FB, None))
    return res


def solve(state, params):
    t0 = time.process_time()
    inp = state.get("input") or {}
    evs = sorted(inp.get("events", []) or [], key=lambda e: (e.get("t", 0) or 0, e.get("i", 0) or 0))
    sids = []
    for e in evs:
        if e.get("type") == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in evs:
        s = e.get("sid")
        if s is not None and s not in sids:
            sids.append(s)
    sidx = {s: k for k, s in enumerate(sids)}
    n = len(evs)
    NS = len(sids)
    ts = [(e.get("t", 0) or 0) for e in evs]

    sig_prev = {}
    dupcand = [[] for _ in range(n)]
    is_orig = [False] * n
    last_ref = [-1] * n
    cont = {}
    last_known = [-1] * NS
    info = []
    for p, e in enumerate(evs):
        typ = e.get("type")
        s = e.get("sid")
        if s is not None and s in sidx and typ != "open":
            last_known[sidx[s]] = p
        if typ in ("write", "checkpoint", "commit"):
            cont.setdefault((e.get("node"), e.get("off")), []).append(p)
        o = e.get("off")
        if o is None:
            o = 0
        l = e.get("len") or 0
        if s is not None and s in sidx:
            kn = sidx[s]
            cands = [kn]
        else:
            kn = -1
            cands = list(range(NS))
        info.append((typ, e.get("node"), o, l, cands, kn))
        if typ in ("crash", "open"):
            continue
        sig = (typ, e.get("node"), e.get("off"), e.get("len"))
        lst = sig_prev.get(sig)
        if lst:
            dupcand[p] = lst[-4:]
            for q in dupcand[p]:
                is_orig[q] = True
                last_ref[q] = p
        sig_prev.setdefault(sig, []).append(p)

    def abort_pen(p, k, s):
        pen = 0.0
        if last_known[k] > p + 2:
            pen += 3.0
        lst = cont.get((s[1], s[2]))
        if lst:
            j = bisect.bisect_right(lst, p)
            while j < len(lst):
                sd = evs[lst[j]].get("sid")
                if sd is None or sd == sids[k]:
                    pen += 2.5
                    break
                j += 1
        return pen

    def expand(c, ss, memo, path, q, exact):
        typ, en, o, l, cands, kn = info[q]
        exp = []
        for k in cands:
            for (dc, ns) in _opts(ss[k], typ, en, o, l):
                if ns is None:
                    if exact:
                        continue
                    exp.append((c + dc, ss, k))
                else:
                    if typ == "abort" and kn < 0:
                        dc += abort_pen(q, k, ss[k])
                    if exact and dc > EXACT_TOL:
                        continue
                    exp.append((c + dc, ss[:k] + (ns,) + ss[k + 1:], k))
        if not exact:
            if dupcand[q] and memo:
                md = dict(memo)
                for r in dupcand[q]:
                    if r in md:
                        k = md[r]
                        if kn < 0 or kn == k:
                            exp.append((c + DUP, ss, k))
            if not exp:
                exp.append((c + FB * 2, ss, kn))
        out = []
        for (nc, nss, k) in exp:
            nm = memo
            if is_orig[q] and k >= 0:
                nm = memo + ((q, k),)
            out.append((nc, nss, nm, (q, k, path)))
        return out

    def settle(h, tnow, force_all, force_node):
        res = []
        stack = [h]
        guard = 0
        while stack:
            guard += 1
            c, ss, memo, path, pend = stack.pop()
            if not pend:
                res.append((c, ss, memo, path, pend))
                continue
            done = False
            for idx, q in enumerate(pend):
                ex = expand(c, ss, memo, path, q, True)
                if ex:
                    rest = pend[:idx] + pend[idx + 1:]
                    for (nc, nss, nm, npth) in ex:
                        stack.append((nc, nss, nm, npth, rest))
                    done = True
                    break
            if done:
                continue
            fidx = -1
            for idx, q in enumerate(pend):
                if force_all or tnow - ts[q] > WIN or (force_node is not None and info[q][1] == force_node) or guard > 400:
                    fidx = idx
                    break
            if fidx >= 0:
                q = pend[fidx]
                rest = pend[:fidx] + pend[fidx + 1:]
                for (nc, nss, nm, npth) in expand(c, ss, memo, path, q, False):
                    stack.append((nc, nss, nm, npth, rest))
                continue
            res.append((c, ss, memo, path, pend))
        return res

    DEFERRABLE = ("write", "checkpoint", "commit", "recover")
    init_s = tuple((0, None, 0, 0, 0, None, (), 0) for _ in range(NS))
    beam = [(0.0, init_s, (), None, ())]
    B = 40
    budget = 0.72

    def prune(items, B):
        nxt = {}
        for h in items:
            key = (h[1], h[2], h[4])
            old = nxt.get(key)
            if old is None or h[0] < old[0]:
                nxt[key] = h
        cand = list(nxt.values())
        cand.sort(key=lambda x: x[0])
        return cand[:B]

    for p in range(n):
        typ, en, o, l, cands, kn = info[p]
        if typ == "crash":
            nb = []
            for h in beam:
                for (c, ss, memo, path, pend) in settle(h, ts[p], False, en):
                    lst = list(ss)
                    ch = False
                    for k, s in enumerate(lst):
                        if s[1] == en:
                            if s[0] == 1:
                                lst[k] = (2, en, s[3], s[3], s[2], en, (), 0)
                                ch = True
                            elif s[0] == 5:
                                lst[k] = (1, s[5], s[3], s[3], s[4], s[5], (), 0)
                                ch = True
                    nb.append((c, tuple(lst) if ch else ss, memo, path, pend))
            if nb:
                beam = prune(nb, B)
            continue
        allh = []
        for (c, ss, memo, path, pend) in beam:
            if memo:
                memo = tuple(m for m in memo if last_ref[m[0]] >= p)
            new = [x + (pend,) for x in expand(c, ss, memo, path, p, False)]
            if typ in DEFERRABLE and len(pend) < MAXP:
                new.append((c + DEF, ss, memo, path, pend + (p,)))
            for h2 in new:
                allh.extend(settle(h2, ts[p], False, None))
        el = time.process_time() - t0
        rem = n - p
        if el > budget:
            B = 1
        elif p > 10:
            per = el / (p + 1)
            if per * rem > (budget - el):
                B = max(2, int(B * 0.7))
        if allh:
            beam = prune(allh, B)

    fin = []
    for h in beam[:max(1, min(len(beam), 8))]:
        fin.extend(settle(h, 10 ** 12, True, None))
    if not fin:
        fin = [(0.0, init_s, (), None, ())]
    fin.sort(key=lambda x: x[0])
    best = fin[0]
    asg = {}
    path = best[3]
    while path is not None:
        q, k, path = path
        if k >= 0 and q not in asg:
            asg[q] = sids[k]
    assignments = {}
    for p, e in enumerate(evs):
        if e.get("type") != "crash" and e.get("sid") is None:
            s = asg.get(p)
            if s is None:
                s = sids[0] if sids else ""
            assignments[str(e.get("i"))] = s
    sessions = {}
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted", 5: "active"}
    for k, s in enumerate(sids):
        st = best[1][k]
        sessions[s] = {"status": names[st[0]], "durable": int(st[3])}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state

