                        if o + l < g[1]:
                            g2 = gaps[:k] + ((o + l, g[1]),) + gaps[k + 1:]
                            res.append((JIT - 0.5 * GAP, (st, node, off, dur, poff, pnode, g2, inf)))
                        else:
                            g2 = gaps[:k] + gaps[k + 1:]
                            res.append((JIT - GAP, (st, node, off, dur, poff, pnode, g2, inf)))
                        break
        if st == 5 and pnode == en and o == dur:
            res.append((JIT, (1, en, o + l, dur, poff, pnode, (), 0)))
        if st == 2:
            if o == dur:
                res.append((MREC, (1, en, o + l, dur, poff, en, (), 1)))
            elif o > dur:
                res.append((MREC + GAP, (1, en, o + l, dur, poff, en, (), 1)))
            if pnode == en and o == poff:
                res.append((JITC, (st, node, off, dur, o + l, pnode, gaps, inf)))
    elif typ == 'checkpoint':
        if (st == 1 or st == 5) and node == en:
            if o == off:
                res.append((0.0, (st, node, off, o, poff, pnode, gaps, inf)))
            elif o > off:
                res.append((GAP, (st, node, o, o, poff, pnode, (), inf)))
            elif o >= dur:
                res.append((JIT + 0.5, (st, node, off, o, poff, pnode, gaps, inf)))
        if st == 2:
            if pnode == en and o == poff:
                res.append((JITC, (2, node, o, o, o, pnode, (), 0)))
            if o == dur:
                res.append((MREC, (1, en, o, o, poff, en, (), 1)))
            elif o > dur:
                res.append((MREC + GAP, (1, en, o, o, poff, en, (), 1)))
    elif typ == 'commit':
        if (st == 1 or st == 5) and node == en:
            if o == off:
                res.append((0.0, (3, node, o, o, poff, pnode, (), 0)))
            elif o > off:
                res.append((GAP, (3, node, o, o, poff, pnode, (), 0)))
        if st == 5 and pnode == en and o == dur:
            res.append((JIT, (3, en, o, o, poff, pnode, (), 0)))
        if st == 2:
            if pnode == en and o == poff:
                res.append((JITC, (3, node, o, o, o, pnode, (), 0)))
            if o == dur:
                res.append((MREC, (3, en, o, o, poff, en, (), 0)))
            elif o > dur:
                res.append((MREC + GAP, (3, en, o, o, poff, en, (), 0)))
    elif typ == 'abort':
        if (st == 1 or st == 5) and node == en:
            res.append((0.2, (4, node, dur, dur, poff, pnode, (), 0)))
        if st == 2:
            if pnode == en:
                res.append((JITC, (4, node, dur, dur, poff, pnode, (), 0)))
            res.append((MREC, (4, en, dur, dur, poff, en, (), 0)))
    elif typ == 'recover':
        if st == 2:
            if o == dur:
                res.append((0.0, (1, en, o, o, poff, en, (), 0)))
            elif o > dur:
                res.append((GAP, (1, en, o, o, poff, en, (), 0)))
            else:
                res.append((GAP + 1.0, (1, en, o, o, poff, en, (), 0)))
        elif st == 1:
            if inf and node == en and o == dur:
                res.append((JIT - MREC, (1, node, off, dur, poff, pnode, gaps, 0)))
            elif o == dur and not inf:
                res.append((JIT + 1.0, (5, node, off, dur, poff, en, gaps, 0)))
    if not res and (node == en or pnode == en):
        res.append((FB, None))
    return res


def solve(state, params):
    t0 = time.process_time()
    inp = state.get("input") or {}
    evs = sorted(inp.get("events", []) or [], key=lambda e: (e.get("t", 0) or 0, e.get("i", 0) or 0))
    sids = []
    for e in evs:
        if e.get("type") == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in evs:
        s = e.get("sid")
        if s is not None and s not in sids:
            sids.append(s)
    sidx = {s: k for k, s in enumerate(sids)}
    n = len(evs)
    NS = len(sids)

    E = []
    for e in evs:
        o = e.get("off")
        E.append((e.get("type"), e.get("node"), 0 if o is None else o, e.get("len") or 0,
                  e.get("sid") if e.get("sid") in sidx else None, e.get("t", 0) or 0))

    sig_prev = {}
    dupcand = [[] for _ in range(n)]
    is_orig = [False] * n
    last_ref = [-1] * n
    cont = {}
    last_known = [-1] * NS
    for p, e in enumerate(evs):
        typ = e.get("type")
        s = e.get("sid")
        if s is not None and s in sidx and typ != "open":
            last_known[sidx[s]] = p
        if typ in ("write", "checkpoint", "commit"):
            cont.setdefault((e.get("node"), e.get("off")), []).append(p)
        if typ in ("crash", "open"):
            continue
        sig = (typ, e.get("node"), e.get("off"), e.get("len"))
        lst = sig_prev.get(sig)
        if lst:
            dupcand[p] = lst[-4:]
            for q in dupcand[p]:
                is_orig[q] = True
                last_ref[q] = p
        sig_prev.setdefault(sig, []).append(p)

    # lookahead windows
    win = [[] for _ in range(n)]
    for p in range(n):
        if E[p][0] in ("crash", "open"):
            continue
        crashed = set()
        for q in range(p + 1, min(n, p + 1 + PW)):
            if E[q][5] - E[p][5] > TW:
                break
            if E[q][0] == "crash":
                crashed.add(E[q][1])
                continue
            if E[q][0] in ("write", "checkpoint", "commit") and E[q][1] not in crashed:
                win[p].append(q)

    def abort_pen(p, k, s):
        pen = 0.0
        if last_known[k] > p + 2:
            pen += 3.0
        lst = cont.get((s[1], s[2]))
        if lst:
            j = bisect.bisect_right(lst, p)
            while j < len(lst):
                sd = evs[lst[j]].get("sid")
                if sd is None or sd == sids[k]:
                    pen += 2.5
                    break
                j += 1
        return pen

    def pull_chains(p, k, s, done):
        typ, en, o, l = E[p][0], E[p][1], E[p][2], E[p][3]
        out = []
        sk = sids[k]

        def dfs(s0, chain, depth):
            for q in win[p]:
                if q in done or q in chain:
                    continue
                eq = E[q]
                if eq[4] is not None and eq[4] != sk:
                    continue
                if eq[1] != s0[1]:
                    continue
                for (dc, ns) in _opts(s0, eq[0], eq[1], eq[2], eq[3]):
                    if ns is None or dc != 0.0:
                        continue
                    ch2 = chain + (q,)
                    for (dc2, ns2) in _opts(ns, typ, en, o, l):
                        if ns2 is not None and dc2 <= 0.2:
                            out.append((PULL * len(ch2) + dc2, ns2, ch2))
                    if depth < 2 and len(out) < 6:
                        dfs(ns, ch2, depth + 1)
        dfs(s, (), 1)
        return out

    init_s = tuple((0, None, 0, 0, 0, None, (), 0) for _ in range(NS))
    beam = [(0.0, init_s, (), (), None)]
    B = 48
    budget = 0.8
    for p in range(n):
        typ, en, o, l, known, _t = E[p]
        if typ == "crash":
            nb = []
            for (c, ss, memo, done, path) in beam:
                lst = list(ss)
                ch = False
                for k, s in enumerate(lst):
                    if s[1] == en:
                        if s[0] == 1:
                            lst[k] = (2, en, s[3], s[3], s[2], en, (), 0)
                            ch = True
                        elif s[0] == 5:
                            lst[k] = (1, s[5], s[3], s[3], s[4], s[5], (), 0)
                            ch = True
                nb.append((c, tuple(lst) if ch else ss, memo, done, path))
            beam = nb
            continue
        if known is not None:
            cands = [sidx[known]]
        else:
            cands = list(range(NS))
        nxt = {}
        order = []
        for (c, ss, memo, done, path) in beam:
            if memo:
                memo = tuple(m for m in memo if last_ref[m[0]] >= p)
            if p in done:
                nd = tuple(x for x in done if x != p)
                key = (ss, memo, nd)
                old = nxt.get(key)
                if old is None or c < old[0]:
                    if old is None:
                        order.append(key)
                    nxt[key] = (c, ss, memo, nd, path)
                continue
            exp = []
            for k in cands:
                zero = False
                for (dc, ns) in _opts(ss[k], typ, en, o, l):
                    if ns is None:
                        exp.append((c + dc, ss, k, ()))
                    else:
                        if dc <= 0.2:
                            zero = True
                        if typ == "abort" and known is None:
                            dc += abort_pen(p, k, ss[k])
                        exp.append((c + dc, ss[:k] + (ns,) + ss[k + 1:], k, ()))
                if not zero and typ in ("write", "checkpoint", "commit") and win[p] and ss[k][0] in (1, 5):
                    for (dc, ns, ch) in pull_chains(p, k, ss[k], done):
                        exp.append((c + dc, ss[:k] + (ns,) + ss[k + 1:], k, ch))
            if dupcand[p] and memo:
                md = dict(memo)
                for q in dupcand[p]:
                    if q in md:
                        k = md[q]
                        if known is None or sidx[known] == k:
                            exp.append((c + DUP, ss, k, ()))
            if not exp:
                k = cands[0] if (known is not None and cands) else -1
                exp.append((c + FB * 2, ss, k, ()))
            for (nc, nss, k, ch) in exp:
                nm = memo
                np_ = path
                nd = done
                if ch:
                    nd = tuple(sorted(done + ch))
                    for q in ch:
                        np_ = (q, k, np_)
                        if is_orig[q]:
                            nm = nm + ((q, k),)
                if is_orig[p] and k >= 0:
                    nm = nm + ((p, k),)
                key = (nss, nm, nd)
                old = nxt.get(key)
                if old is None or nc < old[0]:
                    if old is None:
                        order.append(key)
                    nxt[key] = (nc, nss, nm, nd, (p, k, np_))
        cand = [nxt[kk] for kk in order]
        cand.sort(key=lambda x: x[0])
        el = time.process_time() - t0
        rem = n - p
        if el > budget:
            B = 1
        elif p > 10:
            per = el / (p + 1)
            if per * rem > (budget - el):
                B = max(2, int(B * 0.7))
        if cand:
            beam = cand[:B]

    best = beam[0]
    asg = {}
    path = best[4]
    while path is not None:
        p, k, path = path
        if k >= 0 and p not in asg:
            asg[p] = sids[k]
    assignments = {}
    for p, e in enumerate(evs):
        if e.get("type") != "crash" and e.get("sid") is None:
            s = asg.get(p)
            if s is None:
                s = sids[0] if sids else ""
            assignments[str(e.get("i"))] = s
    sessions = {}
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted", 5: "active"}
    for k, s in enumerate(sids):
        st = best[1][k]
        sessions[s] = {"status": names[st[0]], "durable": int(st[3])}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state

import time
import bisect

GAP = 2.0
BAD = 9.0
REC = 3.0
DUP = 1.8
LATE = 1.0
UNC = 3.5
FILL = -1.0
JIT = 1.0
FB = 6.0
ANC = 3.0

WCC = ("write", "checkpoint", "commit")


def _opts(s, typ, en, o, l, t, W, pen):
    st, node, pos, dur, holes, pre, tc, inf, pn = s
    res = []
    if typ == 'open':
        if st == 0:
            res.append((0.0, (1, en, 0, 0, (), 0, 0, 0, None)))
        return res
    if st == 0:
        return res
    act = (st == 1 or st == 5)
    dt = max(0.0, t - tc) / W if st == 2 else 0.0
    if typ == 'write':
        end = o + l
        if act and node == en:
            if o == pos:
                res.append((0.0, (st, node, end, dur, holes, pre, tc, inf, pn)))
            elif o > pos:
                res.append((GAP, (st, node, end, dur, (holes + ((pos, o),))[-4:], pre, tc, inf, pn)))
            else:
                hit = False
                for hk in range(len(holes)):
                    a, b = holes[hk]
                    if a <= o and end <= b:
                        nh = list(holes[:hk])
                        if a < o:
                            nh.append((a, o))
                        if end < b:
                            nh.append((end, b))
                        nh.extend(holes[hk + 1:])
                        res.append((FILL if a == o else 0.5,
                                    (st, node, pos, dur, tuple(nh), pre, tc, inf, pn)))
                        hit = True
                        break
                if not hit:
                    res.append((BAD if o >= dur else BAD + 2,
                                (st, node, end, dur, (), pre, tc, inf, pn)))
        if st == 5 and pn == en and o == dur:
            res.append((JIT, (1, en, end, dur, (), pre, tc, 0, None)))
        if st == 2:
            if o == dur:
                res.append((REC, (1, en, end, dur, (), pre, tc, 1, None)))
            elif o > dur:
                res.append((REC + GAP + 1, (1, en, end, dur, ((dur, o),), pre, tc, 1, None)))
            if node == en and o != dur:
                if o == pre:
                    res.append((LATE + dt, (2, node, pos, dur, (), end, tc, 0, None)))
                    res.append((UNC, (1, node, end, dur, (), pre, tc, 0, None)))
                elif dur < o and end <= pre:
                    res.append((LATE + 0.5 + dt, s))
        if (st == 3 or st == 4) and node == en:
            for (a, b) in holes:
                if a <= o and end <= b:
                    res.append((0.5 if a == o else 1.0, s))
                    break
    elif typ == 'checkpoint' or typ == 'commit':
        com = (typ == 'commit')
        if act and node == en:
            nst = 3 if com else st
            npn = pn if nst == 5 else None
            ninf = 0 if com else inf
            if o == pos:
                res.append((0.0, (nst, node, o, o, holes, pre, tc, ninf, npn)))
            elif o > pos:
                res.append((GAP, (nst, node, o, o, (holes + ((pos, o),))[-4:], pre, tc, ninf, npn)))
            elif o >= dur:
                if com:
                    res.append((LATE + 1, (3, node, o, o, (), pre, tc, 0, None)))
                else:
                    res.append((LATE, (st, node, pos, o, holes, pre, tc, inf, pn)))
            else:
                res.append((BAD, (nst, node, o, o, (), pre, tc, ninf, npn)))
        if st == 5 and pn == en and o == dur:
            res.append((JIT, (3 if com else 1, en, o, o, (), pre, tc, 0, None)))
        if st == 2:
            if node == en and dur <= o <= pre:
                if com:
                    res.append((LATE + dt, (3, node, o, o, (), pre, tc, 0, None)))
                else:
                    res.append((LATE + dt, (2, node, o, o, (), pre, tc, 0, None)))
            if o == dur:
                res.append((REC + 0.5, (3 if com else 1, en, o, o, (), pre, tc, 0 if com else 1, None)))
            elif o > dur:
                res.append((REC + GAP + 1, (3 if com else 1, en, o, o, (), pre, tc, 0 if com else 1, None)))
        if (st == 3 or st == 4) and node == en:
            if o <= pos:
                if st == 4 and o > dur and not com:
                    res.append((LATE + 0.5, (4, node, pos, o, holes, pre, tc, 0, None)))
                else:
                    res.append((LATE + 0.5, s))
            elif st == 3 and not com:
                for (a, b) in holes:
                    if a < o <= b:
                        res.append((LATE + 1, s))
                        break
    elif typ == 'abort':
        if act and node == en:
            res.append((0.3 + pen, (4, node, dur, dur, (), pre, tc, 0, None)))
        if st == 2:
            if node == en:
                res.append((LATE + dt + pen, (4, node, dur, dur, (), pre, tc, 0, None)))
            res.append((REC + 1 + pen, (4, en, dur, dur, (), pre, tc, 0, None)))
    elif typ == 'recover':
        if st == 2:
            if o == dur:
                res.append((0.0, (1, en, o, o, (), pre, tc, 0, None)))
            elif dur < o <= pre:
                res.append((GAP, (1, en, o, o, (), pre, tc, 0, None)))
            else:
                res.append((BAD - 2, (1, en, o, max(o, dur), (), pre, tc, 0, None)))
        elif st == 1:
            if inf and node == en and o == dur:
                res.append((JIT - REC, (1, node, pos, dur, holes, pre, tc, 0, None)))
            elif (not inf) and o == dur:
                res.append((JIT + 1, (5, node, pos, dur, holes, pre, tc, 0, en)))
            res.append((REC + 1.5, (1, en, o, max(o, dur), (), pos, t, 0, None)))
    if not res and (node == en or pn == en):
        res.append((FB, s))
    return res


def _fallback(state):
    inp = state["input"]
    events = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    sids = []
    for e in events:
        if e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    lastnode = {}
    status = {s: "active" for s in sids}
    dur = {s: 0 for s in sids}
    out_a = {}
    for e in events:
        if e["type"] == "crash":
            continue
        s = e.get("sid")
        if s is None:
            s = lastnode.get(e["node"], sids[0] if sids else "")
            out_a[str(e["i"])] = s
        if s in status:
            lastnode[e["node"]] = s
            if e["type"] == "commit":
                status[s] = "committed"
                if e["off"] is not None:
                    dur[s] = e["off"]
            elif e["type"] == "abort":
                status[s] = "aborted"
            elif e["type"] in ("checkpoint", "recover") and e["off"] is not None:
                dur[s] = max(dur[s], e["off"])
    state["output"] = {"assignments": out_a,
                       "sessions": {s: {"status": status[s], "durable": int(dur[s])} for s in sids}}
    return state


def _core(state):
    t0 = time.process_time()
    inp = state.get("input") or {}
    evs = sorted(inp.get("events", []) or [], key=lambda e: (e.get("t", 0) or 0, e.get("i", 0) or 0))
    sids = []
    for e in evs:
        if e.get("type") == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in evs:
        s = e.get("sid")
        if s is not None and s not in sids:
            sids.append(s)
    sidx = {s: k for k, s in enumerate(sids)}
    n = len(evs)
    NS = len(sids)
    ts = [(e.get("t", 0) or 0) for e in evs]
    gl = sorted(ts[k + 1] - ts[k] for k in range(n - 1)) or [1]
    med = gl[len(gl) // 2]
    W = max(4.0, 3.0 * max(med, 1))

    sig_prev = {}
    dupcand = [[] for _ in range(n)]
    is_orig = [False] * n
    last_ref = [-1] * n
    cont = {}
    last_known = [-1] * NS
    crashes = {}
    for p, e in enumerate(evs):
        typ = e.get("type")
        s = e.get("sid")
        if typ == "crash":
            crashes.setdefault(e.get("node"), []).append(p)
        if s is not None and s in sidx and typ != "open":
            last_known[sidx[s]] = p
        if typ in WCC:
            cont.setdefault((e.get("node"), e.get("off")), []).append(p)
        if typ in ("crash", "open"):
            continue
        sig = (typ, e.get("node"), e.get("off"), e.get("len"))
        lst = sig_prev.get(sig)
        if lst:
            dupcand[p] = lst[-4:]
            for q in dupcand[p]:
                is_orig[q] = True
                last_ref[q] = p
        sig_prev.setdefault(sig, []).append(p)

    # future anchors: known-sid non-open events that are not likely duplicates
    anchors = [[] for _ in range(NS)]
    for p, e in enumerate(evs):
        typ = e.get("type")
        s = e.get("sid")
        if typ in ("open", "crash") or s is None or s not in sidx:
            continue
        if dupcand[p]:
            continue
        anchors[sidx[s]].append(p)

    def crash_between(node, p, q):
        lst = crashes.get(node)
        if not lst:
            return False
        j = bisect.bisect_right(lst, p)
        return j < len(lst) and lst[j] < q

    cache = {}
    cur = {"p": 0}

    def hval(k, s, q, close):
        if q < 0:
            return 0.0
        st = s[0]
        if st == 0:
            return 0.0
        key = (k, s, q, close)
        v = cache.get(key)
        if v is not None:
            return v
        ae = evs[q]
        at = ae.get("type")
        an = ae.get("node")
        ao = ae.get("off") or 0
        node = s[1]
        pos = s[2]
        dur = s[3]
        v = 0.0
        if st == 3 or st == 4:
            v = 0.0 if close else ANC
        elif st == 2:
            if at == "recover":
                v = 0.0 if ao == dur else (ANC * 0.5 if ao > dur else ANC)
            elif at in WCC:
                v = 0.0 if ao >= dur else ANC
        else:
            cb = crash_between(node, cur["p"], q)
            alt = (st == 5 and an == s[8])
            if at == "recover":
                if not cb and not alt:
                    v = ANC
                elif ao != dur:
                    v = ANC * 0.5
            elif at in WCC:
                if an == node and not cb:
                    if ao < pos and not close:
                        v = ANC
                    elif at != "write" and ao < dur:
                        v = ANC
                elif cb or alt:
                    if ao < dur:
                        v = ANC
                else:
                    v = ANC
            elif at == "abort":
                if an != node and not cb and not alt:
                    v = ANC
        cache[key] = v
        return v

    def abort_pen(p, k, s):
        pen = 0.0
        if last_known[k] > p + 2:
            pen += 3.0
        lst = cont.get((s[1], s[2]))
        if lst:
            j = bisect.bisect_right(lst, p)
            while j < len(lst):
                sd = evs[lst[j]].get("sid")
                if sd is None or sd == sids[k]:
                    pen += 2.5
                    break
                j += 1
        return pen

    init_s = tuple((0, None, 0, 0, (), 0, 0, 0, None) for _ in range(NS))
    zero_h = tuple(0.0 for _ in range(NS))
    beam = [(0.0, init_s, (), None, zero_h, 0.0)]
    work = n * max(NS, 1)
    if work < 3000:
        B0 = 64
    elif work < 8000:
        B0 = 40
    else:
        B0 = 28
    B = B0
    budget = 0.75
    ctx = [None] * NS
    aptr = [0] * NS
    need_all = True
    for p, e in enumerate(evs):
        typ = e.get("type")
        en = e.get("node")
        o = e.get("off")
        l = e.get("len") or 0
        t = e.get("t", 0) or 0
        if o is None:
            o = 0
        if typ == "crash":
            nb = []
            for (c, ss, memo, path, hs, hsum) in beam:
                lst = list(ss)
                ch = False
                for k, s in enumerate(lst):
                    if s[1] == en:
                        if s[0] == 1:
                            lst[k] = (2, en, s[3], s[3], (), s[2], t, 0, None)
                            ch = True
                        elif s[0] == 5:
                            lst[k] = (1, s[8], s[3], s[3], (), s[2], t, 0, None)
                            ch = True
                nb.append((c, tuple(lst) if ch else ss, memo, path, hs, hsum))
            beam = nb
            cache.clear()
            need_all = True
            continue
        cur["p"] = p
        # update anchor contexts
        changed = []
        for k in range(NS):
            al = anchors[k]
            j = aptr[k]
            while j < len(al) and al[j] <= p:
                j += 1
            aptr[k] = j
            q = al[j] if j < len(al) else -1
            close = (q >= 0 and ts[q] - t <= W)
            c2 = (q, close)
            if c2 != ctx[k]:
                ctx[k] = c2
                changed.append(k)
        if need_all:
            changed = list(range(NS))
            need_all = False
        if changed:
            nb = []
            for (c, ss, memo, path, hs, hsum) in beam:
                hl = list(hs)
                for k in changed:
                    hl[k] = hval(k, ss[k], ctx[k][0], ctx[k][1])
                nb.append((c, ss, memo, path, tuple(hl), sum(hl)))
            beam = nb
        known = e.get("sid")
        if known is not None and known in sidx:
            cands = [sidx[known]]
        else:
            known = None
            cands = list(range(NS))
        nxt = {}
        order = []
        for (c, ss, memo, path, hs, hsum) in beam:
            if memo:
                memo = tuple(m for m in memo if last_ref[m[0]] >= p)
            exp = []
            for k in cands:
                sk = ss[k]
                if sk[0] == 0 and typ != "open":
                    continue
                pen = 0.0
                if typ == "abort" and known is None:
                    pen = abort_pen(p, k, sk)
                for (dc, ns) in _opts(sk, typ, en, o, l, t, W, pen):
                    if ns is sk:
                        exp.append((c + dc, ss, k))
                    else:
                        exp.append((c + dc, ss[:k] + (ns,) + ss[k + 1:], k))
            if dupcand[p] and memo:
                md = dict(memo)
                for q in dupcand[p]:
                    if q in md:
                        k = md[q]
                        if known is None or sidx[known] == k:
                            exp.append((c + DUP, ss, k))
            if not exp:
                if known is not None:
                    k = cands[0]
                else:
                    fb = [j for j in range(NS) if ss[j][1] == en and ss[j][0] != 0] or \
                         [j for j in range(NS) if ss[j][0] != 0] or list(range(NS))
                    k = fb[0] if fb else -1
                exp.append((c + 25.0, ss, k))
            for (nc, nss, k) in exp:
                nm = memo
                if is_orig[p] and k >= 0:
                    nm = memo + ((p, k),)
                key = (nss, nm)
                old = nxt.get(key)
                if old is None or nc < old[0]:
                    if nss is ss or k < 0:
                        nhs = hs
                        nhsum = hsum
                    else:
                        hv = hval(k, nss[k], ctx[k][0], ctx[k][1])
                        nhs = hs[:k] + (hv,) + hs[k + 1:]
                        nhsum = hsum - hs[k] + hv
                    if old is None:
                        order.append(key)
                    nxt[key] = (nc, nss, nm, (p, k, path), nhs, nhsum)
        cand = [nxt[kk] for kk in order]
        cand.sort(key=lambda x: x[0] + x[5])
        if cand:
            beam = cand[:B]
        el = time.process_time() - t0
        if el > budget:
            B = 1
        elif p > 8:
            proj = el / (p + 1) * n
            if proj > budget:
                B = max(2, int(B * 0.75))
            elif proj < 0.4 * budget and B < B0:
                B = min(B0, B + 2)

    best = min(beam, key=lambda x: x[0])
    asg = {}
    path = best[3]
    while path is not None:
        p, k, path = path
        if k >= 0:
            asg[p] = sids[k]
    assignments = {}
    for p, e in enumerate(evs):
        if e.get("type") != "crash" and e.get("sid") is None:
            s = asg.get(p)
            if s is None:
                s = sids[0] if sids else ""
            assignments[str(e.get("i"))] = s
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted", 5: "active"}
    sessions = {}
    for k, s in enumerate(sids):
        st = best[1][k]
        sessions[s] = {"status": names[st[0]], "durable": int(st[3])}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state


def solve(state, params):
    try:
        return _core(state)
    except Exception:
        return _fallback(state)

import time
from bisect import bisect_right, insort


def solve(state, params):
    t_start = time.process_time()
    inp = state["input"]
    evs = inp["events"]
    n = len(evs)
    T = [e["t"] for e in evs]
    ND = [e["node"] for e in evs]
    TY = [e["type"] for e in evs]
    OF = [e["off"] for e in evs]
    LN = [e["len"] for e in evs]
    SIG = [(ND[i], TY[i], OF[i], LN[i]) for i in range(n)]
    INF = float("inf")

    crash_t = {}
    for i in range(n):
        if TY[i] == "crash":
            crash_t.setdefault(ND[i], []).append(T[i])
    for k in crash_t:
        crash_t[k].sort()

    open_ev = {}
    anon = []
    for i in range(n):
        if TY[i] == "crash":
            continue
        s = evs[i]["sid"]
        if TY[i] == "open" and s is not None:
            open_ev[s] = i
        if s is None:
            anon.append(i)
    sids = sorted(open_ev, key=lambda s: (T[open_ev[s]], s))
    sess_ev = {}
    for s in sids:
        sess_ev[s] = []
    owner = {}
    for i in range(n):
        s = evs[i]["sid"]
        if s is not None and TY[i] != "crash":
            if s not in sess_ev:
                # session without visible open: create a pseudo session anchored at this event
                continue
            owner[i] = s
            if TY[i] != "open":
                sess_ev[s].append((T[i], i))
    for s in sids:
        sess_ev[s].sort()

    if not sids:
        state["output"] = {"assignments": {}, "sessions": {}}
        return state

    sig_events = {}
    for i in range(n):
        if TY[i] not in ("crash", "open"):
            sig_events.setdefault(SIG[i], []).append(i)

    # ---- jitter window estimate ----
    gaps = sorted(T[i + 1] - T[i] for i in range(n - 1))
    med = gaps[len(gaps) // 2] if gaps else 1
    inv = 0
    for s in sids:
        seq = [i for _, i in sess_ev[s] if TY[i] in ("write", "checkpoint", "commit")]
        start_at = {}
        for i in seq:
            if TY[i] == "write":
                start_at[(ND[i], OF[i])] = i
        for i in seq:
            if TY[i] == "write":
                j = start_at.get((ND[i], OF[i] + LN[i]))
                if j is not None and T[j] < T[i]:
                    inv = max(inv, T[i] - T[j])
            else:
                j = start_at.get((ND[i], OF[i]))
                if j is not None and T[j] < T[i] and TY[i] == "checkpoint":
                    inv = max(inv, T[i] - T[j])
    W = max(inv * 1.3, med * 3.0, 1.0)

    B = 1.0
    G = 2.0
    C = 6.0
    CI = 3.0
    CN = 6.0
    MR = 2.0
    GC = 1.5
    DUP = 0.4

    def item_key(i):
        o = OF[i]
        ty = TY[i]
        if o is None:
            o = 1 << 60
        if ty == "checkpoint" or ty == "recover":
            r = 0
        elif ty == "write":
            r = 1
        else:
            r = 2
        return (o, r, T[i])

    def evaluate(s, lst):
        o = open_ev[s]
        cost = 0.0
        seen = set()
        segs = []
        node = ND[o]
        start = T[o]
        D = 0
        pos = 0
        prev_end = 0
        k = 0
        m = len(lst)
        status = "active"
        final_dur = 0
        later = False
        while True:
            cl = crash_t.get(node, ())
            ci = bisect_right(cl, start)
            Tc = cl[ci] if ci < len(cl) else INF
            items = []
            while k < m and lst[k][0] <= Tc:
                items.append(lst[k][1])
                k += 1
            if Tc < INF:
                while (k < m and lst[k][0] <= Tc + W and TY[lst[k][1]] != "recover"
                       and ND[lst[k][1]] == node):
                    items.append(lst[k][1])
                    k += 1
            items.sort(key=item_key)
            maxt = start
            ended = None
            for i in items:
                ty = TY[i]
                sg = SIG[i]
                if ended is not None:
                    cost += DUP if sg in seen else C
                    continue
                if ND[i] != node:
                    if sg in seen:
                        cost += DUP
                    else:
                        cost += CN
                        seen.add(sg)
                    continue
                if ty == "abort":
                    if sg in seen:
                        cost += DUP
                        continue
                    seen.add(sg)
                    ended = "aborted"
                    pos = D
                    continue
                if ty == "recover":
                    if sg in seen:
                        cost += DUP
                    else:
                        cost += C
                        seen.add(sg)
                    continue
                off = OF[i]
                if off == pos and not (sg in seen and ty == "write" and not later):
                    cost -= B
                elif sg in seen:
                    cost += DUP
                    continue
                elif off > pos:
                    cost += G
                else:
                    cost += C
                seen.add(sg)
                if T[i] < maxt - W:
                    cost += CI
                elif T[i] > maxt:
                    maxt = T[i]
                if ty == "write":
                    pos = off + LN[i]
                    if pos > prev_end:
                        prev_end = pos
                else:
                    if off > pos:
                        pos = off
                    if off > prev_end:
                        prev_end = off
                    D = pos
                    if ty == "commit":
                        ended = "committed"
            if ended is not None:
                while k < m:
                    i = lst[k][1]
                    k += 1
                    cost += DUP if SIG[i] in seen else C
                segs.append((node, start, maxt + W, False))
                status = ended
                final_dur = D
                break
            if Tc == INF:
                segs.append((node, start, INF, False))
                status = "active"
                final_dur = D
                break
            segs.append((node, start, Tc, True))
            pos = D
            later = True
            while k < m and SIG[lst[k][1]] in seen and TY[lst[k][1]] != "recover":
                cost += DUP
                k += 1
            if k >= m:
                status = "down"
                final_dur = D
                break
            rj = -1
            tlim = lst[k][0] + W
            j = k
            while j < m and lst[j][0] <= tlim:
                if TY[lst[j][1]] == "recover" and SIG[lst[j][1]] not in seen:
                    rj = j
                    break
                j += 1
            crash_end = Tc
            if rj >= 0:
                if rj != k:
                    lst = list(lst)
                    it = lst.pop(rj)
                    lst.insert(k, it)
                ri = lst[k][1]
                k += 1
                seen.add(SIG[ri])
                R = OF[ri]
                if R is None:
                    R = D
                if R == D:
                    cost -= B
                elif R > D:
                    cost += GC
                    D = R
                else:
                    cost += C
                pos = R
                node = ND[ri]
                start = T[ri]
            else:
                cost += MR
                fi = lst[k][1]
                node = ND[fi]
                start = T[fi]
                fo = OF[fi]
                if fo is not None and fo > D and fo <= prev_end and TY[fi] == "write":
                    cost += GC
                    D = fo
                    pos = fo
            segs.append(("down", crash_end, start, False))
        return (cost, segs, status, final_dur)

    cache = {}
    for s in sids:
        cache[s] = evaluate(s, sess_ev[s])

    def candidates(i, cur):
        out = []
        ti = T[i]
        nd = ND[i]
        dup_owners = set()
        for j in sig_events.get(SIG[i], ()):
            if j != i and T[j] <= ti:
                ow = owner.get(j)
                if ow is not None:
                    dup_owners.add(ow)
        for s in sids:
            if T[open_ev[s]] > ti:
                continue
            ok = s == cur or s in dup_owners
            if not ok:
                for sg in cache[s][1]:
                    if sg[0] == "down":
                        if sg[1] - W <= ti <= sg[2] + W:
                            ok = True
                            break
                    elif sg[0] == nd and sg[1] - W <= ti <= sg[2] + W:
                        ok = True
                        break
            if not ok and cache[s][2] == "down" and ti >= cache[s][1][-1][2] - W:
                ok = True
            if ok:
                out.append(s)
        if not out:
            out = [s for s in sids if T[open_ev[s]] <= ti] or list(sids)
        return out

    def cheap_pick(i, cs):
        best = None
        for s in cs:
            lt = -INF
            for tt, j in reversed(sess_ev[s]):
                if tt <= T[i] and ND[j] == ND[i]:
                    lt = tt
                    break
            if lt == -INF and ND[open_ev[s]] == ND[i]:
                lt = T[open_ev[s]]
            if best is None or lt > best[0]:
                best = (lt, s)
        return best[1]

    assign = {}
    hard_limit = 0.85
    for i in anon:
        cs = candidates(i, None)
        if time.process_time() - t_start > hard_limit or len(cs) == 1:
            s = cs[0] if len(cs) == 1 else cheap_pick(i, cs)
            nl = list(sess_ev[s])
            insort(nl, (T[i], i))
            sess_ev[s] = nl
            if time.process_time() - t_start <= hard_limit:
                cache[s] = evaluate(s, nl)
            assign[i] = s
            owner[i] = s
            continue
        best = None
        for s in cs:
            nl = list(sess_ev[s])
            insort(nl, (T[i], i))
            r = evaluate(s, nl)
            d = r[0] - cache[s][0]
            if best is None or d < best[0] - 1e-9:
                best = (d, s, nl, r)
        d, s, nl, r = best
        sess_ev[s] = nl
        cache[s] = r
        assign[i] = s
        owner[i] = s

    if time.process_time() - t_start > hard_limit:
        for s in sids:
            cache[s] = evaluate(s, sess_ev[s])

    budget = 0.7
    improved = True
    rounds = 0
    while improved and time.process_time() - t_start < budget and rounds < 8:
        improved = False
        rounds += 1
        for i in anon:
            if time.process_time() - t_start > budget:
                break
            a = assign[i]
            cs = [s for s in candidates(i, a) if s != a]
            if not cs:
                continue
            la = [x for x in sess_ev[a] if x[1] != i]
            ra = evaluate(a, la)
            base = cache[a][0] - ra[0]
            best = None
            for s in cs:
                nl = list(sess_ev[s])
                insort(nl, (T[i], i))
                r = evaluate(s, nl)
                d = r[0] - cache[s][0] - base
                if d < -1e-9 and (best is None or d < best[0]):
                    best = (d, s, nl, r)
            if best is not None:
                d, s, nl, r = best
                sess_ev[a] = la
                cache[a] = ra
                sess_ev[s] = nl
                cache[s] = r
                assign[i] = s
                owner[i] = s
                improved = True
        if improved:
            continue
        by_node = {}
        for i in anon:
            by_node.setdefault(ND[i], []).append(i)
        for nd in sorted(by_node):
            lst_i = by_node[nd]
            for x in range(len(lst_i)):
                if time.process_time() - t_start > budget:
                    break
                i = lst_i[x]
                for y in range(x + 1, min(len(lst_i), x + 8)):
                    j = lst_i[y]
                    a = assign[i]
                    b = assign[j]
                    if a == b or TY[i] != TY[j]:
                        continue
                    if T[open_ev[a]] > T[j] or T[open_ev[b]] > T[i]:
                        continue
                    la = [z for z in sess_ev[a] if z[1] != i]
                    insort(la, (T[j], j))
                    lb = [z for z in sess_ev[b] if z[1] != j]
                    insort(lb, (T[i], i))
                    ra = evaluate(a, la)
                    rb = evaluate(b, lb)
                    if ra[0] + rb[0] < cache[a][0] + cache[b][0] - 1e-9:
                        sess_ev[a] = la
                        sess_ev[b] = lb
                        cache[a] = ra
                        cache[b] = rb
                        assign[i] = b
                        assign[j] = a
                        owner[i] = b
                        owner[j] = a
                        improved = True

    sessions = {}
    for s in sids:
        c = cache[s]
        sessions[s] = {"status": c[2], "durable": int(c[3])}
    state["output"] = {
        "assignments": {str(i): assign[i] for i in anon},
        "sessions": sessions,
    }
    return state

import time
import bisect

GAP = 2.5
MREC = 2.5
JIT = 1.0
JITC = 1.5
FB = 5.0
DUP = 2.0
DEF = 0.7
MAXP = 3
WIN = 15
EXACT_TOL = 0.25


def _opts(s, typ, en, o, l):
    st, node, off, dur, poff, pnode, gaps, inf = s
    res = []
    if typ == 'open':
        if st == 0:
            res.append((0.0, (1, en, 0, 0, 0, en, (), 0)))
        return res
    if st == 0:
        return res
    if typ == 'write':
        if (st == 1 or st == 5) and node == en:
            if o == off:
                res.append((0.0, (st, node, o + l, dur, poff, pnode, gaps, inf)))
            elif o > off:
                g2 = (gaps + ((off, o),))[-3:]
                res.append((GAP, (st, node, o + l, dur, poff, pnode, g2, inf)))
            else:
                for k, g in enumerate(gaps):
                    if g[0] == o and o + l <= g[1]:
                        if o + l < g[1]:
                            g2 = gaps[:k] + ((o + l, g[1]),) + gaps[k + 1:]
                            res.append((JIT - 0.5 * GAP, (st, node, off, dur, poff, pnode, g2, inf)))
                        else:
                            g2 = gaps[:k] + gaps[k + 1:]
                            res.append((JIT - GAP, (st, node, off, dur, poff, pnode, g2, inf)))
                        break
        if st == 5 and pnode == en and o == dur:
            res.append((JIT, (1, en, o + l, dur, poff, pnode, (), 0)))
        if st == 2:
            if o == dur:
                res.append((MREC, (1, en, o + l, dur, poff, en, (), 1)))
            elif o > dur:
                res.append((MREC + GAP, (1, en, o + l, dur, poff, en, (), 1)))
            if pnode == en and o == poff:
                res.append((JITC, (st, node, off, dur, o + l, pnode, gaps, inf)))
    elif typ == 'checkpoint':
        if (st == 1 or st == 5) and node == en:
            if o == off:
                res.append((0.0, (st, node, off, o, poff, pnode, gaps, inf)))
            elif o > off:
                res.append((GAP, (st, node, o, o, poff, pnode, (), inf)))
            elif o >= dur:
                res.append((JIT + 0.5, (st, node, off, o, poff, pnode, gaps, inf)))
        if st == 2:
            if pnode == en and o == poff:
                res.append((JITC, (2, node, o, o, o, pnode, (), 0)))
            if o == dur:
                res.append((MREC, (1, en, o, o, poff, en, (), 1)))
            elif o > dur:
                res.append((MREC + GAP, (1, en, o, o, poff, en, (), 1)))
    elif typ == 'commit':
        if (st == 1 or st == 5) and node == en:
            if o == off:
                res.append((0.0, (3, node, o, o, poff, pnode, (), 0)))
            elif o > off:
                res.append((GAP, (3, node, o, o, poff, pnode, (), 0)))
        if st == 5 and pnode == en and o == dur:
            res.append((JIT, (3, en, o, o, poff, pnode, (), 0)))
        if st == 2:
            if pnode == en and o == poff:
                res.append((JITC, (3, node, o, o, o, pnode, (), 0)))
            if o == dur:
                res.append((MREC, (3, en, o, o, poff, en, (), 0)))
            elif o > dur:
                res.append((MREC + GAP, (3, en, o, o, poff, en, (), 0)))
    elif typ == 'abort':
        if (st == 1 or st == 5) and node == en:
            res.append((0.2, (4, node, dur, dur, poff, pnode, (), 0)))
        if st == 2:
            if pnode == en:
                res.append((JITC, (4, node, dur, dur, poff, pnode, (), 0)))
            res.append((MREC, (4, en, dur, dur, poff, en, (), 0)))
    elif typ == 'recover':
        if st == 2:
            if o == dur:
                res.append((0.0, (1, en, o, o, poff, en, (), 0)))
            elif o > dur:
                res.append((GAP, (1, en, o, o, poff, en, (), 0)))
            else:
                res.append((GAP + 1.0, (1, en, o, o, poff, en, (), 0)))
        elif st == 1:
            if inf and node == en and o == dur:
                res.append((JIT - MREC, (1, node, off, dur, poff, pnode, gaps, 0)))
            elif o == dur and not inf:
                res.append((JIT + 1.0, (5, node, off, dur, poff, en, gaps, 0)))
    if not res and (node == en or pnode == en):
        res.append((FB, None))
    return res


def _make_engine(ts, dupcand, is_orig, last_ref, abort_pen):
    DEFERRABLE = ("write", "checkpoint", "commit", "recover")

    def run(items, NS, B0, budget, adaptive):
        # items: list of (p, typ, en, o, l, cands, kn) in log order
        t0 = time.process_time()
        imap = {}
        for it in items:
            imap[it[0]] = it

        def expand(c, ss, memo, path, q, exact):
            _, typ, en, o, l, cands, kn = imap[q]
            exp = []
            for k in cands:
                for (dc, ns) in _opts(ss[k], typ, en, o, l):
                    if ns is None:
                        if exact:
                            continue
                        exp.append((c + dc, ss, k))
                    else:
                        if typ == "abort" and kn < 0 and abort_pen is not None:
                            dc += abort_pen(q, k, ss[k])
                        if exact and dc > EXACT_TOL:
                            continue
                        exp.append((c + dc, ss[:k] + (ns,) + ss[k + 1:], k))
            if not exact:
                if dupcand[q] and memo:
                    md = dict(memo)
                    for r in dupcand[q]:
                        if r in md:
                            k = md[r]
                            if kn < 0 or kn == k:
                                exp.append((c + DUP, ss, k))
                if not exp:
                    exp.append((c + FB * 2, ss, kn))
            out = []
            for (nc, nss, k) in exp:
                nm = memo
                if is_orig[q] and k >= 0:
                    nm = memo + ((q, k),)
                out.append((nc, nss, nm, (q, k, path)))
            return out

        def settle(h, tnow, force_all, force_node):
            res = []
            stack = [h]
            guard = 0
            while stack:
                guard += 1
                c, ss, memo, path, pend = stack.pop()
                if not pend:
                    res.append((c, ss, memo, path, pend))
                    continue
                done = False
                for idx, q in enumerate(pend):
                    ex = expand(c, ss, memo, path, q, True)
                    if ex:
                        rest = pend[:idx] + pend[idx + 1:]
                        for (nc, nss, nm, npth) in ex:
                            stack.append((nc, nss, nm, npth, rest))
                        done = True
                        break
                if done:
                    continue
                fidx = -1
                for idx, q in enumerate(pend):
                    if force_all or tnow - ts[q] > WIN or (force_node is not None and imap[q][2] == force_node) or guard > 400:
                        fidx = idx
                        break
                if fidx >= 0:
                    q = pend[fidx]
                    rest = pend[:fidx] + pend[fidx + 1:]
                    for (nc, nss, nm, npth) in expand(c, ss, memo, path, q, False):
                        stack.append((nc, nss, nm, npth, rest))
                    continue
                res.append((c, ss, memo, path, pend))
            return res

        def prune(lst, B):
            nxt = {}
            for h in lst:
                key = (h[1], h[2], h[4])
                old = nxt.get(key)
                if old is None or h[0] < old[0]:
                    nxt[key] = h
            cand = list(nxt.values())
            cand.sort(key=lambda x: x[0])
            return cand[:B]

        init_s = tuple((0, None, 0, 0, 0, None, (), 0) for _ in range(NS))
        beam = [(0.0, init_s, (), None, ())]
        B = B0
        nit = len(items)
        for ii, it in enumerate(items):
            p, typ, en, o, l, cands, kn = it
            if typ == "crash":
                nb = []
                for h in beam:
                    for (c, ss, memo, path, pend) in settle(h, ts[p], False, en):
                        lst = list(ss)
                        ch = False
                        for k, s in enumerate(lst):
                            if s[1] == en:
                                if s[0] == 1:
                                    lst[k] = (2, en, s[3], s[3], s[2], en, (), 0)
                                    ch = True
                                elif s[0] == 5:
                                    lst[k] = (1, s[5], s[3], s[3], s[4], s[5], (), 0)
                                    ch = True
                        nb.append((c, tuple(lst) if ch else ss, memo, path, pend))
                if nb:
                    beam = prune(nb, B)
                continue
            allh = []
            for (c, ss, memo, path, pend) in beam:
                if memo:
                    memo = tuple(m for m in memo if last_ref[m[0]] >= p)
                new = [x + (pend,) for x in expand(c, ss, memo, path, p, False)]
                if typ in DEFERRABLE and len(pend) < MAXP:
                    new.append((c + DEF, ss, memo, path, pend + (p,)))
                for h2 in new:
                    allh.extend(settle(h2, ts[p], False, None))
            if adaptive:
                el = time.process_time() - t0
                rem = nit - ii
                if el > budget:
                    B = 1
                elif ii > 10:
                    per = el / (ii + 1)
                    if per * rem > (budget - el):
                        B = max(2, int(B * 0.7))
            if allh:
                beam = prune(allh, B)
        fin = []
        for h in beam[:max(1, min(len(beam), 8))]:
            fin.extend(settle(h, 10 ** 12, True, None))
        if not fin:
            fin = [(0.0, init_s, (), None, ())]
        fin.sort(key=lambda x: x[0])
        return fin[0]

    return run


def solve(state, params):
    T0 = time.process_time()
    inp = state.get("input") or {}
    evs = sorted(inp.get("events", []) or [], key=lambda e: (e.get("t", 0) or 0, e.get("i", 0) or 0))
    sids = []
    for e in evs:
        if e.get("type") == "open" and e.get("sid") is not None and e["sid"] not in sids:
            sids.append(e["sid"])
    for e in evs:
        s = e.get("sid")
        if s is not None and s not in sids:
            sids.append(s)
    sidx = {s: k for k, s in enumerate(sids)}
    n = len(evs)
    NS = len(sids)
    ts = [(e.get("t", 0) or 0) for e in evs]

    sig_prev = {}
    dupcand = [[] for _ in range(n)]
    is_orig = [False] * n
    last_ref = [-1] * n
    cont = {}
    last_known = [-1] * NS
    info = []
    for p, e in enumerate(evs):
        typ = e.get("type")
        s = e.get("sid")
        if s is not None and s in sidx and typ != "open":
            last_known[sidx[s]] = p
        if typ in ("write", "checkpoint", "commit"):
            cont.setdefault((e.get("node"), e.get("off")), []).append(p)
        o = e.get("off")
        if o is None:
            o = 0
        l = e.get("len") or 0
        if s is not None and s in sidx:
            kn = sidx[s]
            cands = [kn]
        else:
            kn = -1
            cands = list(range(NS))
        info.append((p, typ, e.get("node"), o, l, cands, kn))
        if typ in ("crash", "open"):
            continue
        sig = (typ, e.get("node"), e.get("off"), e.get("len"))
        lst = sig_prev.get(sig)
        if lst:
            dupcand[p] = lst[-4:]
            for q in dupcand[p]:
                is_orig[q] = True
                last_ref[q] = p
        sig_prev.setdefault(sig, []).append(p)

    def abort_pen(p, k, s):
        pen = 0.0
        if last_known[k] > p + 2:
            pen += 3.0
        lst = cont.get((s[1], s[2]))
        if lst:
            j = bisect.bisect_right(lst, p)
            while j < len(lst):
                sd = evs[lst[j]].get("sid")
                if sd is None or sd == sids[k]:
                    pen += 2.5
                    break
                j += 1
        return pen

    run = _make_engine(ts, dupcand, is_orig, last_ref, abort_pen)

    # ---------- stage 1: global beam ----------
    best = run(info, NS, 40, 0.5, True)
    asg = {}
    path = best[3]
    while path is not None:
        q, k, path = path
        if k >= 0 and q not in asg:
            asg[q] = k
    for p in range(n):
        typ = info[p][1]
        if typ != "crash" and p not in asg:
            kn = info[p][6]
            asg[p] = kn if kn >= 0 else 0
    beam_states = best[1]

    # ---------- stage 2: local search over per-session replay costs ----------
    crash_items = [it for it in info if it[1] == "crash"]
    run_local = _make_engine(ts, dupcand, is_orig, last_ref, None)
    cache = {}

    def eval_set(mem):
        key = mem
        r = cache.get(key)
        if r is not None:
            return r
        items = []
        for p in mem:
            it = info[p]
            items.append((p, it[1], it[2], it[3], it[4], [0], 0))
        items.extend(crash_items)
        items.sort(key=lambda x: x[0])
        b = run_local(items, 1, 5, 1.0, False)
        r = (b[0], b[1][0])
        cache[key] = r
        return r

    members = [[] for _ in range(NS)]
    for p in range(n):
        if info[p][1] != "crash" and NS > 0:
            members[asg[p]].append(p)
    memt = [tuple(m) for m in members]
    orig_memt = list(memt)
    deadline = 0.86
    changed = False
    if NS > 1:
        anon = [p for p in range(n) if info[p][1] not in ("crash", "open") and info[p][6] < 0]
        # partner (duplicate) map
        partner = {}
        for p in anon:
            for r in dupcand[p]:
                partner.setdefault(p, []).append(r)
                partner.setdefault(r, []).append(p)
        cost = [None] * NS
        ok = True
        for k in range(NS):
            if time.process_time() - T0 > deadline:
                ok = False
                break
            cost[k] = eval_set(memt[k])[0]

        def compatible(q, k):
            _, typ, en, o, l, _, _ = info[q]
            mem = memt[k]
            if not mem:
                return False
            if mem[0] > q + 6:
                return False
            if typ == "recover":
                return True
            nodes_ok = False
            ends = set()
            starts = set()
            for p in mem:
                it = info[p]
                if it[2] == en:
                    nodes_ok = True
                if it[1] == "write":
                    ends.add(it[3] + it[4])
                    starts.add(it[3])
                elif it[1] in ("checkpoint", "commit", "recover"):
                    ends.add(it[3])
                    starts.add(it[3])
            if typ == "abort":
                return nodes_ok
            if o == 0 and nodes_ok:
                return True
            if o in ends:
                return True
            if typ == "write" and (o + l) in starts:
                return True
            if typ in ("checkpoint", "commit") and o in starts:
                return True
            return False

        passes = 0
        while ok and passes < 3:
            passes += 1
            improved = False
            for q in anon:
                if time.process_time() - T0 > deadline:
                    ok = False
                    break
                k0 = asg[q]
                groups = [(q,)]
                for r in partner.get(q, []):
                    if asg.get(r) == k0 and info[r][6] < 0:
                        groups.append(tuple(sorted((q, r))))
                best_move = None
                best_gain = 1e-9
                for grp in groups:
                    rm = tuple(x for x in memt[k0] if x not in grp)
                    c_rm = eval_set(rm)[0]
                    for k in range(NS):
                        if k == k0 or not compatible(q, k):
                            continue
                        if time.process_time() - T0 > deadline:
                            break
                        ad = tuple(sorted(memt[k] + grp))
                        c_ad = eval_set(ad)[0]
                        gain = cost[k0] + cost[k] - c_rm - c_ad
                        if gain > best_gain:
                            best_gain = gain
                            best_move = (grp, k, rm, ad, c_rm, c_ad)
                if best_move is not None:
                    grp, k, rm, ad, c_rm, c_ad = best_move
                    memt[k0] = rm
                    memt[k] = ad
                    cost[k0] = c_rm
                    cost[k] = c_ad
                    for x in grp:
                        asg[x] = k
                    improved = True
                    changed = True
            if not improved:
                break

    assignments = {}
    for p, e in enumerate(evs):
        if e.get("type") != "crash" and e.get("sid") is None:
            k = asg.get(p)
            s = sids[k] if (k is not None and 0 <= k < NS) else (sids[0] if sids else "")
            assignments[str(e.get("i"))] = s
    sessions = {}
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted", 5: "active"}
    for k, s in enumerate(sids):
        st = beam_states[k]
        if changed and memt[k] != orig_memt[k]:
            r = cache.get(memt[k])
            if r is None and time.process_time() - T0 < 0.95:
                r = eval_set(memt[k])
            if r is not None:
                st = r[1]
        sessions[s] = {"status": names[st[0]], "durable": int(st[3])}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state

import time
import bisect

INF = 1e9


def _median(xs):
    if not xs:
        return 1
    ys = sorted(xs)
    return ys[len(ys) // 2]


def _fallback(inp):
    evs = inp.get("events", []) or []
    sids = []
    for e in evs:
        s = e.get("sid")
        if s and s not in sids:
            sids.append(s)
    asg = {}
    st = {}
    for s in sids:
        st[s] = {"status": "active", "durable": 0}
    last = {}
    for e in sorted(evs, key=lambda z: (z.get("t", 0), z.get("i", 0))):
        if e.get("type") == "crash":
            continue
        if e.get("sid"):
            last[e.get("node")] = e["sid"]
        else:
            s = last.get(e.get("node")) or (sids[0] if sids else "s0")
            asg[str(e.get("i"))] = s
    for e in evs:
        s = e.get("sid")
        if s and e.get("type") == "commit":
            st[s] = {"status": "committed", "durable": e.get("off") or 0}
    return {"assignments": asg, "sessions": st}


def _best(Ck):
    b1 = INF
    s1 = None
    b2 = INF
    for s, v in Ck.items():
        if v < b1:
            b2 = b1
            b1 = v
            s1 = s
        elif v < b2:
            b2 = v
    return (b1, s1, b2)


def _solve(inp, t0):
    evs = sorted(inp.get("events", []) or [], key=lambda z: (z["t"], z["i"]))
    crashes = {}
    for e in evs:
        if e["type"] == "crash":
            crashes.setdefault(e["node"], []).append(e["t"])

    def crash_between(node, a, b):
        Lc = crashes.get(node)
        if not Lc or b <= a:
            return False
        k = bisect.bisect_right(Lc, a)
        return k < len(Lc) and Lc[k] < b

    def io(e):
        ty = e["type"]
        off = e.get("off")
        if ty == "write":
            if off is None:
                return None, None
            return off, off + (e.get("len") or 0)
        if ty in ("checkpoint", "commit", "recover"):
            if off is None:
                return None, None
            return off, off
        if ty == "open":
            return None, 0
        return None, None

    ts = [e["t"] for e in evs]
    diffs = [ts[j + 1] - ts[j] for j in range(len(ts) - 1) if ts[j + 1] - ts[j] > 0]
    g = max(1, _median(diffs))

    # jitter estimate from labelled exact links
    lab = {}
    for e in evs:
        if e["type"] != "crash" and e.get("sid"):
            a, b = io(e)
            lab.setdefault(e["sid"], []).append((e["t"], a, b, e["node"], e["type"]))
    maxinv = 0
    for s, Ls in lab.items():
        byin = {}
        for x in Ls:
            if x[1] is not None:
                byin.setdefault(x[1], []).append(x)
        for a in Ls:
            if a[4] != "write":
                continue
            for b in byin.get(a[2], []):
                if b is a:
                    continue
                if b[0] < a[0] and not crash_between(a[3], b[0], a[0]):
                    d = a[0] - b[0]
                    if d < 40 * g and d > maxinv:
                        maxinv = d
    JW = max(3.0 * g, 1.3 * maxinv, 1.0)
    W2 = 40.0 * JW

    # duplicate merging
    groups = []
    sigmap = {}
    gid_of = {}
    for e in evs:
        ty = e["type"]
        if ty == "crash":
            continue
        a, b = io(e)
        sig = (e["node"], ty, e.get("off"), e.get("len"))
        merged = False
        if ty != "open":
            win = 12 * JW if ty == "write" else 4 * JW
            cands = sigmap.get(sig, [])
            for gc in reversed(cands):
                G0 = groups[gc]
                if e["t"] - G0["t"] > win:
                    break
                if len(G0["mem"]) >= 2:
                    continue
                if e["t"] <= G0["t"]:
                    continue
                if e.get("sid") and G0["sid"] and e["sid"] != G0["sid"]:
                    continue
                if ty != "write" and crash_between(e["node"], G0["t"], e["t"]):
                    continue
                G0["mem"].append(e["i"])
                if e.get("sid"):
                    G0["sid"] = e["sid"]
                gid_of[e["i"]] = gc
                merged = True
                break
        if not merged:
            gn = len(groups)
            groups.append({"t": e["t"], "node": e["node"], "type": ty, "in": a, "out": b,
                           "sid": e.get("sid"), "mem": [e["i"]], "off": e.get("off"), "s": None})
            sigmap.setdefault(sig, []).append(gn)
            gid_of[e["i"]] = gn

    sids = []
    for gr in groups:
        if gr["type"] == "open" and gr["sid"] and gr["sid"] not in sids:
            sids.append(gr["sid"])
    for gr in groups:
        if gr["sid"] and gr["sid"] not in sids:
            sids.append(gr["sid"])
    sess_g = {s: [] for s in sids}
    for k, gr in enumerate(groups):
        if gr["sid"]:
            gr["s"] = gr["sid"]
            sess_g[gr["sid"]].append(k)

    def build(s):
        L = sorted(sess_g[s], key=lambda kk: (groups[kk]["t"], kk))
        I = {"L": L, "T": [groups[kk]["t"] for kk in L], "outs": {}, "ins": {}, "end": None, "open": None}
        for kk in L:
            x = groups[kk]
            if x["out"] is not None:
                I["outs"].setdefault(x["out"], []).append(kk)
            if x["in"] is not None:
                I["ins"].setdefault(x["in"], []).append(kk)
            if x["type"] in ("commit", "abort"):
                if I["end"] is None or x["t"] < I["end"]:
                    I["end"] = x["t"]
            if x["type"] == "open":
                I["open"] = x["t"]
        return I

    info = {s: build(s) for s in sids}

    def fit(k, s):
        x = groups[k]
        I = info[s]
        t = x["t"]
        ty = x["type"]
        nd = x["node"]
        ot = I["open"]
        if ot is not None and t < ot:
            return INF
        end = I["end"]
        if ty in ("commit", "abort"):
            if end is not None:
                return INF
        elif end is not None and t > end + JW:
            return INF
        T = I["T"]
        L = I["L"]
        n = len(L)
        p = bisect.bisect_right(T, t)
        prev = groups[L[p - 1]] if p > 0 else None
        nxt = groups[L[p]] if p < n else None
        c = 0.0
        rec_soon = nxt is not None and nxt["type"] == "recover" and nxt["t"] <= t + JW
        if ty != "recover":
            ok = (prev is not None and prev["node"] == nd) or (nxt is not None and nxt["node"] == nd)
            if not ok:
                c += 4.0
            if prev is not None and not rec_soon and crash_between(prev["node"], prev["t"], t - JW):
                c += 2.5
        else:
            if prev is not None and not crash_between(prev["node"], prev["t"] - JW, t + JW):
                c += 3.0
        a = x["in"]
        b = x["out"]
        if a is not None:
            pc = 2.5
            for kk in I["outs"].get(a, ()):
                y = groups[kk]
                if y["t"] <= t + JW and (ty == "recover" or y["node"] == nd):
                    pc = 0.0
                    break
            if pc > 0:
                j = p - 1
                lim = max(-1, p - 7)
                while j > lim:
                    y = groups[L[j]]
                    j -= 1
                    if y["out"] is not None and y["out"] < a:
                        pc = 1.2
                        break
            c += pc
        if b is not None and ty != "commit":
            sc = 1.0
            for kk in I["ins"].get(b, ()):
                y = groups[kk]
                if y["t"] >= t - JW and (y["node"] == nd or y["type"] == "recover"):
                    sc = 0.0
                    break
            c += sc
        if ty == "write" and a is not None:
            for kk in I["ins"].get(a, ()):
                y = groups[kk]
                if y["type"] == "write" and not crash_between(nd, min(y["t"], t), max(y["t"], t)):
                    c += 5.0
                    break
        if ty not in ("recover", "abort") and a is not None:
            j = p - 1
            cnt = 0
            while j >= 0 and cnt < 8:
                y = groups[L[j]]
                j -= 1
                cnt += 1
                if y["t"] >= t - JW:
                    continue
                if crash_between(nd, y["t"], t):
                    break
                if y["out"] is not None and y["out"] > a:
                    c += 3.0
                    break
                if y["type"] == "recover":
                    break
            j = p
            cnt = 0
            while j < n and cnt < 8:
                y = groups[L[j]]
                j += 1
                cnt += 1
                if y["t"] <= t + JW:
                    continue
                if y["type"] == "recover" or crash_between(nd, t, y["t"]):
                    break
                if y["in"] is not None and b is not None and y["in"] < b:
                    c += 3.0
                    break
        if ty == "abort":
            if n and T[-1] > t + JW:
                c += 6.0
            if prev is not None:
                c += 0.5 * min(1.0, (t - prev["t"]) / (20.0 * JW))
        else:
            d = None
            if prev is not None:
                d = t - prev["t"]
            if nxt is not None:
                dd = nxt["t"] - t
                if d is None or dd < d:
                    d = dd
            if d is not None:
                c += 0.3 * min(1.0, d / (20.0 * JW))
        return c

    rem = [k for k in range(len(groups)) if groups[k]["s"] is None and groups[k]["type"] != "open"]
    C = {}
    bestc = {}
    for k in rem:
        Ck = {}
        for s in sids:
            Ck[s] = fit(k, s)
        C[k] = Ck
        bestc[k] = _best(Ck)
    remset = set(rem)
    deadline = 0.55
    while remset:
        if time.perf_counter() - t0 > deadline:
            break
        cands = []
        for k in remset:
            b1, s1, b2 = bestc[k]
            if s1 is None or b1 >= 50:
                continue
            m = min(b2, 50.0) - b1
            cands.append((-m, b1, groups[k]["t"], k))
        if not cands:
            break
        cands.sort()
        batch = []
        used = set()
        for negm, b1, tt, k in cands:
            if -negm < 1.5:
                break
            s = bestc[k][1]
            x = groups[k]
            if x["type"] in ("commit", "abort"):
                key = (s, "end")
            else:
                key = (s, x["type"], x["in"])
            if key in used:
                continue
            used.add(key)
            batch.append((k, s))
        if not batch:
            k = cands[0][3]
            batch = [(k, bestc[k][1])]
        changed = {}
        for k, s in batch:
            groups[k]["s"] = s
            sess_g[s].append(k)
            remset.discard(k)
            changed.setdefault(s, []).append(k)
        for s in changed:
            info[s] = build(s)
        for s, newks in changed.items():
            full = len(newks) > 15 or any(groups[kk]["type"] in ("recover", "commit", "abort") for kk in newks)
            for k in remset:
                x = groups[k]
                if not full:
                    hit = x["type"] == "abort"
                    if not hit:
                        for kk in newks:
                            y = groups[kk]
                            if abs(x["t"] - y["t"]) <= W2 or \
                                    (x["in"] is not None and x["in"] == y["out"]) or \
                                    (x["out"] is not None and x["out"] == y["in"]):
                                hit = True
                                break
                    if not hit:
                        continue
                C[k][s] = fit(k, s)
                bestc[k] = _best(C[k])

    for k in sorted(remset):
        s = bestc[k][1]
        if s is None:
            x = groups[k]
            bs = None
            bt = None
            for s2 in sids:
                ot = info[s2]["open"]
                if ot is not None and ot <= x["t"] and (bt is None or ot > bt):
                    bt = ot
                    bs = s2
            s = bs or (sids[0] if sids else "s0")
        groups[k]["s"] = s
        if s in sess_g:
            sess_g[s].append(k)

    # final per-session replay
    crash_items = []
    for nd, Lc in crashes.items():
        for tc in Lc:
            crash_items.append((tc, 0, nd))
    sessions = {}
    for s in sids:
        L = sorted(sess_g[s], key=lambda kk: (groups[kk]["t"], kk))
        commits = [groups[kk] for kk in L if groups[kk]["type"] == "commit"]
        if commits:
            sessions[s] = {"status": "committed", "durable": commits[0]["off"] or 0}
            continue
        items = list(crash_items)
        for kk in L:
            items.append((groups[kk]["t"], 1, kk))
        items.sort(key=lambda z: (z[0], z[1], str(z[2])))
        dur = 0
        down = False
        crash_t = None
        aborted = False
        cur = None
        opened = False
        pend = None
        for it in items:
            if it[1] == 0:
                tc = it[0]
                nd = it[2]
                if not opened or aborted:
                    continue
                if pend is not None and tc - pend[0] > JW:
                    pend = None
                if pend is not None and nd == pend[1]:
                    pend = None
                    continue
                if not down and nd == cur:
                    down = True
                    crash_t = tc
                continue
            x = groups[it[2]]
            ty = x["type"]
            if ty == "open":
                opened = True
                cur = x["node"]
                continue
            if aborted:
                continue
            if not opened:
                opened = True
                cur = x["node"]
            if down:
                if ty == "recover" or x["t"] > crash_t + JW:
                    down = False
                    cur = x["node"]
                    if ty == "recover" and x["off"] is not None:
                        dur = max(dur, x["off"])
                    elif ty == "checkpoint" and x["off"] is not None:
                        dur = max(dur, x["off"])
                    elif ty == "abort":
                        aborted = True
                else:
                    if ty == "checkpoint" and x["off"] is not None:
                        dur = max(dur, x["off"])
                continue
            if ty == "recover":
                if x["off"] is not None:
                    dur = max(dur, x["off"])
                pend = (x["t"], cur)
                cur = x["node"]
            elif ty == "checkpoint":
                if x["off"] is not None:
                    dur = max(dur, x["off"])
            elif ty == "abort":
                aborted = True
            else:
                cur = x["node"]
        if aborted:
            stt = "aborted"
        elif down:
            stt = "down"
        else:
            stt = "active"
        sessions[s] = {"status": stt, "durable": int(dur)}

    asg = {}
    for e in evs:
        if e["type"] == "crash" or e.get("sid"):
            continue
        gk = gid_of.get(e["i"])
        s = groups[gk]["s"] if gk is not None else None
        if s is None:
            s = sids[0] if sids else "s0"
        asg[str(e["i"])] = s
    return {"assignments": asg, "sessions": sessions}


def solve(state, params):
    t0 = time.perf_counter()
    inp = state.get("input") or {}
    try:
        out = _solve(inp, t0)
    except Exception:
        try:
            out = _fallback(inp)
        except Exception:
            out = {"assignments": {}, "sessions": {}}
    state["output"] = out
    return state

import bisect


def _median(xs):
    if not xs:
        return 1
    xs = sorted(xs)
    return xs[len(xs) // 2]


def solve(state, params):
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    events = []
    for k, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        typ = e.get("type")
        if typ not in ("open", "write", "checkpoint", "commit", "abort", "recover", "crash"):
            continue
        t = e.get("t")
        if not isinstance(t, (int, float)):
            t = 0
        off = e.get("off")
        if not isinstance(off, (int, float)):
            off = None
        ln = e.get("len")
        if not isinstance(ln, (int, float)):
            ln = None
        if typ == "write" and ln is None:
            ln = 0
        if typ == "write" and off is None:
            off = None
        sid = e.get("sid")
        if typ == "crash" or not isinstance(sid, str) or sid == "":
            sid = None
        idx = e.get("i", k)
        events.append({"i": idx, "t": t, "node": str(e.get("node")), "type": typ,
                       "off": off, "len": ln, "sid": sid, "k": k})
    events.sort(key=lambda e: (e["t"], e["k"]))
    n = len(events)

    gaps = [events[j + 1]["t"] - events[j]["t"] for j in range(n - 1)
            if events[j + 1]["t"] > events[j]["t"]]
    mg = max(1, _median(gaps))
    WJ = 12 * mg
    WD = 40 * mg
    K = 8

    S = {}

    def mk(sid):
        if sid not in S:
            S[sid] = {"st": "pending", "node": None, "off": 0, "dur": 0, "pre": 0,
                      "cnode": None, "ct": 0, "imp": False, "last": 0, "hist": {}}
        return S[sid]

    lab = {}
    for p, e in enumerate(events):
        if e["sid"] is not None:
            mk(e["sid"])
            lab.setdefault(e["sid"], []).append(p)

    def nextlab(sid, p):
        L = lab.get(sid)
        if not L:
            return None
        j = bisect.bisect_right(L, p)
        while j < len(L):
            q = L[j]
            if events[q]["type"] != "open":
                return q
            j += 1
        return None

    def key(e):
        return (e["node"], e["type"], e["off"], e["len"])

    dupidx = {}

    def fit(e, sid):
        s = S[sid]
        st = s["st"]
        typ = e["type"]
        N = e["node"]
        off = e["off"]
        t = e["t"]
        if st == "pending":
            return None
        if st in ("committed", "aborted"):
            if typ in ("write", "checkpoint") and s["node"] == N and t - s["last"] <= WJ \
                    and off is not None and off <= s["off"]:
                return 4.0
            return None
        if typ == "write":
            if off is None:
                return 5.0 if (st == "active" and s["node"] == N) else None
            ln = e["len"] or 0
            if st == "active":
                if s["node"] != N:
                    return None
                d = off - s["off"]
                if d == 0:
                    return 0.0
                if d > 0:
                    return 2.0
                if off >= s["dur"] and off + ln <= s["off"]:
                    return 3.0
                return 6.0
            if N == s["cnode"] and s["dur"] <= off < s["pre"] and t - s["ct"] <= WJ:
                return 1.5
            if off == s["dur"]:
                return 2.5
            return None
        if typ in ("checkpoint", "commit"):
            if off is None:
                return 5.0 if (st == "active" and s["node"] == N) else None
            if st == "active":
                if s["node"] != N:
                    return None
                if off == s["off"]:
                    return 0.0
                if off > s["off"]:
                    return 2.0
                if off >= s["dur"]:
                    return 3.0
                return 6.0
            if N == s["cnode"] and s["dur"] < off <= s["pre"] and t - s["ct"] <= WJ:
                return 1.5
            if off == s["dur"]:
                return 2.5
            return None
        if typ == "recover":
            if st == "down":
                if off is None or off == s["dur"]:
                    return 0.0
                return 4.0
            if st == "active" and s["imp"]:
                if off is None or off == s["dur"]:
                    return 0.5 if s["node"] == N else 1.0
                return 5.0
            return None
        if typ == "abort":
            if st == "active" and s["node"] == N:
                return 1.0
            return None
        return None

    def newoff(e, s):
        typ = e["type"]
        off = e["off"]
        if off is None:
            return s["off"], s["dur"]
        if typ == "write":
            if s["st"] == "down" and e["node"] == s["cnode"] and off < s["pre"] and off != s["dur"]:
                return s["dur"], s["dur"]
            o = off + (e["len"] or 0)
            return (max(o, s["off"]) if s["st"] == "active" else o), s["dur"]
        if typ in ("checkpoint", "commit"):
            return max(off, s["off"] if s["st"] == "active" else 0), max(off, s["dur"])
        if typ == "recover":
            return (max(off, s["off"]) if s["st"] == "active" else off), off
        return s["off"], s["dur"]

    def future(e, sid, p):
        q = nextlab(sid, p)
        typ = e["type"]
        if q is None:
            return 0.1
        nl = events[q]
        if typ in ("abort", "commit"):
            if nl["type"] in ("abort", "commit") or nl["t"] - e["t"] <= WJ:
                return 0.0
            return 5.0
        s = S[sid]
        no, nd = newoff(e, s)
        if nl["type"] in ("write", "checkpoint", "commit") and nl["off"] is not None:
            if nl["off"] == no:
                return 0.0
            if nl["off"] > no:
                return 0.3
            if nl["off"] >= nd:
                return 0.6
            return 2.0
        if nl["type"] == "recover" and nl["off"] is not None:
            if nl["off"] >= nd:
                return 0.1
            return 1.0
        return 0.1

    def options(e, p):
        opts = []
        for sid in S:
            c = fit(e, sid)
            if c is None:
                continue
            c += future(e, sid, p)
            opts.append((c, -S[sid]["last"], sid, False))
        L = dupidx.get(key(e))
        if L:
            for (tt, sid) in reversed(L):
                if 0 <= e["t"] - tt <= WD:
                    opts.append((0.25, 0, sid, True))
                    break
        if not opts:
            for sid, s in S.items():
                c = 50.0
                if s["st"] in ("active", "down"):
                    c = 20.0 if s["node"] == e["node"] else 30.0
                elif s["st"] == "pending":
                    c = 60.0
                opts.append((c, -s["last"], sid, False))
        opts.sort()
        return opts

    def best(e, p):
        if e["type"] == "crash":
            return (0.0, None, False)
        if e["type"] == "open":
            return (0.0, e["sid"], False)
        if e["sid"] is not None:
            sid = e["sid"]
            s = S[sid]
            c = fit(e, sid)
            if (c is None or c > 0) and key(e) in s["hist"]:
                return (0.25, sid, True)
            if c is None:
                c = 10.0
            return (c, sid, False)
        opts = options(e, p)
        if not opts:
            return (99.0, None, False)
        o = opts[0]
        return (o[0], o[2], o[3])

    assign = {}

    def apply_crash(e):
        N = e["node"]
        for s in S.values():
            if s["st"] == "active" and s["node"] == N:
                s["st"] = "down"
                s["pre"] = s["off"]
                s["off"] = s["dur"]
                s["cnode"] = N
                s["ct"] = e["t"]
                s["imp"] = False

    def apply(e, sid, isdup):
        if e["sid"] is None and e["type"] != "crash":
            if sid is not None:
                assign[str(e["i"])] = sid
        if sid is None:
            return
        s = mk(sid)
        k = key(e)
        s["hist"][k] = 1
        dupidx.setdefault(k, []).append((e["t"], sid))
        if isdup:
            return
        typ = e["type"]
        N = e["node"]
        off = e["off"]
        t = e["t"]
        st = s["st"]
        if t > s["last"]:
            s["last"] = t
        if typ == "open":
            if st == "pending":
                s["st"] = "active"
                s["node"] = N
                s["off"] = 0
                s["dur"] = 0
            return
        if st == "pending":
            s["st"] = "active"
            s["node"] = N
            st = "active"
        late = (st == "down" and N == s["cnode"] and off is not None
                and t - s["ct"] <= WJ and s["dur"] <= off <= s["pre"])
        if typ == "write":
            ln = e["len"] or 0
            if off is None:
                return
            if st == "down":
                if late and off < s["pre"] and not (off == s["dur"] and t - s["ct"] > WJ // 2):
                    return
                s["st"] = "active"
                s["node"] = N
                s["imp"] = True
                s["off"] = max(s["dur"], off) + ln
                return
            if st == "active" and off + ln > s["off"]:
                s["off"] = off + ln
            return
        if typ == "checkpoint":
            if off is None:
                if st == "active":
                    s["dur"] = s["off"]
                return
            if st == "down":
                if late and off > s["dur"]:
                    s["dur"] = off
                    s["off"] = off
                    return
                s["st"] = "active"
                s["node"] = N
                s["imp"] = True
                s["off"] = max(off, s["dur"])
                s["dur"] = s["off"]
                return
            if st == "active":
                if off > s["off"]:
                    s["off"] = off
                if off > s["dur"]:
                    s["dur"] = off
            return
        if typ == "commit":
            s["st"] = "committed"
            if off is not None:
                s["off"] = off
                s["dur"] = off
            else:
                s["dur"] = s["off"]
            return
        if typ == "abort":
            if st in ("active", "down"):
                s["st"] = "aborted"
                s["off"] = s["dur"]
            return
        if typ == "recover":
            if st == "down":
                s["st"] = "active"
                s["node"] = N
                o = off if off is not None else s["dur"]
                s["off"] = o
                s["dur"] = o
                s["imp"] = False
                return
            if st == "active":
                s["node"] = N
                s["imp"] = False
                if off is not None and off > s["dur"]:
                    s["dur"] = off
                    if s["off"] < off:
                        s["off"] = off
            return

    buf = []
    p = 0
    while True:
        while len(buf) < K and p < n:
            buf.append(p)
            p += 1
        if not buf:
            break
        q0 = buf[0]
        e0 = events[q0]
        pick = 0
        if e0["type"] == "crash":
            N = e0["node"]
            for j in range(1, len(buf)):
                ej = events[buf[j]]
                if ej["type"] in ("crash", "open", "recover") or ej["node"] != N:
                    continue
                if ej["t"] - e0["t"] > WJ:
                    break
                c, sid, isd = best(ej, buf[j])
                if sid is not None and not isd and c == 0.0 and S[sid]["st"] == "active" \
                        and S[sid]["node"] == N:
                    pick = j
                    break
        elif e0["type"] != "open":
            c0, sid0, d0 = best(e0, q0)
            if c0 > 1.0:
                if e0["sid"] is not None:
                    cands = {e0["sid"]}
                else:
                    cands = set()
                    for sid in S:
                        cc = fit(e0, sid)
                        if cc is not None and cc > 0:
                            cands.add(sid)
                for j in range(1, len(buf)):
                    ej = events[buf[j]]
                    if ej["type"] == "crash":
                        if e0["type"] == "recover" and c0 >= 4.0:
                            pick = j
                            break
                        if e0["type"] != "recover" and ej["node"] == e0["node"]:
                            break
                        continue
                    if ej["type"] == "open":
                        continue
                    c, sid, isd = best(ej, buf[j])
                    if sid in cands and not isd and c == 0.0:
                        pick = j
                        break
        qp = buf.pop(pick)
        ep = events[qp]
        if ep["type"] == "crash":
            apply_crash(ep)
            continue
        c, sid, isd = best(ep, qp)
        apply(ep, sid, isd)

    anysid = sorted(S.keys())
    for e in events:
        if e["sid"] is None and e["type"] != "crash" and str(e["i"]) not in assign:
            assign[str(e["i"])] = anysid[0] if anysid else "s0"

    sessions = {}
    for sid, s in S.items():
        st = s["st"]
        if st == "pending":
            st = "active"
        sessions[sid] = {"status": st, "durable": int(s["dur"])}
    state["output"] = {"assignments": assign, "sessions": sessions}
    return state

import time

C_GAP = 3.0
C_JIT = 0.7
C_STALE = 8.0
C_DUP = 1.5
C_MISSREC = 3.5
C_LATE = 2.5
C_EARLYREC = 3.0
C_MISSCK = 3.0
C_COMMIT_BACK = 5.0
C_ABSURD = 25.0
TYPES = {"open": 0, "write": 1, "checkpoint": 2, "commit": 3, "abort": 4, "recover": 5, "crash": 6}


def _toint(x):
    try:
        if x is None:
            return None
        return int(x)
    except Exception:
        return None


def _addgap(gaps, a, b):
    g = gaps + ((a, b),)
    if len(g) > 3:
        g = g[-3:]
    return g


def _fill(gaps, a, b):
    for k, (g0, g1) in enumerate(gaps):
        if g0 <= a and b <= g1 and b > a:
            pieces = []
            if a > g0:
                pieces.append((g0, a))
            if b < g1:
                pieces.append((b, g1))
            ng = gaps[:k] + tuple(pieces) + gaps[k + 1:]
            return ng, C_GAP * (1 - len(pieces))
    return None


def _trans(S, typ, nd, off, ln):
    # S = (st, node, off, dur, gaps, aux)
    # st: 0 pending, 1 active, 2 down, 3 committed, 4 aborted, 5 active (recovered early, crash still pending on node aux)
    st, sn, so, du, gp, ax = S
    out = []
    if typ == 0:
        if st == 0:
            out.append((0.0, (1, nd, 0, 0, (), -1)))
        return out
    if st == 0:
        return out
    if off is None and typ in (1, 2, 3, 5):
        off = so
    if typ == 1:
        if ln is None:
            ln = 0
        if st == 1 or st == 5:
            if sn == nd:
                if off == so:
                    out.append((0.0, (st, sn, off + ln, du, gp, ax)))
                elif off > so:
                    out.append((C_GAP, (st, sn, off + ln, du, _addgap(gp, so, off), ax)))
                else:
                    f = _fill(gp, off, off + ln)
                    if f is not None:
                        out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
                    else:
                        out.append((C_STALE, S))
        elif st == 2:
            if off >= du:
                if off == du:
                    out.append((C_MISSREC, (1, nd, off + ln, du, gp, -1)))
                else:
                    out.append((C_MISSREC + C_GAP, (1, nd, off + ln, du, _addgap(gp, du, off), -1)))
                if sn == nd:
                    out.append((C_LATE, S))
            else:
                f = _fill(gp, off, off + ln)
                if f is not None:
                    out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
        else:
            f = _fill(gp, off, off + ln)
            if f is not None:
                out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
        return out
    if typ == 2 or typ == 3:
        if st == 1 or st == 5:
            if sn == nd:
                nst = 3 if typ == 3 else st
                if off == so:
                    out.append((0.0, (nst, sn, off, off, gp, ax)))
                elif off > so:
                    out.append((C_GAP, (nst, sn, off, off, _addgap(gp, so, off), ax)))
                elif off >= du:
                    if typ == 2:
                        out.append((C_JIT, (st, sn, so, off, gp, ax)))
                    else:
                        out.append((C_COMMIT_BACK, (3, sn, off, off, gp, ax)))
                else:
                    out.append((C_STALE, S))
        elif st == 2:
            if off >= du:
                nst = 3 if typ == 3 else 1
                c = C_MISSREC + (C_GAP if off > du else 0.0)
                out.append((c, (nst, nd, off, off, gp, -1)))
                if sn == nd and typ == 2:
                    out.append((C_LATE, (2, sn, off, off, gp, ax)))
        return out
    if typ == 4:
        if st == 1 or st == 5:
            if sn == nd:
                out.append((0.0, (4, sn, so, du, gp, ax)))
        elif st == 2:
            out.append((C_MISSREC * 0.6, (4, sn, so, du, gp, ax)))
        return out
    if typ == 5:
        if st == 2:
            if off == du:
                out.append((0.0, (1, nd, off, off, gp, -1)))
            elif off > du:
                out.append((C_MISSCK, (1, nd, off, off, gp, -1)))
            else:
                out.append((C_STALE, (1, nd, du, du, gp, -1)))
        elif st == 1:
            if du <= off <= so:
                out.append((C_EARLYREC + (0.0 if off == du else C_MISSCK * 0.5),
                            (5, nd, off, off, gp, sn)))
        return out
    return out


def _crash(S, nd):
    st = S[0]
    if st == 1:
        if S[1] == nd:
            du = S[3]
            return (2, nd, du, du, tuple(g for g in S[4] if g[1] <= du), -1)
        return S
    if st == 5:
        if S[5] == nd:
            return (1, S[1], S[2], S[3], S[4], -1)
        if S[1] == nd:
            du = S[3]
            return (2, nd, du, du, tuple(g for g in S[4] if g[1] <= du), -1)
    return S


def solve(state, params):
    t_start = time.process_time()
    budget = 0.72
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    nodes = list(inp.get("nodes") or [])
    evs = []
    for pos, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        i = e.get("i", pos)
        t = _toint(e.get("t"))
        evs.append((t if t is not None else 0, pos, e, i))
    evs.sort(key=lambda x: (x[0], x[1]))
    node_idx = {}
    for n in nodes:
        if n not in node_idx:
            node_idx[n] = len(node_idx)
    sids = []
    sid_idx = {}
    for _, _, e, _ in evs:
        s = e.get("sid")
        if s is not None and s not in sid_idx:
            sid_idx[s] = len(sids)
            sids.append(s)
    E = []
    for t, pos, e, i in evs:
        typ = TYPES.get(e.get("type"), -1)
        if typ < 0:
            continue
        nn = e.get("node")
        if nn not in node_idx:
            node_idx[nn] = len(node_idx)
        s = e.get("sid")
        E.append((typ, node_idx[nn], _toint(e.get("off")), _toint(e.get("len")),
                  sid_idx[s] if s is not None else -1, i, t))
    nS = len(sids)
    nE = len(E)

    # duplicate candidates: earlier events with identical node/type/off/len
    dupc = {}
    origset = set()
    seen = {}
    for k, (typ, nd, off, ln, si, i, t) in enumerate(E):
        if typ == 0 or typ == 6:
            continue
        key = (typ, nd, off, ln)
        lst = seen.get(key)
        if lst:
            dupc[k] = lst[-4:]
            for j in lst[-4:]:
                origset.add(j)
        seen.setdefault(key, []).append(k)

    init = tuple((0, -1, 0, 0, (), -1) for _ in range(nS))
    # hypothesis: (cost, sessions, assignment linked list, origmap)
    beam = [(0.0, init, None, {})]
    K = 32
    KMAX = 48
    KMIN = 3
    BR = 6
    DELTA = 12.0
    for k in range(nE):
        typ, nd, off, ln, si, i, t = E[k]
        if k % 8 == 0 and k > 0:
            el = time.process_time() - t_start
            proj = el * nE / k
            if proj > budget:
                K = max(KMIN, int(K * 0.7))
            elif proj < budget * 0.5 and K < KMAX:
                K = min(KMAX, K + 4)
            if el > budget * 1.15:
                K = 1
        if typ == 6:
            cm = {}
            merged = {}
            for h in beam:
                ns = []
                for S in h[1]:
                    r = cm.get(id(S))
                    if r is None:
                        r = _crash(S, nd)
                        cm[id(S)] = r
                    ns.append(r)
                ns = tuple(ns)
                o = merged.get(ns)
                if o is None or h[0] < o[0]:
                    merged[ns] = (h[0], ns, h[2], h[3])
            beam = sorted(merged.values(), key=lambda x: x[0])[:max(1, K)]
            continue
        if nS == 0:
            continue
        memo = {}
        cands = [si] if si >= 0 else range(nS)
        dl = dupc.get(k)
        isorig = k in origset
        newc = []
        for hidx, h in enumerate(beam):
            hc, sess, asg, om = h
            opts = []
            for s in cands:
                S = sess[s]
                r = memo.get(id(S))
                if r is None:
                    r = _trans(S, typ, nd, off, ln)
                    memo[id(S)] = r
                for c, NS in r:
                    opts.append((c, s, NS))
            if dl:
                ds = set()
                for j in dl:
                    s = om.get(j)
                    if s is not None and (si < 0 or s == si) and s not in ds:
                        ds.add(s)
                        opts.append((C_DUP, s, None))
            if not opts:
                if si >= 0:
                    fs = si
                else:
                    fs = 0
                    bd = None
                    for s in range(nS):
                        S = sess[s]
                        if S[0] != 0 and S[1] == nd:
                            d = abs(S[2] - (off if off is not None else S[2]))
                            if bd is None or d < bd:
                                bd = d
                                fs = s
                opts.append((C_ABSURD, fs, None))
            opts.sort(key=lambda x: (x[0], x[1]))
            best = opts[0][0]
            for c, s, NS in opts[:BR]:
                if c > best + DELTA:
                    break
                newc.append((hc + c, hidx, s, NS))
        if not newc:
            continue
        newc.sort(key=lambda x: (x[0], x[1], x[2]))
        merged = set()
        out = []
        for c, hidx, s, NS in newc:
            h = beam[hidx]
            sess = h[1]
            if NS is not None and NS != sess[s]:
                l = list(sess)
                l[s] = NS
                ns = tuple(l)
            else:
                ns = sess
            if ns in merged:
                continue
            om = h[3]
            if isorig:
                om = dict(om)
                om[k] = s
            merged.add(ns)
            out.append((c, ns, (k, s, h[2]), om))
            if len(out) >= max(1, K):
                break
        beam = out

    best = beam[0] if beam else (0.0, init, None, {})
    assign = {}
    node = best[2]
    while node is not None:
        k, s, node = node
        assign[k] = s
    assignments = {}
    if nS > 0:
        for k, (typ, nd, off, ln, si, i, t) in enumerate(E):
            if typ == 6 or si >= 0:
                continue
            s = assign.get(k, 0)
            assignments[str(i)] = sids[s]
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted", 5: "active"}
    sessions = {}
    for s in range(nS):
        S = best[1][s]
        du = S[2] if S[0] == 3 else S[3]
        sessions[sids[s]] = {"status": names.get(S[0], "active"), "durable": int(du)}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state

import bisect
import heapq
import math
import time

INF = float("inf")
NONTERM = ("open", "write", "checkpoint", "recover")
SESSION_TYPES = ("open", "write", "checkpoint", "commit", "abort", "recover")


def _ival(x):
    if x is None:
        return None
    try:
        return int(x)
    except Exception:
        try:
            return int(float(x))
        except Exception:
            return None


# ---------------------------------------------------------------- parsing
def prep_events(state, params):
    state["_t0"] = time.process_time()
    try:
        inp = state.get("input") or {}
        raw = inp.get("events") or []
        evs = []
        for k, e in enumerate(raw):
            if not isinstance(e, dict):
                continue
            i = _ival(e.get("i"))
            if i is None:
                i = k
            try:
                t = float(e.get("t") or 0)
            except Exception:
                t = 0.0
            ty = str(e.get("type") or "")
            off = _ival(e.get("off"))
            ln = _ival(e.get("len"))
            if ty == "write" and ln is None:
                ln = 0
            sid = e.get("sid")
            sid = str(sid) if sid is not None else None
            evs.append({"i": i, "t": t, "node": str(e.get("node")), "type": ty,
                        "off": off, "len": ln, "sid": sid})
        evs.sort(key=lambda x: (x["t"], x["i"]))
        for k, e in enumerate(evs):
            e["k"] = k
        state["_evs"] = evs
    except Exception:
        state["_failed"] = True
    return state


def _end(e):
    ty = e["type"]
    if ty == "open":
        return 0
    if e["off"] is None:
        return None
    if ty == "write":
        return e["off"] + (e["len"] or 0)
    if ty in ("checkpoint", "recover", "commit"):
        return e["off"]
    return None


def _durb(e):
    """(bound on durable offset right after e, whether the bound is exact)."""
    ty = e["type"]
    if ty == "open":
        return 0, True
    if e["off"] is None:
        return None, False
    if ty in ("checkpoint", "recover"):
        return e["off"], True
    if ty == "write":
        return e["off"], False
    return None, False


# ------------------------------------------------- sparse min-cost assignment
def _lap(nrows, adjd, ncols):
    """Every row gets exactly one column (each row owns a private dummy column).
    Shortest augmenting paths (Dijkstra) with column potentials (JV style)."""
    v = [0.0] * ncols
    col_row = [-1] * ncols
    row_col = [-1] * nrows
    row_cost = [0.0] * nrows
    for r in range(nrows):
        dist = {}
        pred = {}
        done = []
        dset = set()
        h = []
        for j, c in adjd[r].items():
            d = c - v[j]
            if d < dist.get(j, INF):
                dist[j] = d
                pred[j] = r
                h.append((d, j))
        heapq.heapify(h)
        final = -1
        mu = 0.0
        while h:
            d, j = heapq.heappop(h)
            if j in dset or d > dist[j]:
                continue
            if col_row[j] < 0:
                final = j
                mu = d
                break
            dset.add(j)
            done.append(j)
            i2 = col_row[j]
            base = d - (row_cost[i2] - v[j])
            for k, c in adjd[i2].items():
                if k in dset:
                    continue
                nd = base + c - v[k]
                if nd < dist.get(k, INF) - 1e-12:
                    dist[k] = nd
                    pred[k] = i2
                    heapq.heappush(h, (nd, k))
        if final < 0:
            continue
        for j in done:
            v[j] += dist[j] - mu
        j = final
        while True:
            i = pred[j]
            prevj = row_col[i]
            row_col[i] = j
            col_row[j] = i
            row_cost[i] = adjd[i][j]
            if i == r:
                break
            j = prevj
    return row_col


# ------------------------------------------------------ parameter estimates
def estimate_params(state, params):
    if state.get("_failed"):
        return state
    try:
        evs = state["_evs"]
        sess = [e for e in evs if e["type"] in SESSION_TYPES]
        opens = [e for e in evs if e["type"] == "open"]
        S = max(1, len(opens))
        span = max(1.0, evs[-1]["t"] - evs[0]["t"]) if evs else 1.0
        G = max(1.0, span * S / max(1, len(sess)))
        by = {}
        for e in sess:
            if e["sid"] is not None:
                by.setdefault(e["sid"], []).append(e)
        gaps = []
        inv = []
        for sid, lst in by.items():
            for a, b in zip(lst, lst[1:]):
                gaps.append(b["t"] - a["t"])
            endm = {}
            for a in lst:
                if a["type"] == "write" and a["off"] is not None:
                    endm.setdefault((a["node"], _end(a)), []).append(a)
            for b in lst:
                if b["type"] in ("write", "checkpoint", "commit") and b["off"] is not None:
                    for a in endm.get((b["node"], b["off"]), []):
                        if a is not b and a["t"] > b["t"] and a["t"] - b["t"] < 4 * G:
                            inv.append(a["t"] - b["t"])
        if gaps:
            gaps.sort()
            gm = gaps[len(gaps) // 2]
            if gm > 0:
                G = max(1.0, min(G, 2.0 * gm))
        inv.sort()
        J = inv[-1] * 1.25 + 0.5 if inv else 2.0
        J = max(1.0, min(J, 4 * G + 2))
        state["_G"] = G
        state["_J"] = J
    except Exception:
        state["_failed"] = True
    return state


# ------------------------------------------------------------ edge building
def _build_edges(evs, G, J):
    crash = {}
    for e in evs:
        if e["type"] == "crash":
            crash.setdefault(e["node"], []).append(e["t"])
    for v in crash.values():
        v.sort()

    def cbetween(node, lo, hi):
        lst = crash.get(node)
        if not lst or hi <= lo:
            return False
        p = bisect.bisect_right(lst, lo)
        return p < len(lst) and lst[p] < hi

    W = 2.0 * J + 1.0
    prov = [e for e in evs if e["type"] in NONTERM and (e["type"] == "open" or e["off"] is not None)]
    endmap = {}
    for a in prov:
        endmap.setdefault(_end(a), []).append(a)
    pnode = {}
    for a in prov:
        pnode.setdefault(a["node"], []).append(a)
    pnode_t = {nd: [a["t"] for a in lst] for nd, lst in pnode.items()}
    prov_t = [a["t"] for a in prov]
    twinkey = {}
    for e in evs:
        if e["type"] in SESSION_TYPES and e["type"] != "open":
            twinkey.setdefault((e["node"], e["type"], e["off"], e["len"]), []).append(e)
    Tlong = max(8.0 * G, 4 * W)

    def tcost(g):
        if g >= 0:
            x = g / G
            return 0.25 * x + 0.03 * x * x
        return 1.2 * (-g) / (J + 1.0)

    def cost(a, b):
        if a["k"] == b["k"]:
            return None
        g = b["t"] - a["t"]
        if g < -W:
            return None
        if a["type"] == "open" and b["k"] < a["k"]:
            return None
        lab = 0.0
        if a["sid"] is not None and b["sid"] is not None:
            if a["sid"] != b["sid"]:
                return None
            lab = -2.0
        E = _end(a)
        db, dex = _durb(a)
        if E is None or db is None:
            return None
        an = a["node"]
        cposs = cbetween(an, a["t"] - J - 0.5, b["t"] + J + 0.5)
        cdef = cbetween(an, a["t"] + J + 0.5, b["t"] - J - 0.5)
        ty = b["type"]
        o = b["off"]
        c = None
        if ty == "recover":
            if not cposs or o is None:
                return None
            if o == db:
                c = 0.3
            elif not dex and o < db:
                c = 0.8
            elif o > E:
                c = 5.0
            elif not dex:
                c = 4.0
            else:
                c = 6.0
        elif ty == "abort":
            if b["node"] != an or cdef:
                return None
            c = 0.6 + (0.8 if cposs else 0.0)
        elif ty in ("write", "checkpoint", "commit"):
            if o is None:
                return None
            same = b["node"] == an
            if same and not cdef:
                if o == E:
                    c = 0.6 if cposs else 0.0
                elif o > E:
                    c = 3.0 + (0.6 if cposs else 0.0)
                elif cposs and ((o == db) if dex else (o <= db)):
                    c = 4.5
            if c is None and (cposs or cdef):
                if (o == db) if dex else (o <= db):
                    c = 4.0
                elif o > E:
                    c = 7.0
        else:
            return None
        if c is None:
            return None
        return c + lab + tcost(g)

    nc = {}
    for a in prov:
        lst = crash.get(a["node"])
        if lst:
            p = bisect.bisect_right(lst, a["t"] - J - 0.5)
            nc[a["k"]] = lst[p] if p < len(lst) else INF
        else:
            nc[a["k"]] = INF
    rows = [e for e in evs if e["type"] in SESSION_TYPES and e["type"] != "open"]
    full = []
    for r, b in enumerate(rows):
        cands = {}
        tb = b["t"]
        if b["off"] is not None and b["type"] != "abort":
            for a in endmap.get(b["off"], ()):
                cands[a["k"]] = a
        lst = pnode.get(b["node"])
        if lst:
            tl = pnode_t[b["node"]]
            lo = bisect.bisect_left(tl, tb - Tlong)
            hi = bisect.bisect_right(tl, tb + W)
            for a in lst[lo:hi]:
                cands[a["k"]] = a
        if b["type"] != "abort" and crash:
            lim = tb + J + 0.5
            lo = bisect.bisect_left(prov_t, tb - 2 * Tlong)
            hi = bisect.bisect_right(prov_t, tb + W)
            isrec = b["type"] == "recover"
            bo = b["off"]
            for a in prov[lo:hi]:
                if nc[a["k"]] >= lim or a["k"] in cands:
                    continue
                if isrec or (bo is not None and a["off"] is not None and bo <= a["off"]) \
                        or (a["type"] == "open" and bo == 0):
                    cands[a["k"]] = a
        edges = []
        for a in cands.values():
            c = cost(a, b)
            if c is not None:
                edges.append((c, a["k"], 0))
        for a in twinkey.get((b["node"], b["type"], b["off"], b["len"]), ()):
            if a["k"] >= b["k"] or a["t"] > b["t"]:
                continue
            if a["sid"] is not None and b["sid"] is not None and a["sid"] != b["sid"]:
                continue
            g = b["t"] - a["t"]
            c = 0.4 + min(0.1 * g / G, 2.0)
            if a["sid"] is not None and b["sid"] is not None:
                c -= 1.0
            edges.append((c, a["k"], 1))
        edges.sort()
        full.append(edges[:40])
    return rows, full


def _make_adj(n, rows, full, extra, K=14):
    adjd = []
    for r, b in enumerate(rows):
        bk = b["k"]
        chain = []
        d = {}
        for (c, ak, tw) in full[r]:
            if tw:
                d[n + ak] = c + extra.get((ak, -bk - 1), 0.0)
            else:
                chain.append((c + extra.get((ak, bk), 0.0), ak))
        chain.sort()
        for c, ak in chain[:K]:
            d[ak] = c
        d[2 * n + r] = 60.0
        adjd.append(d)
    return adjd


# ------------------------------------------------------------ chain extraction
def _chains(evs, rows, row_col):
    n = len(evs)
    succ = {}
    twins = {}
    pred = {}
    for r, j in enumerate(row_col):
        b = rows[r]["k"]
        if j < 0 or j >= 2 * n:
            continue
        if j < n:
            succ[j] = b
            pred[b] = (j, 0)
        else:
            twins.setdefault(j - n, []).append(b)
            pred[b] = (j - n, 1)
    owner = {}
    chains = {}
    for e in evs:
        if e["type"] != "open":
            continue
        sid = e["sid"] if e["sid"] is not None else "open#%d" % e["i"]
        if sid in chains:
            sid = sid + "#%d" % e["i"]
        seq = []
        cur = e["k"]
        guard = 0
        while cur is not None and cur not in owner and guard <= n:
            guard += 1
            seq.append(cur)
            owner[cur] = sid
            nxt = succ.get(cur)
            alt = None
            stack = list(twins.get(cur, ()))
            while stack:
                b = stack.pop()
                if b in owner:
                    continue
                owner[b] = sid
                stack.extend(twins.get(b, ()))
                s2 = succ.get(b)
                if alt is None and s2 is not None and s2 not in owner:
                    alt = s2
            if nxt is None or nxt in owner:
                nxt = alt
            cur = nxt
        chains[sid] = seq
    return chains, owner, pred


# ------------------------------------------------------ solve + repair loop
def solve_paths(state, params):
    if state.get("_failed"):
        return state
    try:
        _solve_paths(state)
    except Exception:
        state["_failed"] = True
    return state


def _solve_paths(state):
    evs = state["_evs"]
    G = state["_G"]
    J = state["_J"]
    t0 = state.get("_t0", time.process_time())
    budget = 0.7
    n = len(evs)
    extra = {}
    best = None
    rounds = 0
    jpass = 0
    rows, full = _build_edges(evs, G, J)
    while True:
        tr = time.process_time()
        adjd = _make_adj(n, rows, full, extra)
        row_col = _lap(len(rows), adjd, 2 * n + len(rows))
        chains, owner, pred = _chains(evs, rows, row_col)
        nconf = 0
        newpen = []
        for sid, seq in chains.items():
            lastp = 0
            for p in range(1, len(seq)):
                e = evs[seq[p]]
                if e["sid"] is None:
                    continue
                if e["sid"] == sid:
                    lastp = p
                else:
                    nconf += 1
                    for q in range(lastp, p):
                        newpen.append((seq[q], seq[q + 1]))
                    break
        for b, (a, tw) in pred.items():
            if tw and evs[b]["sid"] is not None and owner.get(b) is not None \
                    and owner[b] != evs[b]["sid"]:
                nconf += 1
                newpen.append((a, -b - 1))
        unreached = [e["k"] for e in evs if e["type"] in SESSION_TYPES and e["k"] not in owner]
        for b in unreached:
            if b in pred:
                a, tw = pred[b]
                newpen.append((a, -b - 1) if tw else (a, b))
        score = nconf * 3 + len(unreached)
        if best is None or score < best[0]:
            best = (score, chains, owner)
        rounds += 1
        now = time.process_time()
        el = now - t0
        last_round = now - tr
        if jpass == 0:
            jpass = 1
            invs = []
            for seq in chains.values():
                for x, y in zip(seq, seq[1:]):
                    a, b = evs[x], evs[y]
                    if (a["type"] == "write" and b["off"] is not None and b["off"] == _end(a)
                            and a["node"] == b["node"] and a["t"] > b["t"]):
                        invs.append(a["t"] - b["t"])
            invs.sort()
            if len(invs) >= 2:
                J2 = invs[-2] * 1.3 + 0.5
                if len(invs) < 6:
                    J2 = max(J2, J)
                J2 = max(1.0, min(J2, 4 * G + 2))
                if abs(J2 - J) > 0.5 * max(1.0, J) and el * 3 < budget:
                    J = J2
                    best = None
                    extra = {}
                    rows, full = _build_edges(evs, G, J)
                    continue
        if score == 0 or not newpen or el + 1.5 * last_round > budget or rounds >= 15:
            break
        for key in newpen:
            extra[key] = extra.get(key, 0.0) + 2.5
    state["_J"] = J
    _, chains, owner = best
    state["_chains"] = {sid: list(seq) for sid, seq in chains.items()}
    state["_owner"] = {str(k): v for k, v in owner.items()}
    return state


# ------------------------------------------------------------------ output
def _fallback(state):
    inp = state.get("input") or {}
    raw = [e for e in (inp.get("events") or []) if isinstance(e, dict)]
    lastsid = {}
    first = None
    assignments = {}
    sessions = {}
    for e in raw:
        sid = e.get("sid")
        ty = e.get("type")
        if ty == "crash":
            continue
        nd = e.get("node")
        if sid is not None:
            sid = str(sid)
            lastsid[nd] = sid
            if first is None:
                first = sid
            if ty == "open" and sid not in sessions:
                sessions[sid] = {"status": "active", "durable": 0}
        else:
            s = lastsid.get(nd, first) or "s0"
            assignments[str(e.get("i"))] = s
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state


def finalize(state, params):
    try:
        if state.get("_failed") or "_chains" not in state:
            raise ValueError("no chains")
        _finalize(state)
    except Exception:
        _fallback(state)
    for key in ("_evs", "_chains", "_owner"):
        state.pop(key, None)
    return state


def _finalize(state):
    evs = state["_evs"]
    J = state["_J"]
    G = state["_G"]
    chains = state["_chains"]
    owner = {int(k): v for k, v in state["_owner"].items()}
    crash = {}
    for e in evs:
        if e["type"] == "crash":
            crash.setdefault(e["node"], []).append(e["t"])
    for v in crash.values():
        v.sort()
    open_sids = [s for s in chains.keys() if "#" not in s] or list(chains.keys())
    owned_by_node = {}
    owned_all = []
    for e in evs:
        if e["k"] in owner and e["type"] in NONTERM:
            owned_by_node.setdefault(e["node"], []).append(e)
            owned_all.append(e)
    assignments = {}
    for e in evs:
        if e["type"] == "crash" or e["sid"] is not None:
            continue
        s = owner.get(e["k"])
        if s is None:
            bestc = None
            for a in owned_by_node.get(e["node"]) or owned_all:
                c = abs(e["t"] - a["t"]) / G
                ea = _end(a)
                if e["off"] is not None and ea is not None and e["off"] != ea:
                    c += 2.0
                if bestc is None or c < bestc:
                    bestc = c
                    s = owner[a["k"]]
            if s is None:
                s = open_sids[0] if open_sids else "s0"
        assignments[str(e["i"])] = s
    sessions = {}
    for sid, seq in chains.items():
        if "#" in sid:
            continue
        dur = 0
        cur = 0
        status = "active"
        last = evs[seq[0]]
        for k in seq[1:]:
            e = evs[k]
            ty = e["type"]
            o = e["off"]
            if ty == "write":
                if o is not None:
                    if o < cur:
                        dur = o          # rollback via an unseen recover
                    cur = o
                cur = cur + (e["len"] or 0)
            elif ty == "checkpoint":
                if o is not None:
                    cur = o
                dur = cur
            elif ty == "commit":
                if o is not None:
                    cur = o
                dur = cur
                status = "committed"
            elif ty == "abort":
                status = "aborted"
            elif ty == "recover":
                if o is not None:
                    cur = o
                dur = cur
            last = e
        if status == "active":
            lst = crash.get(last["node"], [])
            thr = last["t"] if last["type"] == "recover" else last["t"] - 0.7 * J
            p = bisect.bisect_right(lst, thr)
            if p < len(lst):
                status = "down"
        sessions[sid] = {"status": status, "durable": int(dur)}
    for e in evs:
        if e["type"] == "open" and e["sid"] is not None and e["sid"] not in sessions:
            sessions[e["sid"]] = {"status": "active", "durable": 0}
    state["output"] = {"assignments": assignments, "sessions": sessions}
    return state

import time
import random
import bisect
import math
import statistics

V_COST = 5.0
MISS = 1.0
REORD = 0.3
DUP = 0.3
RANK = {"checkpoint": 0, "write": 1, "commit": 2}


def _toint(x):
    if x is None or isinstance(x, bool):
        return None
    try:
        return int(x)
    except Exception:
        try:
            return int(float(x))
        except Exception:
            return None


def solve(state, params):
    t_start = time.process_time()
    budget = 0.66
    inp = state.get("input") or {}
    raw = inp.get("events") or []
    recs = []
    for k, ev in enumerate(raw):
        if not isinstance(ev, dict):
            continue
        i = _toint(ev.get("i"))
        if i is None:
            i = k
        t = _toint(ev.get("t"))
        if t is None:
            t = 0
        sid = ev.get("sid")
        if sid is not None:
            sid = str(sid)
        recs.append((t, i, str(ev.get("node")), str(ev.get("type")), _toint(ev.get("off")),
                     _toint(ev.get("len")), sid))
    recs.sort(key=lambda z: (z[0], z[1]))
    n = len(recs)
    T = [r[0] for r in recs]
    IDX = [r[1] for r in recs]
    ND = [r[2] for r in recs]
    TY = [r[3] for r in recs]
    OFF = [r[4] if r[4] is not None else 0 for r in recs]
    LEN = [r[5] if r[5] is not None else 0 for r in recs]
    SIDR = [r[6] for r in recs]
    ENDOFF = [0] * n
    for k in range(n):
        if TY[k] == "write":
            ENDOFF[k] = OFF[k] + LEN[k]
        elif TY[k] in ("checkpoint", "commit", "recover"):
            ENDOFF[k] = OFF[k]
    SG = [(TY[k], ND[k], OFF[k], LEN[k]) for k in range(n)]

    # ---------------- sessions ----------------
    sids = []
    sidx = {}
    open_t = {}
    for k in range(n):
        if TY[k] == "open" and SIDR[k] is not None and SIDR[k] not in sidx:
            sidx[SIDR[k]] = len(sids)
            sids.append(SIDR[k])
            open_t[sidx[SIDR[k]]] = T[k]
    for k in range(n):
        if TY[k] != "crash" and SIDR[k] is not None and SIDR[k] not in sidx:
            sidx[SIDR[k]] = len(sids)
            sids.append(SIDR[k])
            open_t[sidx[SIDR[k]]] = T[k]
    ns = len(sids)
    anon = [k for k in range(n) if TY[k] != "crash" and SIDR[k] is None]
    if ns == 0:
        state["output"] = {"assignments": {}, "sessions": {}}
        return state

    crash_k = [k for k in range(n) if TY[k] == "crash"]
    CT = [T[k] for k in crash_k]
    CN = [ND[k] for k in crash_k]
    nc = len(crash_k)
    node_crash_t = {}
    for k in crash_k:
        node_crash_t.setdefault(ND[k], []).append(T[k])

    # ---------------- jitter window estimate ----------------
    gaps = [T[k + 1] - T[k] for k in range(n - 1)]
    mg = statistics.median(gaps) if gaps else 1
    W = max(3, int(3 * mg + 1))
    lab = {}
    for k in range(n):
        if SIDR[k] is not None and TY[k] in RANK:
            lab.setdefault(SIDR[k], []).append(k)
    maxinv = 0
    for s, ks in lab.items():
        for a in range(len(ks)):
            for b in range(a + 1, min(len(ks), a + 6)):
                ka = ks[a]
                kb = ks[b]
                if ND[ka] != ND[kb] or SG[ka] == SG[kb]:
                    continue
                if (OFF[kb], RANK[TY[kb]]) < (OFF[ka], RANK[TY[ka]]):
                    ct = node_crash_t.get(ND[ka], [])
                    j = bisect.bisect_left(ct, T[ka] - 2)
                    if j < len(ct) and ct[j] <= T[kb] + 2:
                        continue
                    if T[kb] - T[ka] <= 40:
                        maxinv = max(maxinv, T[kb] - T[ka])
    W = max(W, int(maxinv * 1.3) + 1)

    # ---------------- semantic simulator ----------------
    # S: [0 st, 1 node, 2 cur, 3 dur, 4 crash_t, 5 pre_node, 6 pre_cur, 7 pre_dur,
    #     8 pending_recover_k, 9 seen(set of signatures), 10 end_t]
    def new_state():
        return ["P", None, 0, 0, 0, None, 0, 0, -1, set(), 0]

    def do_crash(S, t, node):
        c = 0.0
        pk = S[8]
        if pk >= 0 and t - T[pk] > W:
            c += V_COST
            S[8] = -1
            pk = -1
        if S[0] == "A" and S[1] == node:
            S[0] = "D"
            S[4] = t
            S[5] = node
            S[6] = S[2]
            S[7] = S[3]
            S[2] = S[3]
            if pk >= 0:
                off = OFF[pk]
                if off > S[3]:
                    c += MISS
                    S[3] = off
                elif off < S[3]:
                    c += V_COST
                S[0] = "A"
                S[1] = ND[pk]
                S[2] = off
                S[8] = -1
                c += REORD
        return c

    def step(S, k):
        c = 0.0
        t = T[k]
        ty = TY[k]
        pk = S[8]
        if pk >= 0 and t - T[pk] > W:
            c += V_COST
            S[8] = -1
        sig = SG[k]
        seen = S[9]
        st = S[0]
        if ty == "open":
            if st == "P":
                S[0] = "A"
                S[1] = ND[k]
                seen.add(sig)
                return c
            return c + (DUP if sig in seen else V_COST)
        if st == "P":
            return c + V_COST
        if st == "C" or st == "X":
            if sig in seen:
                return c + DUP
            if t - S[10] <= W:
                return c + REORD
            return c + V_COST
        off = OFF[k]
        if st == "D":
            if ty == "recover":
                if off == S[3]:
                    pass
                elif off > S[3]:
                    c += MISS
                    S[3] = off
                else:
                    if sig in seen:
                        return c + DUP
                    c += V_COST
                    S[3] = off
                S[0] = "A"
                S[1] = ND[k]
                S[2] = off
                seen.add(sig)
                return c
            if t - S[4] <= W and ND[k] == S[5]:
                pc = S[6]
                if ty == "write" and off == pc:
                    S[6] = pc + LEN[k]
                    seen.add(sig)
                    return c + REORD
                if ty == "checkpoint" and off == pc:
                    S[7] = pc
                    S[3] = pc
                    S[2] = pc
                    seen.add(sig)
                    return c + REORD
                if ty == "commit" and off == pc:
                    S[0] = "C"
                    S[3] = pc
                    S[2] = pc
                    S[10] = t
                    seen.add(sig)
                    return c + REORD
                if ty == "abort":
                    S[0] = "X"
                    S[10] = t
                    seen.add(sig)
                    return c + REORD
            if sig in seen:
                return c + DUP
            c += MISS
            S[0] = "A"
            S[1] = ND[k]
            S[2] = S[3]
        if ty == "recover":
            if sig in seen:
                return c + DUP
            if S[8] < 0:
                S[8] = k
                seen.add(sig)
                return c
            return c + V_COST
        if ND[k] != S[1]:
            if sig in seen:
                return c + DUP
            c += V_COST
            S[1] = ND[k]
        cur = S[2]
        if ty == "write":
            if off == cur:
                S[2] = cur + LEN[k]
            elif off > cur:
                c += MISS
                S[2] = off + LEN[k]
            else:
                if sig in seen:
                    return c + DUP
                c += V_COST
                S[2] = off + LEN[k]
        elif ty == "checkpoint":
            if off == cur:
                S[3] = cur
            elif off > cur:
                c += MISS
                S[2] = off
                S[3] = off
            else:
                if sig in seen:
                    return c + DUP
                c += V_COST
        elif ty == "commit":
            if off > cur:
                c += MISS
            elif off < cur:
                if sig in seen:
                    return c + DUP
                c += V_COST
            S[0] = "C"
            S[2] = off
            S[3] = off
            S[10] = t
        elif ty == "abort":
            S[0] = "X"
            S[2] = S[3]
            S[10] = t
        else:
            c += V_COST
        seen.add(sig)
        return c

    def fix_order(seq):
        seq = list(seq)
        for a in range(1, len(seq)):
            j = a
            while j > 0:
                ka = seq[j - 1]
                kb = seq[j]
                tya = TY[ka]
                tyb = TY[kb]
                if tya not in RANK or tyb not in RANK:
                    break
                if ND[ka] != ND[kb] or T[kb] - T[ka] > W or SG[ka] == SG[kb]:
                    break
                if (OFF[kb], RANK[tyb]) >= (OFF[ka], RANK[tya]):
                    break
                ct = node_crash_t.get(ND[ka])
                if ct:
                    q = bisect.bisect_left(ct, T[ka])
                    if q < len(ct) and ct[q] <= T[kb]:
                        break
                seq[j - 1] = kb
                seq[j] = ka
                j -= 1
        return seq

    def simulate(seq, prev=None):
        F = fix_order(seq)
        p = 0
        if prev is not None:
            PF = prev[0]
            m = min(len(PF), len(F))
            while p < m and PF[p] == F[p]:
                p += 1
        if prev is not None and p > 0:
            snaps = prev[1][:p]
            AP = prev[2][:p]
            if p < len(prev[1]):
                sn = prev[1][p]
            else:
                sn = prev[3]
            S = list(sn[:9])
            S.append({SG[F[q]] for q in range(p) if AP[q]})
            S.append(sn[9])
            ci = sn[10]
            c = sn[11]
        else:
            p = 0
            snaps = []
            AP = []
            S = new_state()
            c = 0.0
            ci = 0
            if F:
                ci = bisect.bisect_left(CT, T[F[0]] - 1)
        seen = S[9]
        for j in range(p, len(F)):
            k = F[j]
            t = T[k]
            snaps.append((S[0], S[1], S[2], S[3], S[4], S[5], S[6], S[7], S[8], S[10], ci, c))
            while ci < nc and (CT[ci] < t or (CT[ci] == t and crash_k[ci] < k)):
                if S[0] == "A" or S[8] >= 0:
                    c += do_crash(S, CT[ci], CN[ci])
                ci += 1
            c += step(S, k)
            AP.append(SG[k] in seen)
        endsnap = (S[0], S[1], S[2], S[3], S[4], S[5], S[6], S[7], S[8], S[10], ci, c)
        while ci < nc:
            if S[0] == "A" or S[8] >= 0:
                c += do_crash(S, CT[ci], CN[ci])
            ci += 1
        if S[8] >= 0:
            c += V_COST
        return c, (F, snaps, AP, endsnap), S

    # ---------------- candidates ----------------
    cands = {}
    for k in anon:
        cl = [s for s in range(ns) if open_t[s] <= T[k]]
        if not cl:
            cl = list(range(ns))
        cands[k] = cl

    lab_by_s = [[] for _ in range(ns)]
    for k in range(n):
        if TY[k] != "crash" and SIDR[k] is not None:
            lab_by_s[sidx[SIDR[k]]].append(k)
    labT = [[T[k] for k in lst] for lst in lab_by_s]

    # ---------------- greedy initialisation ----------------
    def copy_state(S):
        X = list(S)
        X[9] = set(S[9])
        return X

    states = [new_state() for _ in range(ns)]
    last_act = [-1] * ns
    assign = {}
    for k in range(n):
        ty = TY[k]
        if ty == "crash":
            for s in range(ns):
                if states[s][0] == "A" or states[s][8] >= 0:
                    do_crash(states[s], T[k], ND[k])
            continue
        if SIDR[k] is not None:
            s = sidx[SIDR[k]]
            step(states[s], k)
            last_act[s] = k
            continue
        best = None
        bs = cands[k][0]
        for s in cands[k]:
            X = copy_state(states[s])
            c = step(X, k)
            lst = lab_by_s[s]
            q = bisect.bisect_right(labT[s], T[k])
            if q < len(lst) and TY[lst[q]] != "open":
                c += 0.5 * step(copy_state(X), lst[q])
            rec = last_act[s] if ND[k] == states[s][1] else -5
            key = (c, -rec, s)
            if best is None or key < best:
                best = key
                bs = s
        assign[k] = bs
        step(states[bs], k)
        last_act[bs] = k

    # ---------------- stochastic local search (annealing) ----------------
    sess_ev = [list(lab_by_s[s]) for s in range(ns)]
    for k in anon:
        bisect.insort(sess_ev[assign[k]], k)
    cache = []
    cost = []
    for s in range(ns):
        rr = simulate(sess_ev[s])
        cost.append(rr[0])
        cache.append(rr[1])
    total = sum(cost)
    best_total = total
    best_assign = dict(assign)
    rng = random.Random(1234567)
    na = len(anon)
    anon_pos = {k: p for p, k in enumerate(anon)}
    deadline = t_start + budget
    T0 = 1.5
    T1 = 0.05
    it = 0
    if na > 0 and ns > 1:
        sa_start = time.process_time()
        span = max(1e-6, deadline - sa_start)
        temp = T0
        while True:
            if (it & 15) == 0:
                now = time.process_time()
                if now >= deadline:
                    break
                frac = (now - sa_start) / span
                temp = T0 * (T1 / T0) ** frac
            it += 1
            r = rng.random()
            moves = []
            k = anon[rng.randrange(na)]
            a = assign[k]
            if r < 0.6:
                cl = cands[k]
                if len(cl) < 2:
                    continue
                if rng.random() < 0.75:
                    fit = []
                    nfit = []
                    nk = ND[k]
                    ok_ = OFF[k]
                    tyk = TY[k]
                    for s in cl:
                        if s == a:
                            continue
                        lst = sess_ev[s]
                        q = bisect.bisect_left(lst, k)
                        if q == 0:
                            continue
                        kp = lst[q - 1]
                        if ND[kp] == nk:
                            nfit.append(s)
                            if tyk in RANK and ENDOFF[kp] == ok_:
                                fit.append(s)
                        elif tyk == "recover" and (TY[kp] in RANK or TY[kp] == "recover"):
                            if ENDOFF[kp] >= ok_:
                                fit.append(s)
                    if fit and rng.random() < 0.7:
                        pool = fit
                    else:
                        pool = nfit or fit or cl
                    b = pool[rng.randrange(len(pool))]
                else:
                    b = cl[rng.randrange(len(cl))]
                if b == a:
                    continue
                moves.append((k, b))
            elif r < 0.85:
                p = anon_pos[k]
                lo = max(0, p - 15)
                hi = min(na - 1, p + 15)
                k2 = anon[rng.randint(lo, hi)]
                b = assign[k2]
                if b == a or b not in cands[k] or a not in cands[k2]:
                    continue
                moves.append((k, b))
                moves.append((k2, a))
            else:
                b = rng.randrange(ns)
                if b == a:
                    continue
                p = anon_pos[k]
                L = rng.randint(3, 40)
                for q in range(p, min(na, p + L)):
                    kk = anon[q]
                    sa = assign[kk]
                    if sa == a and b in cands[kk]:
                        moves.append((kk, b))
                    elif sa == b and a in cands[kk]:
                        moves.append((kk, a))
                if not moves:
                    continue
            touched = set()
            for kk, nb in moves:
                touched.add(assign[kk])
                touched.add(nb)
            newl = {}
            for s in touched:
                newl[s] = list(sess_ev[s])
            for kk, nb in moves:
                lst = newl[assign[kk]]
                del lst[bisect.bisect_left(lst, kk)]
                bisect.insort(newl[nb], kk)
            newc = {}
            newcache = {}
            delta = 0.0
            for s in touched:
                rr = simulate(newl[s], cache[s])
                newc[s] = rr[0]
                newcache[s] = rr[1]
                delta += rr[0] - cost[s]
            accept = delta <= 0
            if not accept:
                x = delta / temp
                if x < 50 and rng.random() < math.exp(-x):
                    accept = True
            if accept:
                for s in touched:
                    sess_ev[s] = newl[s]
                    cost[s] = newc[s]
                    cache[s] = newcache[s]
                for kk, nb in moves:
                    assign[kk] = nb
                total += delta
                if total < best_total - 1e-9:
                    best_total = total
                    best_assign = dict(assign)
        assign = best_assign
        sess_ev = [list(lab_by_s[s]) for s in range(ns)]
        for k in anon:
            bisect.insort(sess_ev[assign[k]], k)

    # ---------------- output ----------------
    out_sessions = {}
    stmap = {"C": "committed", "X": "aborted", "A": "active", "D": "down", "P": "active"}
    for s in range(ns):
        rr = simulate(sess_ev[s])
        S = rr[2]
        out_sessions[sids[s]] = {"status": stmap.get(S[0], "active"), "durable": int(S[3])}
    assignments = {}
    for k in anon:
        assignments[str(IDX[k])] = sids[assign[k]]
    state["output"] = {"assignments": assignments, "sessions": out_sessions}
    state["sa_iters"] = it
    return state

import time
import random
import bisect
import math
import statistics

V_COST = 5.0
MISS = 1.0
REORD = 0.3
DUP = 0.3
RANK = {"checkpoint": 0, "write": 1, "commit": 2}
SWITCH_MARGIN = 1.0

C_GAP = 3.0
C_JIT = 0.7
C_STALE = 8.0
C_DUP = 1.5
C_MISSREC = 3.5
C_LATE = 2.5
C_EARLYREC = 3.0
C_MISSCK = 3.0
C_COMMIT_BACK = 5.0
C_ABSURD = 25.0
TYPES = {"open": 0, "write": 1, "checkpoint": 2, "commit": 3, "abort": 4, "recover": 5, "crash": 6}


def _toint(x):
    if x is None or isinstance(x, bool):
        return None
    try:
        return int(x)
    except Exception:
        try:
            return int(float(x))
        except Exception:
            return None


def _addgap(gaps, a, b):
    g = gaps + ((a, b),)
    if len(g) > 3:
        g = g[-3:]
    return g


def _fill(gaps, a, b):
    for k, (g0, g1) in enumerate(gaps):
        if g0 <= a and b <= g1 and b > a:
            pieces = []
            if a > g0:
                pieces.append((g0, a))
            if b < g1:
                pieces.append((b, g1))
            ng = gaps[:k] + tuple(pieces) + gaps[k + 1:]
            return ng, C_GAP * (1 - len(pieces))
    return None


def _trans(S, typ, nd, off, ln):
    st, sn, so, du, gp, ax = S
    out = []
    if typ == 0:
        if st == 0:
            out.append((0.0, (1, nd, 0, 0, (), -1)))
        return out
    if st == 0:
        return out
    if off is None and typ in (1, 2, 3, 5):
        off = so
    if typ == 1:
        if ln is None:
            ln = 0
        if st == 1 or st == 5:
            if sn == nd:
                if off == so:
                    out.append((0.0, (st, sn, off + ln, du, gp, ax)))
                elif off > so:
                    out.append((C_GAP, (st, sn, off + ln, du, _addgap(gp, so, off), ax)))
                else:
                    f = _fill(gp, off, off + ln)
                    if f is not None:
                        out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
                    else:
                        out.append((C_STALE, S))
        elif st == 2:
            if off >= du:
                if off == du:
                    out.append((C_MISSREC, (1, nd, off + ln, du, gp, -1)))
                else:
                    out.append((C_MISSREC + C_GAP, (1, nd, off + ln, du, _addgap(gp, du, off), -1)))
                if sn == nd:
                    out.append((C_LATE, S))
            else:
                f = _fill(gp, off, off + ln)
                if f is not None:
                    out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
        else:
            f = _fill(gp, off, off + ln)
            if f is not None:
                out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
        return out
    if typ == 2 or typ == 3:
        if st == 1 or st == 5:
            if sn == nd:
                nst = 3 if typ == 3 else st
                if off == so:
                    out.append((0.0, (nst, sn, off, off, gp, ax)))
                elif off > so:
                    out.append((C_GAP, (nst, sn, off, off, _addgap(gp, so, off), ax)))
                elif off >= du:
                    if typ == 2:
                        out.append((C_JIT, (st, sn, so, off, gp, ax)))
                    else:
                        out.append((C_COMMIT_BACK, (3, sn, off, off, gp, ax)))
                else:
                    out.append((C_STALE, S))
        elif st == 2:
            if off >= du:
                nst = 3 if typ == 3 else 1
                c = C_MISSREC + (C_GAP if off > du else 0.0)
                out.append((c, (nst, nd, off, off, gp, -1)))
                if sn == nd and typ == 2:
                    out.append((C_LATE, (2, sn, off, off, gp, ax)))
        return out
    if typ == 4:
        if st == 1 or st == 5:
            if sn == nd:
                out.append((0.0, (4, sn, so, du, gp, ax)))
        elif st == 2:
            out.append((C_MISSREC * 0.6, (4, sn, so, du, gp, ax)))
        return out
    if typ == 5:
        if st == 2:
            if off == du:
                out.append((0.0, (1, nd, off, off, gp, -1)))
            elif off > du:
                out.append((C_MISSCK, (1, nd, off, off, gp, -1)))
            else:
                out.append((C_STALE, (1, nd, du, du, gp, -1)))
        elif st == 1:
            if du <= off <= so:
                out.append((C_EARLYREC + (0.0 if off == du else C_MISSCK * 0.5),
                            (5, nd, off, off, gp, sn)))
        return out
    return out


def _crash(S, nd):
    st = S[0]
    if st == 1:
        if S[1] == nd:
            du = S[3]
            return (2, nd, du, du, tuple(g for g in S[4] if g[1] <= du), -1)
        return S
    if st == 5:
        if S[5] == nd:
            return (1, S[1], S[2], S[3], S[4], -1)
        if S[1] == nd:
            du = S[3]
            return (2, nd, du, du, tuple(g for g in S[4] if g[1] <= du), -1)
    return S


def _beam(inp, t_start, budget):
    raw = inp.get("events") or []
    nodes = list(inp.get("nodes") or [])
    evs = []
    for pos, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        i = _toint(e.get("i"))
        if i is None:
            i = pos
        t = _toint(e.get("t"))
        evs.append((t if t is not None else 0, i, e, i))
    evs.sort(key=lambda x: (x[0], x[1]))
    node_idx = {}
    for nn in nodes:
        nn = str(nn)
        if nn not in node_idx:
            node_idx[nn] = len(node_idx)
    sids = []
    sid_idx = {}
    for _, _, e, _ in evs:
        s = e.get("sid")
        if s is not None and e.get("type") != "crash":
            s = str(s)
            if s not in sid_idx:
                sid_idx[s] = len(sids)
                sids.append(s)
    E = []
    for t, pos, e, i in evs:
        typ = TYPES.get(e.get("type"), -1)
        if typ < 0:
            continue
        nn = str(e.get("node"))
        if nn not in node_idx:
            node_idx[nn] = len(node_idx)
        s = e.get("sid")
        si = -1
        if s is not None and typ != 6:
            si = sid_idx[str(s)]
        E.append((typ, node_idx[nn], _toint(e.get("off")), _toint(e.get("len")), si, i, t))
    nS = len(sids)
    nE = len(E)
    dupc = {}
    origset = set()
    seen = {}
    for k, (typ, nd, off, ln, si, i, t) in enumerate(E):
        if typ == 0 or typ == 6:
            continue
        key = (typ, nd, off, ln)
        lst = seen.get(key)
        if lst:
            dupc[k] = lst[-4:]
            for j in lst[-4:]:
                origset.add(j)
        seen.setdefault(key, []).append(k)
    init = tuple((0, -1, 0, 0, (), -1) for _ in range(nS))
    beam = [(0.0, init, None, {})]
    K = 24
    KMAX = 40
    KMIN = 3
    BR = 6
    DELTA = 12.0
    b0 = time.process_time()
    for k in range(nE):
        typ, nd, off, ln, si, i, t = E[k]
        if k % 8 == 0 and k > 0:
            el = time.process_time() - b0
            proj = el * nE / k
            if proj > budget:
                K = max(KMIN, int(K * 0.7))
            elif proj < budget * 0.5 and K < KMAX:
                K = min(KMAX, K + 4)
            if el > budget * 1.15:
                K = 1
        if typ == 6:
            cm = {}
            merged = {}
            for h in beam:
                ns = []
                for S in h[1]:
                    r = cm.get(id(S))
                    if r is None:
                        r = _crash(S, nd)
                        cm[id(S)] = r
                    ns.append(r)
                ns = tuple(ns)
                o = merged.get(ns)
                if o is None or h[0] < o[0]:
                    merged[ns] = (h[0], ns, h[2], h[3])
            beam = sorted(merged.values(), key=lambda x: x[0])[:max(1, K)]
            continue
        if nS == 0:
            continue
        memo = {}
        cands = [si] if si >= 0 else range(nS)
        dl = dupc.get(k)
        isorig = k in origset
        newc = []
        for hidx, h in enumerate(beam):
            hc, sess, asg, om = h
            opts = []
            for s in cands:
                S = sess[s]
                r = memo.get(id(S))
                if r is None:
                    r = _trans(S, typ, nd, off, ln)
                    memo[id(S)] = r
                for c, NS in r:
                    opts.append((c, s, NS))
            if dl:
                ds = set()
                for j in dl:
                    s = om.get(j)
                    if s is not None and (si < 0 or s == si) and s not in ds:
                        ds.add(s)
                        opts.append((C_DUP, s, None))
            if not opts:
                if si >= 0:
                    fs = si
                else:
                    fs = 0
                    bd = None
                    for s in range(nS):
                        S = sess[s]
                        if S[0] != 0 and S[1] == nd:
                            d = abs(S[2] - (off if off is not None else S[2]))
                            if bd is None or d < bd:
                                bd = d
                                fs = s
                opts.append((C_ABSURD, fs, None))
            opts.sort(key=lambda x: (x[0], x[1]))
            best = opts[0][0]
            for c, s, NS in opts[:BR]:
                if c > best + DELTA:
                    break
                newc.append((hc + c, hidx, s, NS))
        if not newc:
            continue
        newc.sort(key=lambda x: (x[0], x[1], x[2]))
        merged = set()
        out = []
        for c, hidx, s, NS in newc:
            h = beam[hidx]
            sess = h[1]
            if NS is not None and NS != sess[s]:
                l = list(sess)
                l[s] = NS
                ns = tuple(l)
            else:
                ns = sess
            if ns in merged:
                continue
            om = h[3]
            if isorig:
                om = dict(om)
                om[k] = s
            merged.add(ns)
            out.append((c, ns, (k, s, h[2]), om))
            if len(out) >= max(1, K):
                break
        beam = out
    best = beam[0] if beam else (0.0, init, None, {})
    assign = {}
    node = best[2]
    while node is not None:
        k, s, node = node
        assign[k] = s
    assignments = {}
    if nS > 0:
        for k, (typ, nd, off, ln, si, i, t) in enumerate(E):
            if typ == 6 or si >= 0:
                continue
            s = assign.get(k)
            if s is not None:
                assignments[str(i)] = sids[s]
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted", 5: "active"}
    sessions = {}
    for s in range(nS):
        S = best[1][s]
        du = S[2] if S[0] == 3 else S[3]
        sessions[sids[s]] = {"status": names.get(S[0], "active"), "durable": int(du)}
    return assignments, sessions


def solve(state, params):
    t_start = time.process_time()
    inp = state.get("input") or {}
    if not isinstance(inp, dict):
        inp = {}
    raw = inp.get("events") or []
    recs = []
    for k, ev in enumerate(raw):
        if not isinstance(ev, dict):
            continue
        i = _toint(ev.get("i"))
        if i is None:
            i = k
        t = _toint(ev.get("t"))
        if t is None:
            t = 0
        sid = ev.get("sid")
        if sid is not None:
            sid = str(sid)
        recs.append((t, i, str(ev.get("node")), str(ev.get("type")), _toint(ev.get("off")),
                     _toint(ev.get("len")), sid))
    recs.sort(key=lambda z: (z[0], z[1]))
    n = len(recs)
    T = [r[0] for r in recs]
    IDX = [r[1] for r in recs]
    ND = [r[2] for r in recs]
    TY = [r[3] for r in recs]
    OFF = [r[4] if r[4] is not None else 0 for r in recs]
    LEN = [r[5] if r[5] is not None else 0 for r in recs]
    SIDR = [r[6] if r[3] != "crash" else None for r in recs]
    ENDOFF = [0] * n
    for k in range(n):
        if TY[k] == "write":
            ENDOFF[k] = OFF[k] + LEN[k]
        elif TY[k] in ("checkpoint", "commit", "recover"):
            ENDOFF[k] = OFF[k]
    SG = [(TY[k], ND[k], OFF[k], LEN[k]) for k in range(n)]

    sids = []
    sidx = {}
    open_t = {}
    for k in range(n):
        if TY[k] == "open" and SIDR[k] is not None and SIDR[k] not in sidx:
            sidx[SIDR[k]] = len(sids)
            sids.append(SIDR[k])
            open_t[sidx[SIDR[k]]] = T[k]
    for k in range(n):
        if TY[k] != "crash" and SIDR[k] is not None and SIDR[k] not in sidx:
            sidx[SIDR[k]] = len(sids)
            sids.append(SIDR[k])
            open_t[sidx[SIDR[k]]] = T[k]
    ns = len(sids)
    anon = [k for k in range(n) if TY[k] != "crash" and SIDR[k] is None]
    if ns == 0:
        state["output"] = {"assignments": {}, "sessions": {}}
        return state

    # ---------------- phase 1: beam tracking (Y) ----------------
    try:
        beam_asg, beam_sess = _beam(inp, t_start, 0.30)
    except Exception:
        beam_asg, beam_sess = {}, {}

    crash_k = [k for k in range(n) if TY[k] == "crash"]
    CT = [T[k] for k in crash_k]
    CN = [ND[k] for k in crash_k]
    nc = len(crash_k)
    node_crash_t = {}
    for k in crash_k:
        node_crash_t.setdefault(ND[k], []).append(T[k])

    gaps = [T[k + 1] - T[k] for k in range(n - 1)]
    mg = statistics.median(gaps) if gaps else 1
    W = max(3, int(3 * mg + 1))
    lab = {}
    for k in range(n):
        if SIDR[k] is not None and TY[k] in RANK:
            lab.setdefault(SIDR[k], []).append(k)
    maxinv = 0
    for s, ks in lab.items():
        for a in range(len(ks)):
            for b in range(a + 1, min(len(ks), a + 6)):
                ka = ks[a]
                kb = ks[b]
                if ND[ka] != ND[kb] or SG[ka] == SG[kb]:
                    continue
                if (OFF[kb], RANK[TY[kb]]) < (OFF[ka], RANK[TY[ka]]):
                    ct = node_crash_t.get(ND[ka], [])
                    j = bisect.bisect_left(ct, T[ka] - 2)
                    if j < len(ct) and ct[j] <= T[kb] + 2:
                        continue
                    if T[kb] - T[ka] <= 40:
                        maxinv = max(maxinv, T[kb] - T[ka])
    W = max(W, int(maxinv * 1.3) + 1)

    def new_state():
        return ["P", None, 0, 0, 0, None, 0, 0, -1, set(), 0]

    def do_crash(S, t, node):
        c = 0.0
        pk = S[8]
        if pk >= 0 and t - T[pk] > W:
            c += V_COST
            S[8] = -1
            pk = -1
        if S[0] == "A" and S[1] == node:
            S[0] = "D"
            S[4] = t
            S[5] = node
            S[6] = S[2]
            S[7] = S[3]
            S[2] = S[3]
            if pk >= 0:
                off = OFF[pk]
                if off > S[3]:
                    c += MISS
                    S[3] = off
                elif off < S[3]:
                    c += V_COST
                S[0] = "A"
                S[1] = ND[pk]
                S[2] = off
                S[8] = -1
                c += REORD
        return c

    def step(S, k):
        c = 0.0
        t = T[k]
        ty = TY[k]
        pk = S[8]
        if pk >= 0 and t - T[pk] > W:
            c += V_COST
            S[8] = -1
        sig = SG[k]
        seen = S[9]
        st = S[0]
        if ty == "open":
            if st == "P":
                S[0] = "A"
                S[1] = ND[k]
                seen.add(sig)
                return c
            return c + (DUP if sig in seen else V_COST)
        if st == "P":
            return c + V_COST
        if st == "C" or st == "X":
            if sig in seen:
                return c + DUP
            if t - S[10] <= W:
                return c + REORD
            return c + V_COST
        off = OFF[k]
        if st == "D":
            if ty == "recover":
                if off == S[3]:
                    pass
                elif off > S[3]:
                    c += MISS
                    S[3] = off
                else:
                    if sig in seen:
                        return c + DUP
                    c += V_COST
                    S[3] = off
                S[0] = "A"
                S[1] = ND[k]
                S[2] = off
                seen.add(sig)
                return c
            if t - S[4] <= W and ND[k] == S[5]:
                pc = S[6]
                if ty == "write" and off == pc:
                    S[6] = pc + LEN[k]
                    seen.add(sig)
                    return c + REORD
                if ty == "checkpoint" and off == pc:
                    S[7] = pc
                    S[3] = pc
                    S[2] = pc
                    seen.add(sig)
                    return c + REORD
                if ty == "commit" and off == pc:
                    S[0] = "C"
                    S[3] = pc
                    S[2] = pc
                    S[10] = t
                    seen.add(sig)
                    return c + REORD
                if ty == "abort":
                    S[0] = "X"
                    S[10] = t
                    seen.add(sig)
                    return c + REORD
            if sig in seen:
                return c + DUP
            c += MISS
            S[0] = "A"
            S[1] = ND[k]
            S[2] = S[3]
        if ty == "recover":
            if sig in seen:
                return c + DUP
            if S[8] < 0:
                S[8] = k
                seen.add(sig)
                return c
            return c + V_COST
        if ND[k] != S[1]:
            if sig in seen:
                return c + DUP
            c += V_COST
            S[1] = ND[k]
        cur = S[2]
        if ty == "write":
            if off == cur:
                S[2] = cur + LEN[k]
            elif off > cur:
                c += MISS
                S[2] = off + LEN[k]
            else:
                if sig in seen:
                    return c + DUP
                c += V_COST
                S[2] = off + LEN[k]
        elif ty == "checkpoint":
            if off == cur:
                S[3] = cur
            elif off > cur:
                c += MISS
                S[2] = off
                S[3] = off
            else:
                if sig in seen:
                    return c + DUP
                c += V_COST
        elif ty == "commit":
            if off > cur:
                c += MISS
            elif off < cur:
                if sig in seen:
                    return c + DUP
                c += V_COST
            S[0] = "C"
            S[2] = off
            S[3] = off
            S[10] = t
        elif ty == "abort":
            S[0] = "X"
            S[2] = S[3]
            S[10] = t
        else:
            c += V_COST
        seen.add(sig)
        return c

    def fix_order(seq):
        seq = list(seq)
        for a in range(1, len(seq)):
            j = a
            while j > 0:
                ka = seq[j - 1]
                kb = seq[j]
                tya = TY[ka]
                tyb = TY[kb]
                if tya not in RANK or tyb not in RANK:
                    break
                if ND[ka] != ND[kb] or T[kb] - T[ka] > W or SG[ka] == SG[kb]:
                    break
                if (OFF[kb], RANK[tyb]) >= (OFF[ka], RANK[tya]):
                    break
                ct = node_crash_t.get(ND[ka])
                if ct:
                    q = bisect.bisect_left(ct, T[ka])
                    if q < len(ct) and ct[q] <= T[kb]:
                        break
                seq[j - 1] = kb
                seq[j] = ka
                j -= 1
        return seq

    def simulate(seq, prev=None):
        F = fix_order(seq)
        p = 0
        if prev is not None:
            PF = prev[0]
            m = min(len(PF), len(F))
            while p < m and PF[p] == F[p]:
                p += 1
        if prev is not None and p > 0:
            snaps = prev[1][:p]
            AP = prev[2][:p]
            if p < len(prev[1]):
                sn = prev[1][p]
            else:
                sn = prev[3]
            S = list(sn[:9])
            S.append({SG[F[q]] for q in range(p) if AP[q]})
            S.append(sn[9])
            ci = sn[10]
            c = sn[11]
        else:
            p = 0
            snaps = []
            AP = []
            S = new_state()
            c = 0.0
            ci = 0
            if F:
                ci = bisect.bisect_left(CT, T[F[0]] - 1)
        seen = S[9]
        for j in range(p, len(F)):
            k = F[j]
            t = T[k]
            snaps.append((S[0], S[1], S[2], S[3], S[4], S[5], S[6], S[7], S[8], S[10], ci, c))
            while ci < nc and (CT[ci] < t or (CT[ci] == t and crash_k[ci] < k)):
                if S[0] == "A" or S[8] >= 0:
                    c += do_crash(S, CT[ci], CN[ci])
                ci += 1
            c += step(S, k)
            AP.append(SG[k] in seen)
        endsnap = (S[0], S[1], S[2], S[3], S[4], S[5], S[6], S[7], S[8], S[10], ci, c)
        while ci < nc:
            if S[0] == "A" or S[8] >= 0:
                c += do_crash(S, CT[ci], CN[ci])
            ci += 1
        if S[8] >= 0:
            c += V_COST
        return c, (F, snaps, AP, endsnap), S

    cands = {}
    for k in anon:
        cl = [s for s in range(ns) if open_t[s] <= T[k]]
        if not cl:
            cl = list(range(ns))
        cands[k] = cl

    lab_by_s = [[] for _ in range(ns)]
    for k in range(n):
        if TY[k] != "crash" and SIDR[k] is not None:
            lab_by_s[sidx[SIDR[k]]].append(k)
    labT = [[T[k] for k in lst] for lst in lab_by_s]

    # ---------------- greedy fallback (only for events the beam did not assign) ----------------
    assign = {}
    missing = [k for k in anon if beam_asg.get(str(IDX[k])) not in sidx]
    if missing:
        def copy_state(S):
            X = list(S)
            X[9] = set(S[9])
            return X
        states = [new_state() for _ in range(ns)]
        last_act = [-1] * ns
        for k in range(n):
            ty = TY[k]
            if ty == "crash":
                for s in range(ns):
                    if states[s][0] == "A" or states[s][8] >= 0:
                        do_crash(states[s], T[k], ND[k])
                continue
            if SIDR[k] is not None:
                s = sidx[SIDR[k]]
                step(states[s], k)
                last_act[s] = k
                continue
            bsid = beam_asg.get(str(IDX[k]))
            if bsid in sidx:
                bs = sidx[bsid]
            else:
                best = None
                bs = cands[k][0]
                for s in cands[k]:
                    X = copy_state(states[s])
                    c = step(X, k)
                    lst = lab_by_s[s]
                    q = bisect.bisect_right(labT[s], T[k])
                    if q < len(lst) and TY[lst[q]] != "open":
                        c += 0.5 * step(copy_state(X), lst[q])
                    rec = last_act[s] if ND[k] == states[s][1] else -5
                    key = (c, -rec, s)
                    if best is None or key < best:
                        best = key
                        bs = s
            assign[k] = bs
            step(states[bs], k)
            last_act[bs] = k
    else:
        for k in anon:
            assign[k] = sidx[beam_asg[str(IDX[k])]]
    seed_assign = dict(assign)

    # ---------------- phase 2: annealing seeded by the beam (X) ----------------
    sess_ev = [list(lab_by_s[s]) for s in range(ns)]
    for k in anon:
        bisect.insort(sess_ev[assign[k]], k)
    cache = []
    cost = []
    for s in range(ns):
        rr = simulate(sess_ev[s])
        cost.append(rr[0])
        cache.append(rr[1])
    total = sum(cost)
    seed_total = total
    best_total = total
    best_assign = dict(assign)
    rng = random.Random(1234567)
    na = len(anon)
    anon_pos = {k: p for p, k in enumerate(anon)}
    deadline = t_start + 0.75
    T0 = 1.0
    T1 = 0.05
    it = 0
    if na > 0 and ns > 1:
        sa_start = time.process_time()
        span = max(1e-6, deadline - sa_start)
        temp = T0
        while True:
            if (it & 15) == 0:
                now = time.process_time()
                if now >= deadline:
                    break
                frac = (now - sa_start) / span
                temp = T0 * (T1 / T0) ** frac
            it += 1
            r = rng.random()
            moves = []
            k = anon[rng.randrange(na)]
            a = assign[k]
            if r < 0.6:
                cl = cands[k]
                if len(cl) < 2:
                    continue
                if rng.random() < 0.75:
                    fit = []
                    nfit = []
                    nk = ND[k]
                    ok_ = OFF[k]
                    tyk = TY[k]
                    for s in cl:
                        if s == a:
                            continue
                        lst = sess_ev[s]
                        q = bisect.bisect_left(lst, k)
                        if q == 0:
                            continue
                        kp = lst[q - 1]
                        if ND[kp] == nk:
                            nfit.append(s)
                            if tyk in RANK and ENDOFF[kp] == ok_:
                                fit.append(s)
                        elif tyk == "recover" and (TY[kp] in RANK or TY[kp] == "recover"):
                            if ENDOFF[kp] >= ok_:
                                fit.append(s)
                    if fit and rng.random() < 0.7:
                        pool = fit
                    else:
                        pool = nfit or fit or cl
                    b = pool[rng.randrange(len(pool))]
                else:
                    b = cl[rng.randrange(len(cl))]
                if b == a:
                    continue
                moves.append((k, b))
            elif r < 0.85:
                p = anon_pos[k]
                lo = max(0, p - 15)
                hi = min(na - 1, p + 15)
                k2 = anon[rng.randint(lo, hi)]
                b = assign[k2]
                if b == a or b not in cands[k] or a not in cands[k2]:
                    continue
                moves.append((k, b))
                moves.append((k2, a))
            else:
                b = rng.randrange(ns)
                if b == a:
                    continue
                p = anon_pos[k]
                L = rng.randint(3, 40)
                for q in range(p, min(na, p + L)):
                    kk = anon[q]
                    sa = assign[kk]
                    if sa == a and b in cands[kk]:
                        moves.append((kk, b))
                    elif sa == b and a in cands[kk]:
                        moves.append((kk, a))
                if not moves:
                    continue
            touched = set()
            for kk, nb in moves:
                touched.add(assign[kk])
                touched.add(nb)
            newl = {}
            for s in touched:
                newl[s] = list(sess_ev[s])
            for kk, nb in moves:
                lst = newl[assign[kk]]
                del lst[bisect.bisect_left(lst, kk)]
                bisect.insort(newl[nb], kk)
            newc = {}
            newcache = {}
            delta = 0.0
            for s in touched:
                rr = simulate(newl[s], cache[s])
                newc[s] = rr[0]
                newcache[s] = rr[1]
                delta += rr[0] - cost[s]
            accept = delta <= 0
            if not accept:
                x = delta / temp
                if x < 50 and rng.random() < math.exp(-x):
                    accept = True
            if accept:
                for s in touched:
                    sess_ev[s] = newl[s]
                    cost[s] = newc[s]
                    cache[s] = newcache[s]
                for kk, nb in moves:
                    assign[kk] = nb
                total += delta
                if total < best_total - 1e-9:
                    best_total = total
                    best_assign = dict(assign)

    stmap = {"C": "committed", "X": "aborted", "A": "active", "D": "down", "P": "active"}
    use_sa = best_total < seed_total - SWITCH_MARGIN
    final = best_assign if use_sa else seed_assign
    sess_ev = [list(lab_by_s[s]) for s in range(ns)]
    for k in anon:
        bisect.insort(sess_ev[final[k]], k)
    out_sessions = {}
    for s in range(ns):
        sid = sids[s]
        if (not use_sa) and sid in beam_sess and not missing:
            out_sessions[sid] = beam_sess[sid]
        else:
            S = simulate(sess_ev[s])[2]
            out_sessions[sid] = {"status": stmap.get(S[0], "active"), "durable": int(S[3])}
    assignments = {}
    for k in anon:
        assignments[str(IDX[k])] = sids[final[k]]
    state["output"] = {"assignments": assignments, "sessions": out_sessions}
    state["used_sa"] = bool(use_sa)
    state["sa_iters"] = it
    return state

import time
import random
import bisect
import math
import statistics

V_COST = 5.0
MISS = 1.0
REORD = 0.3
DUP = 0.3
RANK = {"checkpoint": 0, "write": 1, "commit": 2}

C_GAP = 3.0
C_JIT = 0.7
C_STALE = 8.0
C_DUP = 1.5
C_MISSREC = 3.5
C_LATE = 2.5
C_EARLYREC = 3.0
C_MISSCK = 3.0
C_COMMIT_BACK = 5.0
C_ABSURD = 25.0
TYPES = {"open": 0, "write": 1, "checkpoint": 2, "commit": 3, "abort": 4, "recover": 5, "crash": 6}


def _toint(x):
    if x is None or isinstance(x, bool):
        return None
    try:
        return int(x)
    except Exception:
        try:
            return int(float(x))
        except Exception:
            return None


def _addgap(gaps, a, b):
    g = gaps + ((a, b),)
    if len(g) > 3:
        g = g[-3:]
    return g


def _fill(gaps, a, b):
    for k, (g0, g1) in enumerate(gaps):
        if g0 <= a and b <= g1 and b > a:
            pieces = []
            if a > g0:
                pieces.append((g0, a))
            if b < g1:
                pieces.append((b, g1))
            ng = gaps[:k] + tuple(pieces) + gaps[k + 1:]
            return ng, C_GAP * (1 - len(pieces))
    return None


def _trans(S, typ, nd, off, ln):
    st, sn, so, du, gp, ax = S
    out = []
    if typ == 0:
        if st == 0:
            out.append((0.0, (1, nd, 0, 0, (), -1)))
        return out
    if st == 0:
        return out
    if off is None and typ in (1, 2, 3, 5):
        off = so
    if typ == 1:
        if ln is None:
            ln = 0
        if st == 1 or st == 5:
            if sn == nd:
                if off == so:
                    out.append((0.0, (st, sn, off + ln, du, gp, ax)))
                elif off > so:
                    out.append((C_GAP, (st, sn, off + ln, du, _addgap(gp, so, off), ax)))
                else:
                    f = _fill(gp, off, off + ln)
                    if f is not None:
                        out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
                    else:
                        out.append((C_STALE, S))
        elif st == 2:
            if off >= du:
                if off == du:
                    out.append((C_MISSREC, (1, nd, off + ln, du, gp, -1)))
                else:
                    out.append((C_MISSREC + C_GAP, (1, nd, off + ln, du, _addgap(gp, du, off), -1)))
                if sn == nd:
                    out.append((C_LATE, S))
            else:
                f = _fill(gp, off, off + ln)
                if f is not None:
                    out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
        else:
            f = _fill(gp, off, off + ln)
            if f is not None:
                out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
        return out
    if typ == 2 or typ == 3:
        if st == 1 or st == 5:
            if sn == nd:
                nst = 3 if typ == 3 else st
                if off == so:
                    out.append((0.0, (nst, sn, off, off, gp, ax)))
                elif off > so:
                    out.append((C_GAP, (nst, sn, off, off, _addgap(gp, so, off), ax)))
                elif off >= du:
                    if typ == 2:
                        out.append((C_JIT, (st, sn, so, off, gp, ax)))
                    else:
                        out.append((C_COMMIT_BACK, (3, sn, off, off, gp, ax)))
                else:
                    out.append((C_STALE, S))
        elif st == 2:
            if off >= du:
                nst = 3 if typ == 3 else 1
                c = C_MISSREC + (C_GAP if off > du else 0.0)
                out.append((c, (nst, nd, off, off, gp, -1)))
                if sn == nd and typ == 2:
                    out.append((C_LATE, (2, sn, off, off, gp, ax)))
        return out
    if typ == 4:
        if st == 1 or st == 5:
            if sn == nd:
                out.append((0.0, (4, sn, so, du, gp, ax)))
        elif st == 2:
            out.append((C_MISSREC * 0.6, (4, sn, so, du, gp, ax)))
        return out
    if typ == 5:
        if st == 2:
            if off == du:
                out.append((0.0, (1, nd, off, off, gp, -1)))
            elif off > du:
                out.append((C_MISSCK, (1, nd, off, off, gp, -1)))
            else:
                out.append((C_STALE, (1, nd, du, du, gp, -1)))
        elif st == 1:
            if du <= off <= so:
                out.append((C_EARLYREC + (0.0 if off == du else C_MISSCK * 0.5),
                            (5, nd, off, off, gp, sn)))
        return out
    return out


def _crash(S, nd):
    st = S[0]
    if st == 1:
        if S[1] == nd:
            du = S[3]
            return (2, nd, du, du, tuple(g for g in S[4] if g[1] <= du), -1)
        return S
    if st == 5:
        if S[5] == nd:
            return (1, S[1], S[2], S[3], S[4], -1)
        if S[1] == nd:
            du = S[3]
            return (2, nd, du, du, tuple(g for g in S[4] if g[1] <= du), -1)
    return S


def _beam(inp, t_start, budget):
    raw = inp.get("events") or []
    nodes = list(inp.get("nodes") or [])
    evs = []
    for pos, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        i = _toint(e.get("i"))
        if i is None:
            i = pos
        t = _toint(e.get("t"))
        evs.append((t if t is not None else 0, i, e, i))
    evs.sort(key=lambda x: (x[0], x[1]))
    node_idx = {}
    for nn in nodes:
        nn = str(nn)
        if nn not in node_idx:
            node_idx[nn] = len(node_idx)
    sids = []
    sid_idx = {}
    for _, _, e, _ in evs:
        s = e.get("sid")
        if s is not None and e.get("type") != "crash":
            s = str(s)
            if s not in sid_idx:
                sid_idx[s] = len(sids)
                sids.append(s)
    E = []
    for t, pos, e, i in evs:
        typ = TYPES.get(e.get("type"), -1)
        if typ < 0:
            continue
        nn = str(e.get("node"))
        if nn not in node_idx:
            node_idx[nn] = len(node_idx)
        s = e.get("sid")
        si = -1
        if s is not None and typ != 6:
            si = sid_idx[str(s)]
        E.append((typ, node_idx[nn], _toint(e.get("off")), _toint(e.get("len")), si, i, t))
    nS = len(sids)
    nE = len(E)
    dupc = {}
    origset = set()
    seen = {}
    for k, (typ, nd, off, ln, si, i, t) in enumerate(E):
        if typ == 0 or typ == 6:
            continue
        key = (typ, nd, off, ln)
        lst = seen.get(key)
        if lst:
            dupc[k] = lst[-4:]
            for j in lst[-4:]:
                origset.add(j)
        seen.setdefault(key, []).append(k)
    init = tuple((0, -1, 0, 0, (), -1) for _ in range(nS))
    beam = [(0.0, init, None, {})]
    K = 32
    KMAX = 64
    KMIN = 3
    BR = 8
    DELTA = 12.0
    b0 = time.process_time()
    for k in range(nE):
        typ, nd, off, ln, si, i, t = E[k]
        if k % 8 == 0 and k > 0:
            el = time.process_time() - b0
            proj = el * nE / k
            if proj > budget:
                K = max(KMIN, int(K * 0.7))
            elif proj < budget * 0.5 and K < KMAX:
                K = min(KMAX, K + 4)
            if el > budget * 1.15:
                K = 1
        if typ == 6:
            cm = {}
            merged = {}
            for h in beam:
                ns = []
                for S in h[1]:
                    r = cm.get(id(S))
                    if r is None:
                        r = _crash(S, nd)
                        cm[id(S)] = r
                    ns.append(r)
                ns = tuple(ns)
                o = merged.get(ns)
                if o is None or h[0] < o[0]:
                    merged[ns] = (h[0], ns, h[2], h[3])
            beam = sorted(merged.values(), key=lambda x: x[0])[:max(1, K)]
            continue
        if nS == 0:
            continue
        memo = {}
        cands = [si] if si >= 0 else range(nS)
        dl = dupc.get(k)
        isorig = k in origset
        newc = []
        for hidx, h in enumerate(beam):
            hc, sess, asg, om = h
            opts = []
            for s in cands:
                S = sess[s]
                r = memo.get(id(S))
                if r is None:
                    r = _trans(S, typ, nd, off, ln)
                    memo[id(S)] = r
                for c, NS in r:
                    opts.append((c, s, NS))
            if dl:
                ds = set()
                for j in dl:
                    s = om.get(j)
                    if s is not None and (si < 0 or s == si) and s not in ds:
                        ds.add(s)
                        opts.append((C_DUP, s, None))
            if not opts:
                if si >= 0:
                    fs = si
                else:
                    fs = 0
                    bd = None
                    for s in range(nS):
                        S = sess[s]
                        if S[0] != 0 and S[1] == nd:
                            d = abs(S[2] - (off if off is not None else S[2]))
                            if bd is None or d < bd:
                                bd = d
                                fs = s
                opts.append((C_ABSURD, fs, None))
            opts.sort(key=lambda x: (x[0], x[1]))
            best = opts[0][0]
            for c, s, NS in opts[:BR]:
                if c > best + DELTA:
                    break
                newc.append((hc + c, hidx, s, NS))
        if not newc:
            continue
        newc.sort(key=lambda x: (x[0], x[1], x[2]))
        merged = set()
        out = []
        for c, hidx, s, NS in newc:
            h = beam[hidx]
            sess = h[1]
            if NS is not None and NS != sess[s]:
                l = list(sess)
                l[s] = NS
                ns = tuple(l)
            else:
                ns = sess
            if ns in merged:
                continue
            om = h[3]
            if isorig:
                om = dict(om)
                om[k] = s
            merged.add(ns)
            out.append((c, ns, (k, s, h[2]), om))
            if len(out) >= max(1, K):
                break
        beam = out
    best = beam[0] if beam else (0.0, init, None, {})
    assign = {}
    node = best[2]
    while node is not None:
        k, s, node = node
        assign[k] = s
    assignments = {}
    if nS > 0:
        for k, (typ, nd, off, ln, si, i, t) in enumerate(E):
            if typ == 6 or si >= 0:
                continue
            s = assign.get(k)
            if s is not None:
                assignments[str(i)] = sids[s]
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted", 5: "active"}
    sessions = {}
    for s in range(nS):
        S = best[1][s]
        du = S[2] if S[0] == 3 else S[3]
        sessions[sids[s]] = {"status": names.get(S[0], "active"), "durable": int(du)}
    return assignments, sessions


def solve(state, params):
    t_start = time.process_time()
    inp = state.get("input") or {}
    if not isinstance(inp, dict):
        inp = {}
    raw = inp.get("events") or []
    recs = []
    for k, ev in enumerate(raw):
        if not isinstance(ev, dict):
            continue
        i = _toint(ev.get("i"))
        if i is None:
            i = k
        t = _toint(ev.get("t"))
        if t is None:
            t = 0
        sid = ev.get("sid")
        if sid is not None:
            sid = str(sid)
        recs.append((t, i, str(ev.get("node")), str(ev.get("type")), _toint(ev.get("off")),
                     _toint(ev.get("len")), sid))
    recs.sort(key=lambda z: (z[0], z[1]))
    n = len(recs)
    T = [r[0] for r in recs]
    IDX = [r[1] for r in recs]
    ND = [r[2] for r in recs]
    TY = [r[3] for r in recs]
    OFF = [r[4] if r[4] is not None else 0 for r in recs]
    LEN = [r[5] if r[5] is not None else 0 for r in recs]
    SIDR = [r[6] if r[3] != "crash" else None for r in recs]
    ENDOFF = [0] * n
    for k in range(n):
        if TY[k] == "write":
            ENDOFF[k] = OFF[k] + LEN[k]
        elif TY[k] in ("checkpoint", "commit", "recover"):
            ENDOFF[k] = OFF[k]
    SG = [(TY[k], ND[k], OFF[k], LEN[k]) for k in range(n)]

    sids = []
    sidx = {}
    open_t = {}
    for k in range(n):
        if TY[k] == "open" and SIDR[k] is not None and SIDR[k] not in sidx:
            sidx[SIDR[k]] = len(sids)
            sids.append(SIDR[k])
            open_t[sidx[SIDR[k]]] = T[k]
    for k in range(n):
        if TY[k] != "crash" and SIDR[k] is not None and SIDR[k] not in sidx:
            sidx[SIDR[k]] = len(sids)
            sids.append(SIDR[k])
            open_t[sidx[SIDR[k]]] = T[k]
    ns = len(sids)
    anon = [k for k in range(n) if TY[k] != "crash" and SIDR[k] is None]
    if ns == 0:
        state["output"] = {"assignments": {}, "sessions": {}}
        return state

    # ---------------- phase 1: beam tracking ----------------
    try:
        beam_asg, beam_sess = _beam(inp, t_start, 0.40)
    except Exception:
        beam_asg, beam_sess = {}, {}

    crash_k = [k for k in range(n) if TY[k] == "crash"]
    CT = [T[k] for k in crash_k]
    CN = [ND[k] for k in crash_k]
    nc = len(crash_k)
    node_crash_t = {}
    for k in crash_k:
        node_crash_t.setdefault(ND[k], []).append(T[k])

    gaps = [T[k + 1] - T[k] for k in range(n - 1)]
    mg = statistics.median(gaps) if gaps else 1
    W = max(3, int(3 * mg + 1))
    lab = {}
    for k in range(n):
        if SIDR[k] is not None and TY[k] in RANK:
            lab.setdefault(SIDR[k], []).append(k)
    maxinv = 0
    for s, ks in lab.items():
        for a in range(len(ks)):
            for b in range(a + 1, min(len(ks), a + 6)):
                ka = ks[a]
                kb = ks[b]
                if ND[ka] != ND[kb] or SG[ka] == SG[kb]:
                    continue
                if (OFF[kb], RANK[TY[kb]]) < (OFF[ka], RANK[TY[ka]]):
                    ct = node_crash_t.get(ND[ka], [])
                    j = bisect.bisect_left(ct, T[ka] - 2)
                    if j < len(ct) and ct[j] <= T[kb] + 2:
                        continue
                    if T[kb] - T[ka] <= 40:
                        maxinv = max(maxinv, T[kb] - T[ka])
    W = max(W, int(maxinv * 1.3) + 1)

    def new_state():
        return ["P", None, 0, 0, 0, None, 0, 0, -1, set(), 0]

    def do_crash(S, t, node):
        c = 0.0
        pk = S[8]
        if pk >= 0 and t - T[pk] > W:
            c += V_COST
            S[8] = -1
            pk = -1
        if S[0] == "A" and S[1] == node:
            S[0] = "D"
            S[4] = t
            S[5] = node
            S[6] = S[2]
            S[7] = S[3]
            S[2] = S[3]
            if pk >= 0:
                off = OFF[pk]
                if off > S[3]:
                    c += MISS
                    S[3] = off
                elif off < S[3]:
                    c += V_COST
                S[0] = "A"
                S[1] = ND[pk]
                S[2] = off
                S[8] = -1
                c += REORD
        return c

    def step(S, k):
        c = 0.0
        t = T[k]
        ty = TY[k]
        pk = S[8]
        if pk >= 0 and t - T[pk] > W:
            c += V_COST
            S[8] = -1
        sig = SG[k]
        seen = S[9]
        st = S[0]
        if ty == "open":
            if st == "P":
                S[0] = "A"
                S[1] = ND[k]
                seen.add(sig)
                return c
            return c + (DUP if sig in seen else V_COST)
        if st == "P":
            return c + V_COST
        if st == "C" or st == "X":
            if sig in seen:
                return c + DUP
            if t - S[10] <= W:
                return c + REORD
            return c + V_COST
        off = OFF[k]
        if st == "D":
            if ty == "recover":
                if off == S[3]:
                    pass
                elif off > S[3]:
                    c += MISS
                    S[3] = off
                else:
                    if sig in seen:
                        return c + DUP
                    c += V_COST
                    S[3] = off
                S[0] = "A"
                S[1] = ND[k]
                S[2] = off
                seen.add(sig)
                return c
            if t - S[4] <= W and ND[k] == S[5]:
                pc = S[6]
                if ty == "write" and off == pc:
                    S[6] = pc + LEN[k]
                    seen.add(sig)
                    return c + REORD
                if ty == "checkpoint" and off == pc:
                    S[7] = pc
                    S[3] = pc
                    S[2] = pc
                    seen.add(sig)
                    return c + REORD
                if ty == "commit" and off == pc:
                    S[0] = "C"
                    S[3] = pc
                    S[2] = pc
                    S[10] = t
                    seen.add(sig)
                    return c + REORD
                if ty == "abort":
                    S[0] = "X"
                    S[10] = t
                    seen.add(sig)
                    return c + REORD
            if sig in seen:
                return c + DUP
            c += MISS
            S[0] = "A"
            S[1] = ND[k]
            S[2] = S[3]
        if ty == "recover":
            if sig in seen:
                return c + DUP
            if S[8] < 0:
                S[8] = k
                seen.add(sig)
                return c
            return c + V_COST
        if ND[k] != S[1]:
            if sig in seen:
                return c + DUP
            c += V_COST
            S[1] = ND[k]
        cur = S[2]
        if ty == "write":
            if off == cur:
                S[2] = cur + LEN[k]
            elif off > cur:
                c += MISS
                S[2] = off + LEN[k]
            else:
                if sig in seen:
                    return c + DUP
                c += V_COST
                S[2] = off + LEN[k]
        elif ty == "checkpoint":
            if off == cur:
                S[3] = cur
            elif off > cur:
                c += MISS
                S[2] = off
                S[3] = off
            else:
                if sig in seen:
                    return c + DUP
                c += V_COST
        elif ty == "commit":
            if off > cur:
                c += MISS
            elif off < cur:
                if sig in seen:
                    return c + DUP
                c += V_COST
            S[0] = "C"
            S[2] = off
            S[3] = off
            S[10] = t
        elif ty == "abort":
            S[0] = "X"
            S[2] = S[3]
            S[10] = t
        else:
            c += V_COST
        seen.add(sig)
        return c

    def fix_order(seq):
        seq = list(seq)
        for a in range(1, len(seq)):
            j = a
            while j > 0:
                ka = seq[j - 1]
                kb = seq[j]
                tya = TY[ka]
                tyb = TY[kb]
                if tya not in RANK or tyb not in RANK:
                    break
                if ND[ka] != ND[kb] or T[kb] - T[ka] > W or SG[ka] == SG[kb]:
                    break
                if (OFF[kb], RANK[tyb]) >= (OFF[ka], RANK[tya]):
                    break
                ct = node_crash_t.get(ND[ka])
                if ct:
                    q = bisect.bisect_left(ct, T[ka])
                    if q < len(ct) and ct[q] <= T[kb]:
                        break
                seq[j - 1] = kb
                seq[j] = ka
                j -= 1
        return seq

    def simulate(seq, prev=None):
        F = fix_order(seq)
        p = 0
        if prev is not None:
            PF = prev[0]
            m = min(len(PF), len(F))
            while p < m and PF[p] == F[p]:
                p += 1
        if prev is not None and p > 0:
            snaps = prev[1][:p]
            AP = prev[2][:p]
            if p < len(prev[1]):
                sn = prev[1][p]
            else:
                sn = prev[3]
            S = list(sn[:9])
            S.append({SG[F[q]] for q in range(p) if AP[q]})
            S.append(sn[9])
            ci = sn[10]
            c = sn[11]
        else:
            p = 0
            snaps = []
            AP = []
            S = new_state()
            c = 0.0
            ci = 0
            if F:
                ci = bisect.bisect_left(CT, T[F[0]] - 1)
        seen = S[9]
        for j in range(p, len(F)):
            k = F[j]
            t = T[k]
            snaps.append((S[0], S[1], S[2], S[3], S[4], S[5], S[6], S[7], S[8], S[10], ci, c))
            while ci < nc and (CT[ci] < t or (CT[ci] == t and crash_k[ci] < k)):
                if S[0] == "A" or S[8] >= 0:
                    c += do_crash(S, CT[ci], CN[ci])
                ci += 1
            c += step(S, k)
            AP.append(SG[k] in seen)
        endsnap = (S[0], S[1], S[2], S[3], S[4], S[5], S[6], S[7], S[8], S[10], ci, c)
        while ci < nc:
            if S[0] == "A" or S[8] >= 0:
                c += do_crash(S, CT[ci], CN[ci])
            ci += 1
        if S[8] >= 0:
            c += V_COST
        return c, (F, snaps, AP, endsnap), S

    cands = {}
    for k in anon:
        cl = [s for s in range(ns) if open_t[s] <= T[k]]
        if not cl:
            cl = list(range(ns))
        cands[k] = cl

    lab_by_s = [[] for _ in range(ns)]
    for k in range(n):
        if TY[k] != "crash" and SIDR[k] is not None:
            lab_by_s[sidx[SIDR[k]]].append(k)
    labT = [[T[k] for k in lst] for lst in lab_by_s]

    # ---------------- greedy fallback ----------------
    assign = {}
    missing = [k for k in anon if beam_asg.get(str(IDX[k])) not in sidx]
    if missing:
        def copy_state(S):
            X = list(S)
            X[9] = set(S[9])
            return X
        states = [new_state() for _ in range(ns)]
        last_act = [-1] * ns
        for k in range(n):
            ty = TY[k]
            if ty == "crash":
                for s in range(ns):
                    if states[s][0] == "A" or states[s][8] >= 0:
                        do_crash(states[s], T[k], ND[k])
                continue
            if SIDR[k] is not None:
                s = sidx[SIDR[k]]
                step(states[s], k)
                last_act[s] = k
                continue
            bsid = beam_asg.get(str(IDX[k]))
            if bsid in sidx:
                bs = sidx[bsid]
            else:
                best = None
                bs = cands[k][0]
                for s in cands[k]:
                    X = copy_state(states[s])
                    c = step(X, k)
                    lst = lab_by_s[s]
                    q = bisect.bisect_right(labT[s], T[k])
                    if q < len(lst) and TY[lst[q]] != "open":
                        c += 0.5 * step(copy_state(X), lst[q])
                    rec = last_act[s] if ND[k] == states[s][1] else -5
                    key = (c, -rec, s)
                    if best is None or key < best:
                        best = key
                        bs = s
            assign[k] = bs
            step(states[bs], k)
            last_act[bs] = k
    else:
        for k in anon:
            assign[k] = sidx[beam_asg[str(IDX[k])]]
    seed_assign = dict(assign)

    # ---------------- phase 2: annealing seeded by the beam ----------------
    sess_ev = [list(lab_by_s[s]) for s in range(ns)]
    for k in anon:
        bisect.insort(sess_ev[assign[k]], k)
    cache = []
    cost = []
    for s in range(ns):
        rr = simulate(sess_ev[s])
        cost.append(rr[0])
        cache.append(rr[1])
    total = sum(cost)
    seed_total = total
    best_total = total
    best_assign = dict(assign)
    rng = random.Random(1234567)
    na = len(anon)
    anon_pos = {k: p for p, k in enumerate(anon)}
    deadline = t_start + 0.86
    T0 = 1.0
    T1 = 0.05
    it = 0
    if na > 0 and ns > 1:
        sa_start = time.process_time()
        span = max(1e-6, deadline - sa_start)
        temp = T0
        while True:
            if (it & 15) == 0:
                now = time.process_time()
                if now >= deadline:
                    break
                frac = (now - sa_start) / span
                temp = T0 * (T1 / T0) ** frac
            it += 1
            r = rng.random()
            moves = []
            k = anon[rng.randrange(na)]
            a = assign[k]
            if r < 0.55:
                cl = cands[k]
                if len(cl) < 2:
                    continue
                if rng.random() < 0.75:
                    fit = []
                    nfit = []
                    nk = ND[k]
                    ok_ = OFF[k]
                    tyk = TY[k]
                    for s in cl:
                        if s == a:
                            continue
                        lst = sess_ev[s]
                        q = bisect.bisect_left(lst, k)
                        if q == 0:
                            continue
                        kp = lst[q - 1]
                        if ND[kp] == nk:
                            nfit.append(s)
                            if tyk in RANK and ENDOFF[kp] == ok_:
                                fit.append(s)
                        elif tyk == "recover" and (TY[kp] in RANK or TY[kp] == "recover"):
                            if ENDOFF[kp] >= ok_:
                                fit.append(s)
                    if fit and rng.random() < 0.7:
                        pool = fit
                    else:
                        pool = nfit or fit or cl
                    b = pool[rng.randrange(len(pool))]
                else:
                    b = cl[rng.randrange(len(cl))]
                if b == a:
                    continue
                moves.append((k, b))
            elif r < 0.75:
                p = anon_pos[k]
                lo = max(0, p - 15)
                hi = min(na - 1, p + 15)
                k2 = anon[rng.randint(lo, hi)]
                b = assign[k2]
                if b == a or b not in cands[k] or a not in cands[k2]:
                    continue
                moves.append((k, b))
                moves.append((k2, a))
            elif r < 0.88:
                b = rng.randrange(ns)
                if b == a:
                    continue
                p = anon_pos[k]
                L = rng.randint(3, 40)
                for q in range(p, min(na, p + L)):
                    kk = anon[q]
                    sa = assign[kk]
                    if sa == a and b in cands[kk]:
                        moves.append((kk, b))
                    elif sa == b and a in cands[kk]:
                        moves.append((kk, a))
                if not moves:
                    continue
            else:
                # tail swap: exchange all anonymous events on this node of two sessions from k onward
                nk = ND[k]
                others = [s for s in cands[k] if s != a]
                if not others:
                    continue
                b = others[rng.randrange(len(others))]
                p = anon_pos[k]
                for q in range(p, na):
                    kk = anon[q]
                    if ND[kk] != nk:
                        continue
                    sa = assign[kk]
                    if sa == a and b in cands[kk]:
                        moves.append((kk, b))
                    elif sa == b and a in cands[kk]:
                        moves.append((kk, a))
                if not moves:
                    continue
            touched = set()
            for kk, nb in moves:
                touched.add(assign[kk])
                touched.add(nb)
            newl = {}
            for s in touched:
                newl[s] = list(sess_ev[s])
            for kk, nb in moves:
                lst = newl[assign[kk]]
                del lst[bisect.bisect_left(lst, kk)]
                bisect.insort(newl[nb], kk)
            newc = {}
            newcache = {}
            delta = 0.0
            for s in touched:
                rr = simulate(newl[s], cache[s])
                newc[s] = rr[0]
                newcache[s] = rr[1]
                delta += rr[0] - cost[s]
            accept = delta <= 0
            if not accept:
                x = delta / temp
                if x < 50 and rng.random() < math.exp(-x):
                    accept = True
            if accept:
                for s in touched:
                    sess_ev[s] = newl[s]
                    cost[s] = newc[s]
                    cache[s] = newcache[s]
                for kk, nb in moves:
                    assign[kk] = nb
                total += delta
                if total < best_total - 1e-9:
                    best_total = total
                    best_assign = dict(assign)

    stmap = {"C": "committed", "X": "aborted", "A": "active", "D": "down", "P": "active"}
    margin = max(0.8, 0.004 * n)
    use_sa = best_total < seed_total - margin
    final = best_assign if use_sa else seed_assign
    sess_ev = [list(lab_by_s[s]) for s in range(ns)]
    for k in anon:
        bisect.insort(sess_ev[final[k]], k)
    out_sessions = {}
    for s in range(ns):
        sid = sids[s]
        if (not use_sa) and sid in beam_sess and not missing:
            out_sessions[sid] = beam_sess[sid]
        else:
            S = simulate(sess_ev[s])[2]
            out_sessions[sid] = {"status": stmap.get(S[0], "active"), "durable": int(S[3])}
    assignments = {}
    for k in anon:
        assignments[str(IDX[k])] = sids[final[k]]
    state["output"] = {"assignments": assignments, "sessions": out_sessions}
    state["used_sa"] = bool(use_sa)
    state["sa_iters"] = it
    return state

import time
import random
import bisect
import math

TYPE_CODE = {"open": 0, "write": 1, "checkpoint": 2, "commit": 3, "abort": 4, "recover": 5, "crash": 6}
STATUS_NAME = ["active", "down", "committed", "aborted"]
C_GAP = 1.0
C_BAD = 3.0
C_NODE = 3.0
C_MISSREC = 1.0
C_END = 5.0
C_DUP = 0.05
C_RECACT = 3.0
W_ABORT_GAP = 0.5
W_SILENT = 0.3


def _int_or_none(x):
    if x is None:
        return None
    try:
        return int(x)
    except Exception:
        return None


def _fallback(inp):
    evs = inp.get("events") or []
    last_on_node = {}
    sess = {}
    assign = {}
    for e in sorted(evs, key=lambda x: (_int_or_none(x.get("t")) or 0, _int_or_none(x.get("i")) or 0)):
        ty = e.get("type")
        sid = e.get("sid")
        nd = e.get("node")
        if ty == "crash":
            continue
        if sid is not None:
            sess.setdefault(sid, {"status": "active", "durable": 0})
            last_on_node[nd] = sid
        else:
            s = last_on_node.get(nd)
            if s is None and sess:
                s = sorted(sess)[0]
            if s is not None:
                assign[str(e.get("i"))] = s
    for e in evs:
        if e.get("type") != "crash" and e.get("sid") is None and str(e.get("i")) not in assign:
            assign[str(e.get("i"))] = sorted(sess)[0] if sess else "s0"
    return {"assignments": assign, "sessions": sess}


def solve(state, params):
    t0 = time.process_time()
    inp = state.get("input") or {}
    try:
        out = _solve(inp, t0)
    except Exception:
        out = _fallback(inp)
    state["output"] = out
    return state


def _solve(inp, t0):
    BUDGET = 0.70
    raw = list(inp.get("events") or [])
    keyed = []
    for k, e in enumerate(raw):
        t = _int_or_none(e.get("t"))
        keyed.append((t if t is not None else 0, k, e))
    keyed.sort(key=lambda x: (x[0], x[1]))
    n = len(keyed)
    T = [0] * n
    ND = [0] * n
    TY = [0] * n
    OF = [None] * n
    LN = [0] * n
    OUTI = [""] * n
    SIDL = [None] * n
    node_ix = {}
    for p, (t, k, e) in enumerate(keyed):
        T[p] = t
        nd = e.get("node")
        if nd not in node_ix:
            node_ix[nd] = len(node_ix)
        ND[p] = node_ix[nd]
        TY[p] = TYPE_CODE.get(e.get("type"), 1)
        OF[p] = _int_or_none(e.get("off"))
        ln = _int_or_none(e.get("len"))
        LN[p] = ln if ln is not None else 0
        OUTI[p] = str(e.get("i") if e.get("i") is not None else k)
        SIDL[p] = e.get("sid")
    SIG = [(ND[p], TY[p], OF[p], LN[p]) for p in range(n)]

    # sessions
    sids = []
    sidx = {}
    open_pos = []
    for p in range(n):
        if TY[p] == 0 and SIDL[p] is not None and SIDL[p] not in sidx:
            sidx[SIDL[p]] = len(sids)
            sids.append(SIDL[p])
            open_pos.append(p)
    for p in range(n):
        if TY[p] != 6 and SIDL[p] is not None and SIDL[p] not in sidx:
            sidx[SIDL[p]] = len(sids)
            sids.append(SIDL[p])
            open_pos.append(-1)
    S = len(sids)
    crashes = [p for p in range(n) if TY[p] == 6]
    anon = [p for p in range(n) if TY[p] != 6 and SIDL[p] is None]
    if S == 0:
        return {"assignments": {OUTI[p]: "s0" for p in anon}, "sessions": {}}
    first_pos = []
    for s in range(S):
        if open_pos[s] >= 0:
            first_pos.append(open_pos[s])
        else:
            fp = n
            for p in range(n):
                if SIDL[p] == sids[s]:
                    fp = p
                    break
            first_pos.append(fp)
    t_min = T[0] if n else 0
    t_end = T[-1] if n else 0
    span = float(max(1, t_end - t_min))

    # jitter window estimation
    diffs = sorted(T[p + 1] - T[p] for p in range(n - 1) if T[p + 1] > T[p])
    g = diffs[len(diffs) // 2] if diffs else 1
    maxinv = 0
    by_s = {}
    for p in range(n):
        if TY[p] in (1, 2, 3) and SIDL[p] is not None and OF[p] is not None:
            by_s.setdefault(SIDL[p], []).append(p)
    for s, lst in by_s.items():
        starts = {}
        for p in lst:
            starts.setdefault(OF[p], []).append(p)
        for a in lst:
            if TY[a] != 1:
                continue
            end = OF[a] + LN[a]
            for b in starts.get(end, ()):
                if T[b] < T[a]:
                    maxinv = max(maxinv, T[a] - T[b])
    J = max(10 * g, 2 * maxinv, 1)

    crashT = [T[c] for c in crashes]

    # candidates for each anonymous event
    cand = {}
    for p in anon:
        cs = [s for s in range(S) if first_pos[s] < p or (open_pos[s] < 0)]
        if not cs:
            cs = list(range(S))
        cand[p] = cs

    def step(p, status, node, cur, dur):
        if status >= 2:
            return (C_END, status, node, cur, dur)
        ty = TY[p]
        en = ND[p]
        o = OF[p]
        c = 0.0
        if ty == 5:
            if o is None:
                o = dur
            if status == 1:
                if o != dur:
                    c += C_GAP if o > dur else C_BAD
            else:
                c += C_RECACT
            return (c, 0, en, o, o)
        if status == 1:
            c += C_MISSREC
            status = 0
            node = en
        elif node != en:
            if node is None:
                node = en
            else:
                c += C_NODE
                node = en
        if ty == 1:
            if o is None:
                o = cur
            if o != cur:
                c += C_GAP if o > cur else C_BAD
            cur = o + LN[p]
        elif ty == 2:
            if o is None:
                o = cur
            if o != cur:
                c += C_GAP if o > cur else C_BAD
            cur = o
            dur = o
        elif ty == 3:
            if o is None:
                o = cur
            if o != cur:
                c += C_GAP if o > cur else C_BAD
            cur = o
            dur = o
            status = 2
        elif ty == 4:
            status = 3
        elif ty == 0:
            c += C_BAD
        return (c, status, node, cur, dur)

    def sim(slist, want_bad):
        if not slist:
            return (0.0, 0, 0, [])
        first = slist[0]
        if TY[first] == 0:
            status, node, cur, dur = 0, ND[first], 0, 0
            body = slist[1:]
        else:
            status, node, cur, dur = 0, None, 0, 0
            body = slist[:]
        ci = bisect.bisect_left(crashT, T[first])
        if ci < len(crashes):
            rem = sorted(body + [c for c in crashes[ci:] if c > first])
        else:
            rem = body[:]
        cost = 0.0
        bad = []
        seen = set()
        last_t = T[first]
        while rem:
            choose = 0
            if status < 2:
                h = rem[0]
                lim = T[h] + J
                L = len(rem)
                j = 0
                head_abort = TY[h] == 4
                alt = -1
                while j < L and j < 8:
                    q = rem[j]
                    if T[q] > lim:
                        break
                    tq = TY[q]
                    if tq != 6 and tq != 4:
                        if alt < 0:
                            alt = j
                        r = step(q, status, node, cur, dur)
                        if r[0] == 0:
                            choose = j
                            alt = -2
                            break
                    j += 1
                if alt >= 0 and head_abort:
                    choose = alt
            p = rem.pop(choose)
            if TY[p] == 6:
                if status == 0 and node == ND[p]:
                    status = 1
                    cur = dur
                continue
            r = step(p, status, node, cur, dur)
            c = r[0]
            sg = SIG[p]
            if c > 0 and sg in seen:
                cost += C_DUP
                continue
            if TY[p] == 4 and status < 2:
                c += W_ABORT_GAP * max(0, T[p] - last_t) / span
            cost += c
            if want_bad and c >= 1.0:
                bad.append(p)
            status, node, cur, dur = r[1], r[2], r[3], r[4]
            seen.add(sg)
            last_t = T[p]
        if status == 0:
            cost += W_SILENT * max(0, t_end - last_t) / span
        return (cost, status, dur, bad)

    # ---------------- greedy initialisation (anchor seeded, crash aware) ----------------
    owner = [-1] * n
    for p in range(n):
        if TY[p] != 6 and SIDL[p] is not None:
            owner[p] = sidx[SIDL[p]]
    gst = [None] * S  # [status,node,cur,dur,last_t,seen,cptr]
    NC = len(crashes)

    def apply_crash(st, c):
        if st[0] == 0 and st[1] == ND[c]:
            st[0] = 1
            st[2] = st[3]

    def settle(st, p):
        t = T[p]
        while st[6] < NC and crashes[st[6]] < p and T[crashes[st[6]]] + J < t:
            apply_crash(st, crashes[st[6]])
            st[6] += 1

    def evaluate(st, p):
        best = None
        k = st[6]
        unc = []
        while k < NC and crashes[k] < p:
            unc.append(crashes[k])
            k += 1
        options = [(st[0], st[1], st[2], st[3], 0)]
        if unc:
            a = [st[0], st[1], st[2], st[3]]
            for c in unc:
                if a[0] == 0 and a[1] == ND[c]:
                    a[0] = 1
                    a[2] = a[3]
            if (a[0], a[2]) != (st[0], st[2]):
                options.append((a[0], a[1], a[2], a[3], len(unc)))
        for (stt, nd, cu, du, nc) in options:
            r = step(p, stt, nd, cu, du)
            c = r[0]
            dupf = False
            if c > 0 and SIG[p] in st[5]:
                c = C_DUP
                dupf = True
            if best is None or c < best[0]:
                best = (c, r, nc, dupf)
        return best

    def commit_ev(st, p, res):
        c, r, nc, dupf = res
        st[6] += nc
        if not dupf:
            st[0], st[1], st[2], st[3] = r[1], r[2], r[3], r[4]
            st[5].add(SIG[p])
        st[4] = T[p]

    for p in range(n):
        ty = TY[p]
        if ty == 6:
            continue
        s = owner[p]
        if s >= 0 and gst[s] is None:
            ci = bisect.bisect_right(crashes, p)
            gst[s] = [0, ND[p], 0, 0, T[p], set(), ci]
            if ty == 0:
                continue
        if s >= 0:
            st = gst[s]
            settle(st, p)
            commit_ev(st, p, evaluate(st, p))
            continue
        best = None
        for s2 in cand[p]:
            st = gst[s2]
            if st is None:
                continue
            settle(st, p)
            res = evaluate(st, p)
            key = (res[0], T[p] - st[4])
            if best is None or key < best[0]:
                best = (key, s2, res)
        if best is None:
            owner[p] = cand[p][0]
            continue
        owner[p] = best[1]
        commit_ev(gst[best[1]], p, best[2])

    # ---------------- stochastic local search (annealing) ----------------
    lists = [[] for _ in range(S)]
    for p in range(n):
        if TY[p] != 6 and owner[p] >= 0:
            lists[owner[p]].append(p)
    scost = [0.0] * S
    sbad = [[] for _ in range(S)]
    for s in range(S):
        r = sim(lists[s], True)
        scost[s] = r[0]
        sbad[s] = r[3]
    total = sum(scost)
    best_total = total
    best_owner = owner[:]
    anon_set = set(anon)
    NA = len(anon)
    anon_rank = {p: k for k, p in enumerate(anon)}
    rng = random.Random(12345)
    T0, T1 = 0.6, 0.02
    deadline = BUDGET
    it = 0
    last_improve = 0
    temp = T0

    def remove_sorted(lst, p):
        k = bisect.bisect_left(lst, p)
        if k < len(lst) and lst[k] == p:
            lst.pop(k)

    if NA > 0 and S > 1:
        while True:
            if (it & 15) == 0:
                el = time.process_time() - t0
                if el > deadline:
                    break
                frac = el / deadline
                temp = T0 * (T1 / T0) ** min(1.0, frac)
                if it - last_improve > 4000 and total > best_total + 1e-9:
                    owner = best_owner[:]
                    lists = [[] for _ in range(S)]
                    for p in range(n):
                        if TY[p] != 6 and owner[p] >= 0:
                            lists[owner[p]].append(p)
                    for s in range(S):
                        r = sim(lists[s], True)
                        scost[s] = r[0]
                        sbad[s] = r[3]
                    total = sum(scost)
                    last_improve = it
            it += 1
            e = -1
            if rng.random() < 0.7:
                bs = [s for s in range(S) if sbad[s]]
                if bs:
                    s = bs[rng.randrange(len(bs))]
                    b = sbad[s][rng.randrange(len(sbad[s]))]
                    lst = lists[s]
                    k = bisect.bisect_left(lst, b)
                    lo = max(0, k - 3)
                    hi = min(len(lst), k + 2)
                    pool = [q for q in lst[lo:hi] if q in anon_set]
                    if not pool:
                        k2 = bisect.bisect_left(anon, b)
                        lo = max(0, k2 - 4)
                        hi = min(NA, k2 + 4)
                        pool = anon[lo:hi]
                    if pool:
                        e = pool[rng.randrange(len(pool))]
            if e < 0:
                e = anon[rng.randrange(NA)]
            A = owner[e]
            cs = cand[e]
            if len(cs) < 2:
                continue
            B = cs[rng.randrange(len(cs))]
            if B == A:
                continue
            r = rng.random()
            if r < 0.55:
                la = lists[A][:]
                remove_sorted(la, e)
                lb = lists[B][:]
                bisect.insort(lb, e)
                moved = [(e, B)]
            elif r < 0.8:
                k = anon_rank[e]
                lo = max(0, k - 12)
                hi = min(NA, k + 13)
                pool = [q for q in anon[lo:hi] if owner[q] == B and A in cand[q]]
                if not pool:
                    continue
                e2 = pool[rng.randrange(len(pool))]
                la = lists[A][:]
                remove_sorted(la, e)
                bisect.insort(la, e2)
                lb = lists[B][:]
                remove_sorted(lb, e2)
                bisect.insort(lb, e)
                moved = [(e, B), (e2, A)]
            else:
                if rng.random() < 0.5:
                    limit = n
                else:
                    k = anon_rank[e]
                    k2 = min(NA - 1, k + rng.randint(1, 8))
                    limit = anon[k2] + 1
                la = []
                lb = []
                moved = []
                for q in lists[A]:
                    if q >= e and q < limit and q in anon_set:
                        moved.append((q, B))
                    else:
                        la.append(q)
                for q in lists[B]:
                    if q >= e and q < limit and q in anon_set:
                        moved.append((q, A))
                    else:
                        lb.append(q)
                if len(moved) < 2:
                    continue
                for (q, s2) in moved:
                    if s2 == A:
                        la.append(q)
                    else:
                        lb.append(q)
                la.sort()
                lb.sort()
            ra = sim(la, True)
            rb = sim(lb, True)
            delta = ra[0] + rb[0] - scost[A] - scost[B]
            if delta <= 0 or rng.random() < math.exp(-delta / temp):
                lists[A] = la
                lists[B] = lb
                scost[A] = ra[0]
                scost[B] = rb[0]
                sbad[A] = ra[3]
                sbad[B] = rb[3]
                for (q, s2) in moved:
                    owner[q] = s2
                total += delta
                if total < best_total - 1e-9:
                    best_total = total
                    best_owner = owner[:]
                    last_improve = it

    owner = best_owner
    lists = [[] for _ in range(S)]
    for p in range(n):
        if TY[p] != 6 and owner[p] >= 0:
            lists[owner[p]].append(p)
    sessions = {}
    for s in range(S):
        r = sim(lists[s], False)
        sessions[sids[s]] = {"status": STATUS_NAME[r[1]], "durable": int(r[2])}
    assignments = {}
    for p in anon:
        s = owner[p]
        if s < 0:
            s = 0
        assignments[OUTI[p]] = sids[s]
    return {"assignments": assignments, "sessions": sessions}

import time, random, bisect, math
from collections import defaultdict

TYC = {"open": 0, "write": 1, "checkpoint": 2, "commit": 3, "abort": 4, "recover": 5, "crash": 6}
DUPC = 0.15
GAPC = 1.0
BACKC = 3.0
BIG = 10 ** 18


def solve(state, params):
    t_start = time.process_time()
    inp = state["input"]
    raw = sorted(inp["events"], key=lambda e: (e["t"], e["i"]))
    n = len(raw)
    node_ix = {}
    for nd in inp.get("nodes", []):
        node_ix.setdefault(nd, len(node_ix))
    T = []; ND = []; TY = []; OF = []; LN = []; LAB = []; IDX = []
    for e in raw:
        nd = e.get("node")
        if nd not in node_ix:
            node_ix[nd] = len(node_ix)
        T.append(int(e["t"])); ND.append(node_ix[nd]); TY.append(TYC.get(e["type"], 1))
        OF.append(e.get("off")); LN.append(e.get("len")); LAB.append(e.get("sid")); IDX.append(e["i"])
    sids = []; sidx = {}; open_pos = []
    for p in range(n):
        if TY[p] == 0 and LAB[p] is not None and LAB[p] not in sidx:
            sidx[LAB[p]] = len(sids); sids.append(LAB[p]); open_pos.append(p)
    NS = len(sids)
    MUL = n + 1
    KEY = [T[p] * MUL + p for p in range(n)]

    def start(p):
        ty = TY[p]
        if ty == 0: return 0
        if ty == 4 or ty == 6: return None
        return OF[p] if OF[p] is not None else 0

    def end(p):
        ty = TY[p]
        if ty == 0: return 0
        if ty == 1: return (OF[p] or 0) + (LN[p] or 0)
        if ty == 4 or ty == 6: return None
        return OF[p] if OF[p] is not None else 0

    ST = [start(p) for p in range(n)]
    EN = [end(p) for p in range(n)]
    DK = [(TY[p], ND[p], OF[p], LN[p]) for p in range(n)]
    crashes = [p for p in range(n) if TY[p] == 6]
    CK = [KEY[p] for p in crashes]; CN = [ND[p] for p in crashes]; CT = [T[p] for p in crashes]
    NC = len(crashes)
    crash_t_by_node = defaultdict(list)
    for p in crashes:
        crash_t_by_node[ND[p]].append(T[p])

    # ---- jitter window estimate
    gaps = sorted(T[i + 1] - T[i] for i in range(n - 1)) or [1]
    g = max(1, gaps[len(gaps) // 2])
    invs = [0]
    bys = defaultdict(list)
    for p in range(n):
        if LAB[p] in sidx and TY[p] in (1, 2, 3):
            bys[LAB[p]].append(p)
    for s, lst in bys.items():
        seenk = set()
        for a, b in zip(lst, lst[1:]):
            seenk.add(DK[a])
            if DK[b] in seenk:
                continue
            if ND[a] == ND[b] and ST[b] < ST[a] and not crash_t_by_node.get(ND[a]):
                invs.append(T[b] - T[a])
    W = max(max(invs) + 1, 3 * g, 3)

    def okey(p):
        ty = TY[p]
        if ty == 2: return (ST[p], 0)
        if ty == 1: return (ST[p], 1)
        if ty == 3: return (ST[p], 2)
        return (BIG, 3)

    OK = [okey(p) for p in range(n)]

    def crash_near(nd, lo, hi):
        lst = crash_t_by_node.get(nd)
        if not lst: return False
        j = bisect.bisect_left(lst, lo)
        return j < len(lst) and lst[j] <= hi

    def order(ps):
        lst = sorted(ps)
        for j in range(1, len(lst)):
            while j > 0:
                a = lst[j - 1]; b = lst[j]
                if (1 <= TY[a] <= 4 and 1 <= TY[b] <= 4 and ND[a] == ND[b]
                        and T[b] - T[a] <= W and OK[a] > OK[b]
                        and not crash_near(ND[a], T[a] - W, T[b] + W)):
                    lst[j - 1] = b; lst[j] = a; j -= 1
                else:
                    break
        return lst

    # S = [node, cur, dur, stt, pre_cur, pre_t, crash_ptr, last_t, uncertain]
    def init(s):
        o = open_pos[s]
        return [ND[o], 0, 0, 0, None, None, bisect.bisect_right(CK, KEY[o]), T[o], 0]

    def apply_crashes_until(S, kp):
        k = S[6]
        while k < NC and CK[k] < kp:
            if S[3] == 0 and CN[k] == S[0]:
                S[4] = S[1]; S[5] = CT[k]; S[1] = S[2]; S[3] = 1
                S[8] = 1 if CT[k] - S[7] <= W else 0
            k += 1
        S[6] = k

    def step2(S, p):
        ty = TY[p]
        c = 0.0
        if ty == 0:
            return 50.0
        if S[3] >= 2:
            return 4.0
        if ty == 5 and S[3] == 0:
            k = S[6]; lim = T[p] + W
            while k < NC and CT[k] <= lim and S[3] == 0:
                if CN[k] == S[0]:
                    S[4] = S[1]; S[5] = CT[k]; S[1] = S[2]; S[3] = 1
                    S[8] = 1
                k += 1
            S[6] = k
            if S[3] == 0:
                S[0] = ND[p]; S[1] = OF[p] or 0; S[2] = S[1]
                return 3.0
            c += 0.3
        if S[3] == 1:
            if ty == 5:
                o_ = OF[p] or 0
                if o_ == S[2]:
                    pass
                elif S[4] is not None and S[2] < o_ <= S[4]:
                    c += 1.0
                else:
                    c += 2.5
                S[0] = ND[p]; S[1] = o_; S[2] = o_; S[3] = 0; S[4] = None; S[5] = None
                return c
            s0 = ST[p]
            if (ND[p] == S[0] and S[5] is not None and T[p] - S[5] <= W and ty in (1, 2)
                    and S[4] is not None and s0 is not None):
                if s0 == S[4]: c += 0.4
                elif s0 > S[4]: c += 1.4
                else: c += 3.0
                if ty == 1:
                    S[4] = EN[p]
                else:
                    S[2] = OF[p] or 0; S[4] = S[2]; S[1] = S[2]
                return c
            if (ND[p] == S[0] and S[4] is not None and s0 is not None and s0 == S[4]
                    and ty in (1, 2, 3) and (S[8] or S[4] != S[2])):
                c += 0.6 if S[8] else 2.0
                S[1] = S[4]; S[3] = 0; S[4] = None; S[5] = None
            elif ty == 4 or (s0 is not None and s0 == S[2]):
                c += 1.2
                S[0] = ND[p]; S[3] = 0; S[1] = S[2]; S[4] = None; S[5] = None
            else:
                return 4.0
        if ND[p] != S[0]:
            if ty == 5:
                S[0] = ND[p]; S[1] = OF[p] or 0; S[2] = S[1]
                return c + 3.0
            return c + 5.0
        if ty == 5:
            S[1] = OF[p] or 0; S[2] = S[1]
            return c + 3.0
        if ty == 4:
            S[3] = 3; S[1] = S[2]
            return c
        s0 = ST[p]; cur = S[1]
        if s0 != cur:
            c += GAPC if s0 > cur else BACKC
        if ty == 1:
            S[1] = EN[p]
        else:
            S[1] = s0; S[2] = s0
            if ty == 3:
                S[3] = 2
        return c

    def step(S, p):
        apply_crashes_until(S, KEY[p])
        r = step2(S, p)
        if T[p] > S[7]:
            S[7] = T[p]
        return r

    def replay(s, ps):
        o = open_pos[s]
        S = init(s)
        seen = set()
        cost = 0.0
        for p in order(ps):
            if p == o: continue
            if p < o:
                cost += 50.0; continue
            dk = DK[p]
            if dk in seen:
                cost += DUPC; continue
            seen.add(dk)
            cost += step(S, p)
        apply_crashes_until(S, BIG)
        return cost, S

    assign = [-1] * n
    anon = []
    for p in range(n):
        if TY[p] == 6: continue
        if LAB[p] in sidx:
            assign[p] = sidx[LAB[p]]
        else:
            anon.append(p)

    if NS == 0:
        state["output"] = {"assignments": {str(IDX[p]): "" for p in anon}, "sessions": {}}
        return state

    cands = {}
    for p in anon:
        cands[p] = [s for s in range(NS) if open_pos[s] < p]

    # ---- fragments via mutually unique exact continuity
    by_ns = defaultdict(list)
    for p in range(n):
        if TY[p] in (1, 2, 3):
            by_ns[(ND[p], ST[p])].append(p)
    G = 40 * g
    succ = {}; predc = defaultdict(int)
    for a in range(n):
        if TY[a] not in (0, 1, 2, 5): continue
        lo_pos = open_pos[assign[a]] if assign[a] >= 0 else -1
        lst = [b for b in by_ns.get((ND[a], EN[a]), ()) if b != a and DK[b] != DK[a]
               and T[a] - W <= T[b] <= T[a] + G and b > lo_pos]
        if len(lst) == 1:
            succ[a] = lst[0]
    for a, b in succ.items():
        predc[b] += 1
    par = list(range(n)); lab = list(assign)

    def find(x):
        while par[x] != x:
            par[x] = par[par[x]]; x = par[x]
        return x
    for a, b in succ.items():
        if predc[b] != 1: continue
        ra, rb = find(a), find(b)
        if ra == rb: continue
        la, lb = lab[ra], lab[rb]
        if la >= 0 and lb >= 0 and la != lb: continue
        par[rb] = ra; lab[ra] = la if la >= 0 else lb
    comp = defaultdict(list)
    for p in anon:
        comp[find(p)].append(p)
    pinned = {}
    frags = []
    for r, mem in comp.items():
        if lab[r] >= 0:
            for p in mem:
                if open_pos[lab[r]] < p:
                    pinned[p] = lab[r]
        elif len(mem) > 1:
            frags.append(mem)

    # ---- greedy online init
    states = [None] * NS
    seens = [set() for _ in range(NS)]
    lastt = [0] * NS
    for p in range(n):
        if TY[p] == 6: continue
        if TY[p] == 0 and LAB[p] in sidx and open_pos[sidx[LAB[p]]] == p:
            s = sidx[LAB[p]]; states[s] = init(s); lastt[s] = T[p]; continue
        if assign[p] >= 0 or p in pinned:
            s = assign[p] if assign[p] >= 0 else pinned[p]
            assign[p] = s
            if states[s] is None: continue
            if DK[p] not in seens[s]:
                seens[s].add(DK[p]); step(states[s], p)
            lastt[s] = T[p]
            continue
        best = None
        for s in cands[p]:
            if states[s] is None: continue
            if DK[p] in seens[s]:
                c = DUPC + 0.05
            else:
                S2 = states[s][:]
                c = step(S2, p)
            key = (c, -(lastt[s] if ND[p] == states[s][0] else -10 ** 9))
            if best is None or key < best[0]:
                best = (key, s)
        if best is None:
            assign[p] = 0
            continue
        s = best[1]; assign[p] = s; lastt[s] = T[p]
        if DK[p] not in seens[s]:
            seens[s].add(DK[p]); step(states[s], p)

    members = [set() for _ in range(NS)]
    for p in range(n):
        if assign[p] >= 0:
            members[assign[p]].add(p)
    costs = [replay(s, members[s])[0] for s in range(NS)]

    by_ne = defaultdict(list)
    for p in range(n):
        if TY[p] != 6 and EN[p] is not None:
            by_ne[(ND[p], EN[p])].append(p)
    nbr = {}
    for p in anon:
        lst = []
        if ST[p] is not None:
            lst += [q for q in by_ne.get((ND[p], ST[p]), ()) if q != p and abs(T[q] - T[p]) <= G]
        if EN[p] is not None:
            lst += [q for q in by_ns.get((ND[p], EN[p]), ()) if q != p and abs(T[q] - T[p]) <= G]
        lst += [q for q in range(max(0, p - 6), min(n, p + 7)) if q != p and TY[q] != 6 and ND[q] == ND[p]]
        nbr[p] = lst

    units = ([[p] for p in anon] + frags) if anon else []
    rng = random.Random(12345)
    cur_total = sum(costs)
    best_total = cur_total; best_assign = assign[:]
    budget = 0.65
    it = 0
    T0, T1 = 0.8, 0.03
    elapsed = time.process_time() - t_start
    while units and elapsed < budget:
        it += 1
        if it % 16 == 0:
            elapsed = time.process_time() - t_start
        frac = min(1.0, elapsed / budget)
        temp = T0 * (T1 / T0) ** frac
        mv = rng.random()
        if mv >= 0.88 and len(anon) >= 2:
            p = anon[rng.randrange(len(anon))]
            a = assign[p]
            nb = nbr.get(p)
            if nb and rng.random() < 0.7:
                b = assign[nb[rng.randrange(len(nb))]]
            else:
                cl = cands[p]
                b = cl[rng.randrange(len(cl))] if cl else a
            if b < 0 or a < 0 or b == a: continue
            hi = n if rng.random() < 0.5 else p + 1 + rng.randrange(40)
            ma = [q for q in members[a] if p <= q < hi and q in cands]
            mb = [q for q in members[b] if p <= q < hi and q in cands]
            if any(open_pos[b] >= q for q in ma) or any(open_pos[a] >= q for q in mb): continue
            for q in ma:
                members[a].discard(q); members[b].add(q)
            for q in mb:
                members[b].discard(q); members[a].add(q)
            na = replay(a, members[a])[0]; nb2 = replay(b, members[b])[0]
            delta = na + nb2 - costs[a] - costs[b]
            if delta <= 0 or rng.random() < math.exp(-delta / temp):
                for q in ma: assign[q] = b
                for q in mb: assign[q] = a
                costs[a] = na; costs[b] = nb2
                cur_total += delta
                if cur_total < best_total - 1e-9:
                    best_total = cur_total; best_assign = assign[:]
            else:
                for q in ma:
                    members[b].discard(q); members[a].add(q)
                for q in mb:
                    members[a].discard(q); members[b].add(q)
        elif mv < 0.66 or len(anon) < 2:
            u = units[rng.randrange(len(units))]
            p0 = min(u)
            cl = cands[p0]
            if not cl: continue
            if rng.random() < 0.6 and nbr.get(u[0]):
                q = nbr[u[0]][rng.randrange(len(nbr[u[0]]))]
                tgt = assign[q]
                if tgt < 0 or open_pos[tgt] >= p0: continue
            else:
                tgt = cl[rng.randrange(len(cl))]
            moving = [p for p in u if assign[p] != tgt]
            if not moving: continue
            aff = set(assign[p] for p in moving)
            aff.add(tgt)
            for p in moving:
                members[assign[p]].discard(p); members[tgt].add(p)
            newc = {}
            for s in aff:
                newc[s] = replay(s, members[s])[0]
            delta = sum(newc[s] - costs[s] for s in aff)
            if delta <= 0 or rng.random() < math.exp(-delta / temp):
                for p in moving: assign[p] = tgt
                for s in aff: costs[s] = newc[s]
                cur_total += delta
                if cur_total < best_total - 1e-9:
                    best_total = cur_total; best_assign = assign[:]
            else:
                for p in moving:
                    members[tgt].discard(p)
                    members[assign[p]].add(p)
        else:
            p = anon[rng.randrange(len(anon))]
            nb = nbr.get(p)
            if not nb: continue
            q = nb[rng.randrange(len(nb))]
            if q not in cands or assign[q] == assign[p]: continue
            a, b = assign[p], assign[q]
            if a < 0 or b < 0: continue
            if open_pos[b] >= p or open_pos[a] >= q: continue
            members[a].discard(p); members[b].discard(q); members[a].add(q); members[b].add(p)
            na = replay(a, members[a])[0]; nb2 = replay(b, members[b])[0]
            delta = na + nb2 - costs[a] - costs[b]
            if delta <= 0 or rng.random() < math.exp(-delta / temp):
                assign[p] = b; assign[q] = a; costs[a] = na; costs[b] = nb2
                cur_total += delta
                if cur_total < best_total - 1e-9:
                    best_total = cur_total; best_assign = assign[:]
            else:
                members[a].discard(q); members[b].discard(p); members[a].add(p); members[b].add(q)

    assign = best_assign
    members = [set() for _ in range(NS)]
    for p in range(n):
        if assign[p] >= 0:
            members[assign[p]].add(p)
    sess_out = {}
    for s in range(NS):
        c, S = replay(s, members[s])
        st = {0: "active", 1: "down", 2: "committed", 3: "aborted"}.get(S[3], "active")
        sess_out[sids[s]] = {"status": st, "durable": int(S[2] or 0)}
    asg = {}
    for p in anon:
        asg[str(IDX[p])] = sids[assign[p]] if assign[p] >= 0 else sids[0]
    state["output"] = {"assignments": asg, "sessions": sess_out}
    return state

import time
import random
import bisect
import math
import statistics

V_COST = 5.0
MISS = 1.0
REORD = 0.3
DUP = 0.3
RANK = {"checkpoint": 0, "write": 1, "commit": 2}
SWITCH_MARGIN = 1.0

C_GAP = 3.0
C_JIT = 0.7
C_STALE = 8.0
C_DUP = 1.5
C_MISSREC = 3.5
C_LATE = 2.5
C_EARLYREC = 3.0
C_MISSCK = 3.0
C_COMMIT_BACK = 5.0
C_ABSURD = 25.0
TYPES = {"open": 0, "write": 1, "checkpoint": 2, "commit": 3, "abort": 4, "recover": 5, "crash": 6}


def _toint(x):
    if x is None or isinstance(x, bool):
        return None
    try:
        return int(x)
    except Exception:
        try:
            return int(float(x))
        except Exception:
            return None


def _addgap(gaps, a, b):
    g = gaps + ((a, b),)
    if len(g) > 3:
        g = g[-3:]
    return g


def _fill(gaps, a, b):
    for k, (g0, g1) in enumerate(gaps):
        if g0 <= a and b <= g1 and b > a:
            pieces = []
            if a > g0:
                pieces.append((g0, a))
            if b < g1:
                pieces.append((b, g1))
            ng = gaps[:k] + tuple(pieces) + gaps[k + 1:]
            return ng, C_GAP * (1 - len(pieces))
    return None


def _trans(S, typ, nd, off, ln):
    st, sn, so, du, gp, ax = S
    out = []
    if typ == 0:
        if st == 0:
            out.append((0.0, (1, nd, 0, 0, (), -1)))
        return out
    if st == 0:
        return out
    if off is None and typ in (1, 2, 3, 5):
        off = so
    if typ == 1:
        if ln is None:
            ln = 0
        if st == 1 or st == 5:
            if sn == nd:
                if off == so:
                    out.append((0.0, (st, sn, off + ln, du, gp, ax)))
                elif off > so:
                    out.append((C_GAP, (st, sn, off + ln, du, _addgap(gp, so, off), ax)))
                else:
                    f = _fill(gp, off, off + ln)
                    if f is not None:
                        out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
                    else:
                        out.append((C_STALE, S))
        elif st == 2:
            if off >= du:
                if off == du:
                    out.append((C_MISSREC, (1, nd, off + ln, du, gp, -1)))
                else:
                    out.append((C_MISSREC + C_GAP, (1, nd, off + ln, du, _addgap(gp, du, off), -1)))
                if sn == nd:
                    out.append((C_LATE, S))
            else:
                f = _fill(gp, off, off + ln)
                if f is not None:
                    out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
        else:
            f = _fill(gp, off, off + ln)
            if f is not None:
                out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
        return out
    if typ == 2 or typ == 3:
        if st == 1 or st == 5:
            if sn == nd:
                nst = 3 if typ == 3 else st
                if off == so:
                    out.append((0.0, (nst, sn, off, off, gp, ax)))
                elif off > so:
                    out.append((C_GAP, (nst, sn, off, off, _addgap(gp, so, off), ax)))
                elif off >= du:
                    if typ == 2:
                        out.append((C_JIT, (st, sn, so, off, gp, ax)))
                    else:
                        out.append((C_COMMIT_BACK, (3, sn, off, off, gp, ax)))
                else:
                    out.append((C_STALE, S))
        elif st == 2:
            if off >= du:
                nst = 3 if typ == 3 else 1
                c = C_MISSREC + (C_GAP if off > du else 0.0)
                out.append((c, (nst, nd, off, off, gp, -1)))
                if sn == nd and typ == 2:
                    out.append((C_LATE, (2, sn, off, off, gp, ax)))
        return out
    if typ == 4:
        if st == 1 or st == 5:
            if sn == nd:
                out.append((0.0, (4, sn, so, du, gp, ax)))
        elif st == 2:
            out.append((C_MISSREC * 0.6, (4, sn, so, du, gp, ax)))
        return out
    if typ == 5:
        if st == 2:
            if off == du:
                out.append((0.0, (1, nd, off, off, gp, -1)))
            elif off > du:
                out.append((C_MISSCK, (1, nd, off, off, gp, -1)))
            else:
                out.append((C_STALE, (1, nd, du, du, gp, -1)))
        elif st == 1:
            if du <= off <= so:
                out.append((C_EARLYREC + (0.0 if off == du else C_MISSCK * 0.5),
                            (5, nd, off, off, gp, sn)))
        return out
    return out


def _crash(S, nd):
    st = S[0]
    if st == 1:
        if S[1] == nd:
            du = S[3]
            return (2, nd, du, du, tuple(g for g in S[4] if g[1] <= du), -1)
        return S
    if st == 5:
        if S[5] == nd:
            return (1, S[1], S[2], S[3], S[4], -1)
        if S[1] == nd:
            du = S[3]
            return (2, nd, du, du, tuple(g for g in S[4] if g[1] <= du), -1)
    return S


def _beam(inp, t_start, budget):
    raw = inp.get("events") or []
    nodes = list(inp.get("nodes") or [])
    evs = []
    for pos, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        i = _toint(e.get("i"))
        if i is None:
            i = pos
        t = _toint(e.get("t"))
        evs.append((t if t is not None else 0, i, e, i))
    evs.sort(key=lambda x: (x[0], x[1]))
    node_idx = {}
    for nn in nodes:
        nn = str(nn)
        if nn not in node_idx:
            node_idx[nn] = len(node_idx)
    sids = []
    sid_idx = {}
    for _, _, e, _ in evs:
        s = e.get("sid")
        if s is not None and e.get("type") != "crash":
            s = str(s)
            if s not in sid_idx:
                sid_idx[s] = len(sids)
                sids.append(s)
    E = []
    for t, pos, e, i in evs:
        typ = TYPES.get(e.get("type"), -1)
        if typ < 0:
            continue
        nn = str(e.get("node"))
        if nn not in node_idx:
            node_idx[nn] = len(node_idx)
        s = e.get("sid")
        si = -1
        if s is not None and typ != 6:
            si = sid_idx[str(s)]
        E.append((typ, node_idx[nn], _toint(e.get("off")), _toint(e.get("len")), si, i, t))
    nS = len(sids)
    nE = len(E)
    dupc = {}
    origset = set()
    seen = {}
    for k, (typ, nd, off, ln, si, i, t) in enumerate(E):
        if typ == 0 or typ == 6:
            continue
        key = (typ, nd, off, ln)
        lst = seen.get(key)
        if lst:
            dupc[k] = lst[-4:]
            for j in lst[-4:]:
                origset.add(j)
        seen.setdefault(key, []).append(k)
    init = tuple((0, -1, 0, 0, (), -1) for _ in range(nS))
    beam = [(0.0, init, None, {})]
    K = 24
    KMAX = 40
    KMIN = 3
    BR = 6
    DELTA = 12.0
    b0 = time.process_time()
    for k in range(nE):
        typ, nd, off, ln, si, i, t = E[k]
        if k % 8 == 0 and k > 0:
            el = time.process_time() - b0
            proj = el * nE / k
            if proj > budget:
                K = max(KMIN, int(K * 0.7))
            elif proj < budget * 0.5 and K < KMAX:
                K = min(KMAX, K + 4)
            if el > budget * 1.15:
                K = 1
        if typ == 6:
            cm = {}
            merged = {}
            for h in beam:
                ns = []
                for S in h[1]:
                    r = cm.get(id(S))
                    if r is None:
                        r = _crash(S, nd)
                        cm[id(S)] = r
                    ns.append(r)
                ns = tuple(ns)
                o = merged.get(ns)
                if o is None or h[0] < o[0]:
                    merged[ns] = (h[0], ns, h[2], h[3])
            beam = sorted(merged.values(), key=lambda x: x[0])[:max(1, K)]
            continue
        if nS == 0:
            continue
        memo = {}
        cands = [si] if si >= 0 else range(nS)
        dl = dupc.get(k)
        isorig = k in origset
        newc = []
        for hidx, h in enumerate(beam):
            hc, sess, asg, om = h
            opts = []
            for s in cands:
                S = sess[s]
                r = memo.get(id(S))
                if r is None:
                    r = _trans(S, typ, nd, off, ln)
                    memo[id(S)] = r
                for c, NS in r:
                    opts.append((c, s, NS))
            if dl:
                ds = set()
                for j in dl:
                    s = om.get(j)
                    if s is not None and (si < 0 or s == si) and s not in ds:
                        ds.add(s)
                        opts.append((C_DUP, s, None))
            if not opts:
                if si >= 0:
                    fs = si
                else:
                    fs = 0
                    bd = None
                    for s in range(nS):
                        S = sess[s]
                        if S[0] != 0 and S[1] == nd:
                            d = abs(S[2] - (off if off is not None else S[2]))
                            if bd is None or d < bd:
                                bd = d
                                fs = s
                opts.append((C_ABSURD, fs, None))
            opts.sort(key=lambda x: (x[0], x[1]))
            best = opts[0][0]
            for c, s, NS in opts[:BR]:
                if c > best + DELTA:
                    break
                newc.append((hc + c, hidx, s, NS))
        if not newc:
            continue
        newc.sort(key=lambda x: (x[0], x[1], x[2]))
        merged = set()
        out = []
        for c, hidx, s, NS in newc:
            h = beam[hidx]
            sess = h[1]
            if NS is not None and NS != sess[s]:
                l = list(sess)
                l[s] = NS
                ns = tuple(l)
            else:
                ns = sess
            if ns in merged:
                continue
            om = h[3]
            if isorig:
                om = dict(om)
                om[k] = s
            merged.add(ns)
            out.append((c, ns, (k, s, h[2]), om))
            if len(out) >= max(1, K):
                break
        beam = out
    best = beam[0] if beam else (0.0, init, None, {})
    assign = {}
    node = best[2]
    while node is not None:
        k, s, node = node
        assign[k] = s
    assignments = {}
    if nS > 0:
        for k, (typ, nd, off, ln, si, i, t) in enumerate(E):
            if typ == 6 or si >= 0:
                continue
            s = assign.get(k)
            if s is not None:
                assignments[str(i)] = sids[s]
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted", 5: "active"}
    sessions = {}
    for s in range(nS):
        S = best[1][s]
        du = S[2] if S[0] == 3 else S[3]
        sessions[sids[s]] = {"status": names.get(S[0], "active"), "durable": int(du)}
    return assignments, sessions


def solve(state, params):
    t_start = time.process_time()
    inp = state.get("input") or {}
    if not isinstance(inp, dict):
        inp = {}
    raw = inp.get("events") or []
    recs = []
    for k, ev in enumerate(raw):
        if not isinstance(ev, dict):
            continue
        i = _toint(ev.get("i"))
        if i is None:
            i = k
        t = _toint(ev.get("t"))
        if t is None:
            t = 0
        sid = ev.get("sid")
        if sid is not None:
            sid = str(sid)
        recs.append((t, i, str(ev.get("node")), str(ev.get("type")), _toint(ev.get("off")),
                     _toint(ev.get("len")), sid))
    recs.sort(key=lambda z: (z[0], z[1]))
    n = len(recs)
    T = [r[0] for r in recs]
    IDX = [r[1] for r in recs]
    ND = [r[2] for r in recs]
    TY = [r[3] for r in recs]
    OFF = [r[4] if r[4] is not None else 0 for r in recs]
    LEN = [r[5] if r[5] is not None else 0 for r in recs]
    SIDR = [r[6] if r[3] != "crash" else None for r in recs]
    ENDOFF = [0] * n
    for k in range(n):
        if TY[k] == "write":
            ENDOFF[k] = OFF[k] + LEN[k]
        elif TY[k] in ("checkpoint", "commit", "recover"):
            ENDOFF[k] = OFF[k]
    SG = [(TY[k], ND[k], OFF[k], LEN[k]) for k in range(n)]

    sids = []
    sidx = {}
    open_t = {}
    for k in range(n):
        if TY[k] == "open" and SIDR[k] is not None and SIDR[k] not in sidx:
            sidx[SIDR[k]] = len(sids)
            sids.append(SIDR[k])
            open_t[sidx[SIDR[k]]] = T[k]
    for k in range(n):
        if TY[k] != "crash" and SIDR[k] is not None and SIDR[k] not in sidx:
            sidx[SIDR[k]] = len(sids)
            sids.append(SIDR[k])
            open_t[sidx[SIDR[k]]] = T[k]
    ns = len(sids)
    anon = [k for k in range(n) if TY[k] != "crash" and SIDR[k] is None]
    if ns == 0:
        state["output"] = {"assignments": {}, "sessions": {}}
        return state

    # ---------------- phase 1: beam tracking ----------------
    try:
        beam_asg, beam_sess = _beam(inp, t_start, 0.30)
    except Exception:
        beam_asg, beam_sess = {}, {}

    crash_k = [k for k in range(n) if TY[k] == "crash"]
    CT = [T[k] for k in crash_k]
    CN = [ND[k] for k in crash_k]
    nc = len(crash_k)
    node_crash_t = {}
    for k in crash_k:
        node_crash_t.setdefault(ND[k], []).append(T[k])

    gaps = [T[k + 1] - T[k] for k in range(n - 1)]
    mg = statistics.median(gaps) if gaps else 1
    W = max(3, int(3 * mg + 1))
    lab = {}
    for k in range(n):
        if SIDR[k] is not None and TY[k] in RANK:
            lab.setdefault(SIDR[k], []).append(k)
    maxinv = 0
    for s, ks in lab.items():
        for a in range(len(ks)):
            for b in range(a + 1, min(len(ks), a + 6)):
                ka = ks[a]
                kb = ks[b]
                if ND[ka] != ND[kb] or SG[ka] == SG[kb]:
                    continue
                if (OFF[kb], RANK[TY[kb]]) < (OFF[ka], RANK[TY[ka]]):
                    ct = node_crash_t.get(ND[ka], [])
                    j = bisect.bisect_left(ct, T[ka] - 2)
                    if j < len(ct) and ct[j] <= T[kb] + 2:
                        continue
                    if T[kb] - T[ka] <= 40:
                        maxinv = max(maxinv, T[kb] - T[ka])
    W = max(W, int(maxinv * 1.3) + 1)

    def new_state():
        return ["P", None, 0, 0, 0, None, 0, 0, -1, set(), 0]

    def do_crash(S, t, node):
        c = 0.0
        pk = S[8]
        if pk >= 0 and t - T[pk] > W:
            c += V_COST
            S[8] = -1
            pk = -1
        if S[0] == "A" and S[1] == node:
            S[0] = "D"
            S[4] = t
            S[5] = node
            S[6] = S[2]
            S[7] = S[3]
            S[2] = S[3]
            if pk >= 0:
                off = OFF[pk]
                if off > S[3]:
                    c += MISS
                    S[3] = off
                elif off < S[3]:
                    c += V_COST
                S[0] = "A"
                S[1] = ND[pk]
                S[2] = max(off, S[3])
                S[8] = -1
                c += REORD
        return c

    def step(S, k):
        c = 0.0
        t = T[k]
        ty = TY[k]
        pk = S[8]
        if pk >= 0 and t - T[pk] > W:
            c += V_COST
            S[8] = -1
        sig = SG[k]
        seen = S[9]
        st = S[0]
        if ty == "open":
            if st == "P":
                S[0] = "A"
                S[1] = ND[k]
                seen.add(sig)
                return c
            return c + (DUP if sig in seen else V_COST)
        if st == "P":
            return c + V_COST
        if st == "C" or st == "X":
            if sig in seen:
                return c + DUP
            if t - S[10] <= W:
                return c + REORD
            return c + V_COST
        off = OFF[k]
        if st == "D":
            if ty == "recover":
                if off == S[3]:
                    pass
                elif off > S[3]:
                    c += MISS
                    S[3] = off
                else:
                    if sig in seen:
                        return c + DUP
                    c += V_COST
                    # durable never decreases
                S[0] = "A"
                S[1] = ND[k]
                S[2] = S[3]
                seen.add(sig)
                return c
            if t - S[4] <= W and ND[k] == S[5]:
                pc = S[6]
                if ty == "write" and off == pc:
                    S[6] = pc + LEN[k]
                    seen.add(sig)
                    return c + REORD
                if ty == "checkpoint" and off == pc:
                    S[7] = pc
                    S[3] = pc
                    S[2] = pc
                    seen.add(sig)
                    return c + REORD
                if ty == "commit" and off == pc:
                    S[0] = "C"
                    S[3] = pc
                    S[2] = pc
                    S[10] = t
                    seen.add(sig)
                    return c + REORD
                if ty == "abort":
                    S[0] = "X"
                    S[10] = t
                    seen.add(sig)
                    return c + REORD
            if sig in seen:
                return c + DUP
            c += MISS
            S[0] = "A"
            S[1] = ND[k]
            S[2] = S[3]
            if ty == "write" and off > S[3]:
                # implicit recover: resume point reveals a missing checkpoint
                c += MISS
                S[3] = off
                S[2] = off
        if ty == "recover":
            if sig in seen:
                return c + DUP
            if S[8] < 0:
                S[8] = k
                seen.add(sig)
                return c
            return c + V_COST
        if ND[k] != S[1]:
            if sig in seen:
                return c + DUP
            c += V_COST
            S[1] = ND[k]
        cur = S[2]
        if ty == "write":
            if off == cur:
                S[2] = cur + LEN[k]
            elif off > cur:
                c += MISS
                S[2] = off + LEN[k]
            else:
                if sig in seen:
                    return c + DUP
                c += V_COST
                S[2] = off + LEN[k]
        elif ty == "checkpoint":
            if off == cur:
                S[3] = max(S[3], cur)
            elif off > cur:
                c += MISS
                S[2] = off
                S[3] = off
            else:
                if sig in seen:
                    return c + DUP
                c += V_COST
        elif ty == "commit":
            if off > cur:
                c += MISS
            elif off < cur:
                if sig in seen:
                    return c + DUP
                c += V_COST
            S[0] = "C"
            S[2] = off
            S[3] = off
            S[10] = t
        elif ty == "abort":
            S[0] = "X"
            S[2] = S[3]
            S[10] = t
        else:
            c += V_COST
        seen.add(sig)
        return c

    def fix_order(seq):
        seq = list(seq)
        for a in range(1, len(seq)):
            j = a
            while j > 0:
                ka = seq[j - 1]
                kb = seq[j]
                tya = TY[ka]
                tyb = TY[kb]
                if tya not in RANK or tyb not in RANK:
                    break
                if ND[ka] != ND[kb] or T[kb] - T[ka] > W or SG[ka] == SG[kb]:
                    break
                if (OFF[kb], RANK[tyb]) >= (OFF[ka], RANK[tya]):
                    break
                ct = node_crash_t.get(ND[ka])
                if ct:
                    q = bisect.bisect_left(ct, T[ka])
                    if q < len(ct) and ct[q] <= T[kb]:
                        break
                seq[j - 1] = kb
                seq[j] = ka
                j -= 1
        return seq

    def simulate(seq, prev=None):
        F = fix_order(seq)
        p = 0
        if prev is not None:
            PF = prev[0]
            m = min(len(PF), len(F))
            while p < m and PF[p] == F[p]:
                p += 1
        if prev is not None and p > 0:
            snaps = prev[1][:p]
            AP = prev[2][:p]
            if p < len(prev[1]):
                sn = prev[1][p]
            else:
                sn = prev[3]
            S = list(sn[:9])
            S.append({SG[F[q]] for q in range(p) if AP[q]})
            S.append(sn[9])
            ci = sn[10]
            c = sn[11]
        else:
            p = 0
            snaps = []
            AP = []
            S = new_state()
            c = 0.0
            ci = 0
            if F:
                ci = bisect.bisect_left(CT, T[F[0]] - 1)
        seen = S[9]
        for j in range(p, len(F)):
            k = F[j]
            t = T[k]
            snaps.append((S[0], S[1], S[2], S[3], S[4], S[5], S[6], S[7], S[8], S[10], ci, c))
            while ci < nc and (CT[ci] < t or (CT[ci] == t and crash_k[ci] < k)):
                if S[0] == "A" or S[8] >= 0:
                    c += do_crash(S, CT[ci], CN[ci])
                ci += 1
            c += step(S, k)
            AP.append(SG[k] in seen)
        endsnap = (S[0], S[1], S[2], S[3], S[4], S[5], S[6], S[7], S[8], S[10], ci, c)
        while ci < nc:
            if S[0] == "A" or S[8] >= 0:
                c += do_crash(S, CT[ci], CN[ci])
            ci += 1
        if S[8] >= 0:
            c += V_COST
        return c, (F, snaps, AP, endsnap), S

    cands = {}
    for k in anon:
        cl = [s for s in range(ns) if open_t[s] <= T[k]]
        if not cl:
            cl = list(range(ns))
        cands[k] = cl

    lab_by_s = [[] for _ in range(ns)]
    for k in range(n):
        if TY[k] != "crash" and SIDR[k] is not None:
            lab_by_s[sidx[SIDR[k]]].append(k)
    labT = [[T[k] for k in lst] for lst in lab_by_s]

    # ---------------- greedy fallback for events the beam left unassigned ----------------
    assign = {}
    missing = [k for k in anon if beam_asg.get(str(IDX[k])) not in sidx]
    if missing:
        def copy_state(S):
            X = list(S)
            X[9] = set(S[9])
            return X
        states = [new_state() for _ in range(ns)]
        last_act = [-1] * ns
        for k in range(n):
            ty = TY[k]
            if ty == "crash":
                for s in range(ns):
                    if states[s][0] == "A" or states[s][8] >= 0:
                        do_crash(states[s], T[k], ND[k])
                continue
            if SIDR[k] is not None:
                s = sidx[SIDR[k]]
                step(states[s], k)
                last_act[s] = k
                continue
            bsid = beam_asg.get(str(IDX[k]))
            if bsid in sidx:
                bs = sidx[bsid]
            else:
                best = None
                bs = cands[k][0]
                for s in cands[k]:
                    X = copy_state(states[s])
                    c = step(X, k)
                    lst = lab_by_s[s]
                    q = bisect.bisect_right(labT[s], T[k])
                    if q < len(lst) and TY[lst[q]] != "open":
                        c += 0.5 * step(copy_state(X), lst[q])
                    rec = last_act[s] if ND[k] == states[s][1] else -5
                    key = (c, -rec, s)
                    if best is None or key < best:
                        best = key
                        bs = s
            assign[k] = bs
            step(states[bs], k)
            last_act[bs] = k
    else:
        for k in anon:
            assign[k] = sidx[beam_asg[str(IDX[k])]]
    seed_assign = dict(assign)

    # ---------------- phase 2: annealing seeded by the beam ----------------
    sess_ev = [list(lab_by_s[s]) for s in range(ns)]
    for k in anon:
        bisect.insort(sess_ev[assign[k]], k)
    cache = []
    cost = []
    for s in range(ns):
        rr = simulate(sess_ev[s])
        cost.append(rr[0])
        cache.append(rr[1])
    total = sum(cost)
    seed_total = total
    best_total = total
    best_assign = dict(assign)
    rng = random.Random(1234567)
    na = len(anon)
    anon_pos = {k: p for p, k in enumerate(anon)}
    deadline = t_start + 0.82
    T0 = 1.0
    T1 = 0.05
    it = 0
    if na > 0 and ns > 1:
        sa_start = time.process_time()
        span = max(1e-6, deadline - sa_start)
        temp = T0
        while True:
            if (it & 15) == 0:
                now = time.process_time()
                if now >= deadline:
                    break
                frac = (now - sa_start) / span
                temp = T0 * (T1 / T0) ** frac
            it += 1
            r = rng.random()
            moves = []
            k = anon[rng.randrange(na)]
            a = assign[k]
            if r < 0.6:
                cl = cands[k]
                if len(cl) < 2:
                    continue
                if rng.random() < 0.75:
                    fit = []
                    nfit = []
                    nk = ND[k]
                    ok_ = OFF[k]
                    tyk = TY[k]
                    for s in cl:
                        if s == a:
                            continue
                        lst = sess_ev[s]
                        q = bisect.bisect_left(lst, k)
                        if q == 0:
                            continue
                        kp = lst[q - 1]
                        if ND[kp] == nk:
                            nfit.append(s)
                            if tyk in RANK and ENDOFF[kp] == ok_:
                                fit.append(s)
                        elif tyk == "recover" and (TY[kp] in RANK or TY[kp] == "recover"):
                            if ENDOFF[kp] >= ok_:
                                fit.append(s)
                    if fit and rng.random() < 0.7:
                        pool = fit
                    else:
                        pool = nfit or fit or cl
                    b = pool[rng.randrange(len(pool))]
                else:
                    b = cl[rng.randrange(len(cl))]
                if b == a:
                    continue
                moves.append((k, b))
            elif r < 0.85:
                p = anon_pos[k]
                lo = max(0, p - 15)
                hi = min(na - 1, p + 15)
                k2 = anon[rng.randint(lo, hi)]
                b = assign[k2]
                if b == a or b not in cands[k] or a not in cands[k2]:
                    continue
                moves.append((k, b))
                moves.append((k2, a))
            else:
                b = rng.randrange(ns)
                if b == a:
                    continue
                p = anon_pos[k]
                L = rng.randint(3, 40)
                for q in range(p, min(na, p + L)):
                    kk = anon[q]
                    sa = assign[kk]
                    if sa == a and b in cands[kk]:
                        moves.append((kk, b))
                    elif sa == b and a in cands[kk]:
                        moves.append((kk, a))
                if not moves:
                    continue
            touched = set()
            for kk, nb in moves:
                touched.add(assign[kk])
                touched.add(nb)
            newl = {}
            for s in touched:
                newl[s] = list(sess_ev[s])
            for kk, nb in moves:
                lst = newl[assign[kk]]
                del lst[bisect.bisect_left(lst, kk)]
                bisect.insort(newl[nb], kk)
            newc = {}
            newcache = {}
            delta = 0.0
            for s in touched:
                rr = simulate(newl[s], cache[s])
                newc[s] = rr[0]
                newcache[s] = rr[1]
                delta += rr[0] - cost[s]
            accept = delta <= 0
            if not accept:
                x = delta / temp
                if x < 50 and rng.random() < math.exp(-x):
                    accept = True
            if accept:
                for s in touched:
                    sess_ev[s] = newl[s]
                    cost[s] = newc[s]
                    cache[s] = newcache[s]
                for kk, nb in moves:
                    assign[kk] = nb
                total += delta
                if total < best_total - 1e-9:
                    best_total = total
                    best_assign = dict(assign)

    # ---------------- final: consistent states from the chosen assignment ----------------
    stmap = {"C": "committed", "X": "aborted", "A": "active", "D": "down", "P": "active"}
    use_sa = best_total < seed_total - SWITCH_MARGIN
    final = best_assign if use_sa else seed_assign
    sess_ev = [list(lab_by_s[s]) for s in range(ns)]
    for k in anon:
        bisect.insort(sess_ev[final[k]], k)
    out_sessions = {}
    for s in range(ns):
        sid = sids[s]
        S = simulate(sess_ev[s])[2]
        rep_status = stmap.get(S[0], "active")
        rep_du = int(S[3])
        ckmax = 0
        for k in sess_ev[s]:
            if TY[k] == "checkpoint" or TY[k] == "recover":
                if OFF[k] > ckmax:
                    ckmax = OFF[k]
        if (not use_sa) and sid in beam_sess and not missing:
            bs = beam_sess[sid]
            status = bs.get("status", "active")
            du = _toint(bs.get("durable"))
            if du is None:
                du = 0
            if status != "committed":
                if rep_status != "committed":
                    du = max(du, rep_du)
                du = max(du, ckmax)
        else:
            status = rep_status
            du = rep_du
            if status != "committed":
                du = max(du, ckmax)
        out_sessions[sid] = {"status": status, "durable": int(du)}
    assignments = {}
    for k in anon:
        assignments[str(IDX[k])] = sids[final[k]]
    state["output"] = {"assignments": assignments, "sessions": out_sessions}
    state["used_sa"] = bool(use_sa)
    state["sa_iters"] = it
    return state

import bisect
import time
from collections import defaultdict

WCC_SET = frozenset(['write', 'checkpoint', 'commit'])
G_GAP = 2.0
R0 = 1.8
C_ABORT = 0.3
C_DUP = 0.2
C_BAD = 6.0
C_FALL = 8.0
C_MISSREC = 2.0
C_MISSCK = 1.5
C_SWAP = 0.1
C_DEF = 5.0
BIG = 100.0
ALPHA = 0.1
TC_CAP = 1.0
SOFT_BUDGET = 0.55
HARD_BUDGET = 1.1
FINAL_BUDGET = 0.95
NEG = -1e18


def solve(state, params):
    t0 = time.process_time()
    inp = state.get("input") or {}
    try:
        out = _solve(inp, t0)
    except Exception:
        out = _fallback(inp)
    state["output"] = out
    return state


def _fallback(inp):
    evs = sorted(list(inp.get("events") or []), key=lambda e: (e.get("t") or 0, e.get("i") or 0))
    sess = []
    lastopen = {}
    for e in evs:
        if e.get("type") == "open" and e.get("sid") is not None:
            s = e.get("sid")
            if s not in sess:
                sess.append(s)
    for e in evs:
        s = e.get("sid")
        if s is not None and e.get("type") != "crash" and s not in sess:
            sess.append(s)
    default = sess[0] if sess else "s0"
    assign = {}
    for e in evs:
        if e.get("type") == "open" and e.get("sid") is not None:
            lastopen[e.get("node")] = e.get("sid")
        if e.get("type") == "crash" or e.get("sid") is not None:
            continue
        assign[str(e.get("i"))] = lastopen.get(e.get("node"), default)
    sessions = {}
    for s in sess:
        sessions[s] = {"status": "active", "durable": 0}
    return {"assignments": assign, "sessions": sessions}


def _after(ty, node, o, l, dbase, tl, sigs, pref):
    if ty == 'write':
        return (node, o + (l or 0), dbase, tl, sigs, pref, None)
    if ty == 'checkpoint':
        return (node, o, o, tl, sigs, pref, None)
    return (node, o, o, tl, sigs, pref, 'commit')


def _solve(inp, t0):
    evs = sorted(list(inp.get("events") or []), key=lambda e: (e.get("t") or 0, e.get("i") or 0))
    N = len(evs)
    typ = [e.get("type") for e in evs]
    nod = [e.get("node") for e in evs]
    off = [e.get("off") for e in evs]
    ln = [(e.get("len") or 0) for e in evs]
    tt = [(e.get("t") or 0) for e in evs]
    sidl = [e.get("sid") for e in evs]
    idx = [e.get("i") for e in evs]

    sess = []
    openpos = {}
    for q in range(N):
        if typ[q] == 'open' and sidl[q] is not None and sidl[q] not in openpos:
            openpos[sidl[q]] = q
            sess.append(sidl[q])
    if not sess:
        return _fallback(inp)
    extra_sess = []
    for q in range(N):
        s = sidl[q]
        if s is not None and typ[q] != 'crash' and s not in openpos and s not in extra_sess:
            extra_sess.append(s)
    own = [None] * N
    for q in range(N):
        if typ[q] != 'crash' and sidl[q] is not None:
            own[q] = sidl[q]
    anon = [q for q in range(N) if typ[q] != 'crash' and sidl[q] is None]

    exact = defaultdict(list)
    anyoff = defaultdict(list)
    nodepos = defaultdict(list)
    abortpos = defaultdict(list)
    recpos = []
    sigpos = defaultdict(list)
    crashpos = defaultdict(list)
    crasht = defaultdict(list)
    ownpos = defaultdict(list)
    sig = [None] * N
    for q in range(N):
        ty = typ[q]
        if ty == 'crash':
            crashpos[nod[q]].append(q)
            crasht[nod[q]].append(tt[q])
            continue
        if ty != 'open':
            sig[q] = (nod[q], ty, off[q], ln[q])
            sigpos[sig[q]].append(q)
            if own[q] is not None:
                ownpos[own[q]].append(q)
        if ty in WCC_SET and off[q] is not None:
            exact[(nod[q], off[q])].append(q)
            anyoff[off[q]].append(q)
            nodepos[nod[q]].append(q)
        elif ty == 'abort':
            abortpos[nod[q]].append(q)
        elif ty == 'recover' and off[q] is not None:
            recpos.append(q)

    # jitter estimate
    inv = 0
    bys = defaultdict(list)
    for q in range(N):
        if sidl[q] is not None and typ[q] in WCC_SET and off[q] is not None:
            bys[sidl[q]].append(q)
    for s in bys:
        lst = bys[s]
        L = len(lst)
        for a in range(L):
            qa = lst[a]
            for qb in lst[a + 1:a + 10]:
                if typ[qb] == 'write' and nod[qb] == nod[qa] and off[qb] + ln[qb] == off[qa]:
                    d = tt[qb] - tt[qa]
                    if d > inv:
                        inv = d
    dts = sorted(tt[q + 1] - tt[q] for q in range(N - 1))
    med = dts[len(dts) // 2] if dts else 1
    J = max(1.0, 1.3 * inv, 2.0 * med)
    span = (tt[-1] - tt[0]) if N else 1
    S = max(1, len(sess))
    gunit = max(1.0, float(span) * S / max(1, N))

    def crash_info(node, pref, tl, q, bt):
        cp = crashpos.get(node)
        if not cp:
            return 0.0, None
        lo = bisect.bisect_right(cp, pref)
        hi = bisect.bisect_left(cp, q)
        ctl = crasht[node]
        if hi > lo:
            for k in range(lo, hi):
                c = ctl[k]
                if c > tl + J and c < bt - J:
                    return C_DEF, 0.0
            return 1.0, 0.0
        weak = False
        if lo - 1 >= 0 and ctl[lo - 1] > tl - J:
            weak = True
        if hi < len(cp) and ctl[hi] - J < bt:
            weak = True
        if weak:
            return 0.0, 1.0
        return 0.0, None

    def crash_between(node, a, b):
        cp = crashpos.get(node)
        if not cp:
            return False
        return bisect.bisect_right(cp, a) < bisect.bisect_left(cp, b)

    def step(st, q):
        node = st[0]
        E = st[1]
        D = st[2]
        tl = st[3]
        sigs = st[4]
        pref = st[5]
        ty = typ[q]
        bn = nod[q]
        o = off[q]
        sg = sig[q]
        best_c = None
        best_s = None
        if sg is not None and sg in sigs:
            best_c = C_DUP
            best_s = (node, E, D, tl, sigs, pref, st[6])
        if ty == 'open' or ty == 'crash' or sg is None:
            if best_c is None:
                return None
            return best_c, best_s
        nc, cc = crash_info(node, pref, tl, q, tt[q])
        nsigs = (sg,) + sigs[:2]
        ntl = tt[q] if tt[q] > tl else tl
        if ty in WCC_SET and o is not None:
            if bn == node:
                if o == E:
                    oc = 0.0
                elif o > E:
                    oc = G_GAP
                else:
                    oc = C_BAD
                c = nc + oc
                if best_c is None or c < best_c:
                    best_c = c
                    best_s = _after(ty, bn, o, ln[q], D, ntl, nsigs, q)
            if cc is not None:
                if o == D:
                    oc = 0.0
                    nd = D
                elif D < o <= E:
                    oc = C_MISSCK
                    nd = o
                elif o > E:
                    oc = G_GAP
                    nd = D
                else:
                    oc = C_BAD
                    nd = o
                c = cc + C_MISSREC + oc
                if best_c is None or c < best_c:
                    best_c = c
                    best_s = _after(ty, bn, o, ln[q], nd, ntl, nsigs, q)
            if best_c is None:
                best_c = C_FALL
                best_s = _after(ty, bn, o, ln[q], min(D, o), ntl, nsigs, q)
        elif ty == 'abort':
            if bn == node:
                c = nc + C_ABORT
                if best_c is None or c < best_c:
                    best_c = c
                    best_s = (bn, E, D, ntl, nsigs, q, 'abort')
            if cc is not None:
                c = cc + C_MISSREC + C_ABORT
                if best_c is None or c < best_c:
                    best_c = c
                    best_s = (bn, D, D, ntl, nsigs, q, 'abort')
            if best_c is None:
                best_c = C_FALL
                best_s = (bn, E, D, ntl, nsigs, q, 'abort')
        elif ty == 'recover' and o is not None:
            if cc is not None:
                if o == D:
                    oc = 0.0
                elif D < o <= E:
                    oc = C_MISSCK
                else:
                    oc = C_BAD
                c = cc + oc
                if best_c is None or c < best_c:
                    best_c = c
                    best_s = (bn, o, o, ntl, nsigs, q, None)
            if best_c is None:
                best_c = C_FALL
                best_s = (bn, o, o, ntl, nsigs, q, None)
        if best_c is None:
            return None
        return best_c, best_s

    def run_dp(s, lam, rset):
        op = openpos[s]
        if rset is None:
            ol = ownpos.get(s, [])
            rs = None
            nown = 1
        else:
            ol = sorted(set(rset) | set(ownpos.get(s, [])))
            rs = set(ol)
            nown = 2

        def ok(q):
            if rs is not None:
                return q in rs
            o2 = own[q]
            return o2 is None or o2 == s

        def rew(q):
            if rs is not None or own[q] == s:
                return BIG
            return lam.get(q, 0.0)

        st0 = (nod[op], 0, 0, tt[op], (), op, None)
        sc = {op: 0.0}
        stt = {op: st0}
        back = {op: None}
        dom = {}
        cnt_exp = 0
        for p in range(op, N):
            if p not in sc:
                continue
            st = stt[p]
            if st[6] is not None:
                continue
            cnt_exp += 1
            if (cnt_exp & 15) == 0 and time.process_time() - t0 > HARD_BUDGET:
                break
            s0 = sc[p]
            node = st[0]
            E = st[1]
            D = st[2]
            tl = st[3]
            pref = st[5]
            key = (node, E, D)
            dm = dom.get(key)
            if dm is not None and dm[0] >= s0 - 1e-9 and dm[1] < p and not crash_between(node, dm[1], p):
                continue
            dom[key] = (s0, p)
            cands = {}
            exc = []
            lst = exact.get((node, E))
            if lst:
                i0 = bisect.bisect_right(lst, p)
                exc = lst[i0:i0 + 8]
                for q in exc:
                    cands[q] = 1
            nl = nodepos.get(node)
            if nl:
                i0 = bisect.bisect_right(nl, p)
                cnt = 0
                for q in nl[i0:i0 + 25]:
                    if off[q] > E and ok(q):
                        cands[q] = 1
                        cnt += 1
                        if cnt >= 3:
                            break
            al = abortpos.get(node)
            if al:
                i0 = bisect.bisect_right(al, p)
                cnt = 0
                for q in al[i0:i0 + 6]:
                    if ok(q):
                        cands[q] = 1
                        cnt += 1
                        if cnt >= 2:
                            break
            for sg in st[4]:
                sl = sigpos.get(sg)
                if sl:
                    i0 = bisect.bisect_right(sl, p)
                    for q in sl[i0:i0 + 2]:
                        if ok(q):
                            cands[q] = 1
                            break
            cp = crashpos.get(node)
            if cp:
                k = bisect.bisect_right(cp, pref)
                rel = k < len(cp) or (k > 0 and crasht[node][k - 1] > tl - J)
                if rel:
                    i0 = bisect.bisect_right(recpos, p)
                    cnt = 0
                    for q in recpos[i0:i0 + 12]:
                        if D <= off[q] <= E and ok(q):
                            cands[q] = 1
                            cnt += 1
                            if cnt >= 4:
                                break
                    al2 = anyoff.get(D)
                    if al2:
                        i0 = bisect.bisect_right(al2, p)
                        cnt = 0
                        for q in al2[i0:i0 + 8]:
                            if ok(q):
                                cands[q] = 1
                                cnt += 1
                                if cnt >= 3:
                                    break
            if ol:
                i0 = bisect.bisect_right(ol, p)
                for q in ol[i0:i0 + nown]:
                    cands[q] = 1
            for q in cands:
                if q <= p or not ok(q):
                    continue
                r = step(st, q)
                if r is None:
                    continue
                c, nst = r
                dt = tt[q] - tl
                tc = ALPHA * dt / gunit if dt > 0 else 0.0
                if tc > TC_CAP:
                    tc = TC_CAP
                v = s0 - c - tc + rew(q)
                if v > sc.get(q, NEG):
                    sc[q] = v
                    stt[q] = nst
                    back[q] = (p, (q,), c + tc)
            # adjacent jitter swaps: y (later observed) truly precedes x
            for y in exc:
                if typ[y] != 'write' or not ok(y):
                    continue
                Ey = off[y] + ln[y]
                l2 = exact.get((node, Ey))
                if not l2:
                    continue
                i0 = bisect.bisect_right(l2, p)
                for x in l2[i0:]:
                    if x >= y:
                        break
                    if not ok(x) or tt[x] < tt[y] - 2 * J:
                        continue
                    nc, cc = crash_info(node, pref, tl, y, tt[y])
                    c = nc + C_SWAP
                    ntl = max(tt[x], tt[y], tl)
                    nsig = (sig[x], sig[y]) + st[4][:1]
                    nst = _after(typ[x], node, off[x], ln[x], D, ntl, nsig, y)
                    dt = ntl - tl
                    tc = ALPHA * dt / gunit if dt > 0 else 0.0
                    if tc > TC_CAP:
                        tc = TC_CAP
                    v = s0 - c - tc + rew(x) + rew(y)
                    if v > sc.get(y, NEG):
                        sc[y] = v
                        stt[y] = nst
                        back[y] = (y if False else p, (y, x), c + tc)
                    break
        qbest = op
        bv = sc[op]
        for k2 in sc:
            v = sc[k2]
            if v > bv or (v == bv and k2 < qbest):
                bv = v
                qbest = k2
        path = []
        q = qbest
        guard = 0
        while back.get(q) is not None and guard < N + 5:
            p, evt, c = back[q]
            path.append((p, q, evt, c))
            q = p
            guard += 1
        path.reverse()
        return {'path': path, 'stt': stt, 'end': qbest, 'endstate': stt[qbest]}

    # Lagrangian loop
    lam = {}
    for q in anon:
        lam[q] = R0
    best_meas = None
    best_res = None
    it = 0
    stepsz = 1.0
    while True:
        ti = time.process_time()
        res = {}
        for s in sess:
            res[s] = run_dp(s, lam, None)
        claims = defaultdict(list)
        for s in sess:
            path = res[s]['path']
            for k, (p, q, evt, c) in enumerate(path):
                cout = path[k + 1][3] if k + 1 < len(path) else 0.0
                for e in evt:
                    if own[e] is None:
                        claims[e].append((c + cout, s))
        meas = 0
        for q in anon:
            n = len(claims.get(q, ()))
            meas += abs(1 - n)
        if best_meas is None or meas < best_meas:
            best_meas = meas
            best_res = (res, claims)
        now = time.process_time()
        el = now - t0
        dur = now - ti
        it += 1
        if meas == 0 or el + dur * 1.1 > SOFT_BUDGET or it >= 30:
            break
        for q in anon:
            n = len(claims.get(q, ()))
            if n != 1:
                v = lam[q] + stepsz * (1 - n)
                lam[q] = v if v > 0.0 else 0.0
        stepsz *= 0.85

    res, claims = best_res
    assign = {}
    for q in claims:
        lst = sorted(claims[q])
        assign[q] = lst[0][1]

    keys = {}
    states = {}
    for s in sess:
        r = res[s]
        op = openpos[s]
        ks = [op]
        ss = [r['stt'][op]]
        for (p, q, evt, c) in r['path']:
            ks.append(q)
            ss.append(r['stt'][q])
        keys[s] = ks
        states[s] = ss
    sigown = defaultdict(set)
    for q in assign:
        if sig[q] is not None:
            sigown[sig[q]].add(assign[q])
    for q in range(N):
        if own[q] is not None and sig[q] is not None:
            sigown[sig[q]].add(own[q])

    for q in anon:
        if q in assign:
            continue
        best = None
        for s in sess:
            op = openpos[s]
            if op >= q:
                continue
            ks = keys[s]
            k = bisect.bisect_left(ks, q) - 1
            if k < 0:
                k = 0
            st = states[s][k]
            if sig[q] is not None and s in sigown.get(sig[q], ()):
                c = 0.05
            else:
                r = step(st, q)
                if r is None:
                    c = 20.0
                else:
                    c = r[0]
                    dt = tt[q] - st[3]
                    if dt > 0:
                        c += min(TC_CAP, ALPHA * dt / gunit)
                if st[6] is not None:
                    c += 5.0
            if best is None or c < best[0]:
                best = (c, s)
        if best is None:
            best = (0.0, sess[0])
        assign[q] = best[1]
        if sig[q] is not None:
            sigown[sig[q]].add(best[1])

    def status_of(st):
        if st[6] == 'commit':
            return 'committed', st[1]
        if st[6] == 'abort':
            return 'aborted', st[2]
        cp = crashpos.get(st[0])
        if cp and bisect.bisect_right(cp, st[5]) < len(cp):
            return 'down', st[2]
        return 'active', st[2]

    groups = defaultdict(list)
    for q in anon:
        groups[assign[q]].append(q)
    out_sess = {}
    for s in sess:
        st = None
        if time.process_time() - t0 < FINAL_BUDGET:
            try:
                r = run_dp(s, {}, groups.get(s, []))
                st = r['endstate']
            except Exception:
                st = None
        if st is None:
            st = res[s]['endstate']
        stat, dur = status_of(st)
        try:
            dur = int(dur)
        except Exception:
            dur = 0
        out_sess[s] = {"status": stat, "durable": dur}
    for s in extra_sess:
        if s not in out_sess:
            out_sess[s] = {"status": "active", "durable": 0}

    out_assign = {}
    for q in anon:
        out_assign[str(idx[q])] = assign.get(q, sess[0])
    return {"assignments": out_assign, "sessions": out_sess}

import time
import random
import bisect
import math
import statistics

V_COST = 5.0
MISS = 1.0
REORD = 0.3
DUP = 0.3
RANK = {"checkpoint": 0, "write": 1, "commit": 2}
SWITCH_MARGIN = 1.0

C_GAP = 3.0
C_JIT = 0.7
C_STALE = 8.0
C_DUP = 1.5
C_MISSREC = 3.5
C_LATE = 2.5
C_EARLYREC = 3.0
C_MISSCK = 3.0
C_COMMIT_BACK = 5.0
C_ABSURD = 25.0
MAXGAPS = 5
TYPES = {"open": 0, "write": 1, "checkpoint": 2, "commit": 3, "abort": 4, "recover": 5, "crash": 6}


def _toint(x):
    if x is None or isinstance(x, bool):
        return None
    try:
        return int(x)
    except Exception:
        try:
            return int(float(x))
        except Exception:
            return None


def _addgap(gaps, a, b):
    g = gaps + ((a, b),)
    if len(g) > MAXGAPS:
        g = g[-MAXGAPS:]
    return g


def _fill(gaps, a, b):
    for k, (g0, g1) in enumerate(gaps):
        if g0 <= a and b <= g1 and b > a:
            pieces = []
            if a > g0:
                pieces.append((g0, a))
            if b < g1:
                pieces.append((b, g1))
            ng = gaps[:k] + tuple(pieces) + gaps[k + 1:]
            return ng, C_GAP * (1 - len(pieces))
    return None


def _trans(S, typ, nd, off, ln):
    st, sn, so, du, gp, ax = S
    out = []
    if typ == 0:
        if st == 0:
            out.append((0.0, (1, nd, 0, 0, (), -1)))
        return out
    if st == 0:
        return out
    if off is None and typ in (1, 2, 3, 5):
        off = so
    if typ == 1:
        if ln is None:
            ln = 0
        if st == 1 or st == 5:
            if sn == nd:
                if off == so:
                    out.append((0.0, (st, sn, off + ln, du, gp, ax)))
                elif off > so:
                    out.append((C_GAP, (st, sn, off + ln, du, _addgap(gp, so, off), ax)))
                else:
                    f = _fill(gp, off, off + ln)
                    if f is not None:
                        out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
                    else:
                        out.append((C_STALE, S))
        elif st == 2:
            if off >= du:
                if off == du:
                    out.append((C_MISSREC, (1, nd, off + ln, du, gp, -2)))
                else:
                    out.append((C_MISSREC + C_GAP, (1, nd, off + ln, du, _addgap(gp, du, off), -2)))
                if sn == nd:
                    out.append((C_LATE, S))
            else:
                f = _fill(gp, off, off + ln)
                if f is not None:
                    out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
        else:
            f = _fill(gp, off, off + ln)
            if f is not None:
                out.append((C_JIT - f[1], (st, sn, so, du, f[0], ax)))
        return out
    if typ == 2 or typ == 3:
        if st == 1 or st == 5:
            if sn == nd:
                nst = 3 if typ == 3 else st
                if off == so:
                    out.append((0.0, (nst, sn, off, off, gp, ax)))
                elif off > so:
                    out.append((C_GAP, (nst, sn, off, off, _addgap(gp, so, off), ax)))
                elif off >= du:
                    if typ == 2:
                        out.append((C_JIT, (st, sn, so, off, gp, ax)))
                    else:
                        out.append((C_COMMIT_BACK, (3, sn, off, off, gp, ax)))
                else:
                    out.append((C_STALE, S))
        elif st == 2:
            if off >= du:
                nst = 3 if typ == 3 else 1
                c = C_MISSREC + (C_GAP if off > du else 0.0)
                out.append((c, (nst, nd, off, off, gp, -2)))
                if sn == nd and typ == 2:
                    out.append((C_LATE, (2, sn, off, off, gp, ax)))
        return out
    if typ == 4:
        if st == 1 or st == 5:
            if sn == nd:
                out.append((0.0, (4, sn, so, du, gp, ax)))
        elif st == 2:
            out.append((C_MISSREC * 0.6, (4, sn, so, du, gp, ax)))
        return out
    if typ == 5:
        if st == 2:
            if off == du:
                out.append((0.0, (1, nd, off, off, gp, -1)))
            elif off > du:
                out.append((C_MISSCK, (1, nd, off, off, gp, -1)))
            else:
                out.append((C_STALE, (1, nd, du, du, gp, -1)))
        elif st == 1:
            if ax == -2 and sn == nd and off <= du:
                out.append((C_JIT - C_MISSREC, (1, sn, so, du, gp, -1)))
            if du <= off <= so:
                out.append((C_EARLYREC + (0.0 if off == du else C_MISSCK * 0.5),
                            (5, nd, off, off, gp, sn)))
        return out
    return out


def _crash(S, nd):
    st = S[0]
    if st == 1:
        if S[1] == nd:
            du = S[3]
            return (2, nd, du, du, tuple(g for g in S[4] if g[1] <= du), -1)
        return S
    if st == 5:
        if S[5] == nd:
            return (1, S[1], S[2], S[3], S[4], -1)
        if S[1] == nd:
            du = S[3]
            return (2, nd, du, du, tuple(g for g in S[4] if g[1] <= du), -1)
    return S


def _beam(inp, t_start, budget):
    raw = inp.get("events") or []
    nodes = list(inp.get("nodes") or [])
    evs = []
    for pos, e in enumerate(raw):
        if not isinstance(e, dict):
            continue
        i = _toint(e.get("i"))
        if i is None:
            i = pos
        t = _toint(e.get("t"))
        evs.append((t if t is not None else 0, i, e, i))
    evs.sort(key=lambda x: (x[0], x[1]))
    node_idx = {}
    for nn in nodes:
        nn = str(nn)
        if nn not in node_idx:
            node_idx[nn] = len(node_idx)
    sids = []
    sid_idx = {}
    for _, _, e, _ in evs:
        s = e.get("sid")
        if s is not None and e.get("type") != "crash":
            s = str(s)
            if s not in sid_idx:
                sid_idx[s] = len(sids)
                sids.append(s)
    E = []
    for t, pos, e, i in evs:
        typ = TYPES.get(e.get("type"), -1)
        if typ < 0:
            continue
        nn = str(e.get("node"))
        if nn not in node_idx:
            node_idx[nn] = len(node_idx)
        s = e.get("sid")
        si = -1
        if s is not None and typ != 6:
            si = sid_idx[str(s)]
        E.append((typ, node_idx[nn], _toint(e.get("off")), _toint(e.get("len")), si, i, t))
    nS = len(sids)
    nE = len(E)
    dupc = {}
    origset = set()
    seen = {}
    for k, (typ, nd, off, ln, si, i, t) in enumerate(E):
        if typ == 0 or typ == 6:
            continue
        key = (typ, nd, off, ln)
        lst = seen.get(key)
        if lst:
            dupc[k] = lst[-4:]
            for j in lst[-4:]:
                origset.add(j)
        seen.setdefault(key, []).append(k)
    init = tuple((0, -1, 0, 0, (), -1) for _ in range(nS))
    beam = [(0.0, init, None, {})]
    K = 24
    KMAX = 40
    KMIN = 3
    BR = 6
    DELTA = 12.0
    b0 = time.process_time()
    for k in range(nE):
        typ, nd, off, ln, si, i, t = E[k]
        if k % 8 == 0 and k > 0:
            el = time.process_time() - b0
            proj = el * nE / k
            if proj > budget:
                K = max(KMIN, int(K * 0.7))
            elif proj < budget * 0.5 and K < KMAX:
                K = min(KMAX, K + 4)
            if el > budget * 1.15:
                K = 1
        if typ == 6:
            cm = {}
            merged = {}
            for h in beam:
                ns = []
                for S in h[1]:
                    r = cm.get(id(S))
                    if r is None:
                        r = _crash(S, nd)
                        cm[id(S)] = r
                    ns.append(r)
                ns = tuple(ns)
                o = merged.get(ns)
                if o is None or h[0] < o[0]:
                    merged[ns] = (h[0], ns, h[2], h[3])
            beam = sorted(merged.values(), key=lambda x: x[0])[:max(1, K)]
            continue
        if nS == 0:
            continue
        memo = {}
        cands = [si] if si >= 0 else range(nS)
        dl = dupc.get(k)
        isorig = k in origset
        newc = []
        for hidx, h in enumerate(beam):
            hc, sess, asg, om = h
            opts = []
            for s in cands:
                S = sess[s]
                r = memo.get(id(S))
                if r is None:
                    r = _trans(S, typ, nd, off, ln)
                    memo[id(S)] = r
                for c, NS in r:
                    opts.append((c, s, NS))
            if dl:
                ds = set()
                for j in dl:
                    s = om.get(j)
                    if s is not None and (si < 0 or s == si) and s not in ds:
                        ds.add(s)
                        opts.append((C_DUP, s, None))
            if not opts:
                if si >= 0:
                    fs = si
                else:
                    fs = 0
                    bd = None
                    for s in range(nS):
                        S = sess[s]
                        if S[0] != 0 and S[1] == nd:
                            d = abs(S[2] - (off if off is not None else S[2]))
                            if bd is None or d < bd:
                                bd = d
                                fs = s
                opts.append((C_ABSURD, fs, None))
            opts.sort(key=lambda x: (x[0], x[1]))
            best = opts[0][0]
            for c, s, NS in opts[:BR]:
                if c > best + DELTA:
                    break
                newc.append((hc + c, hidx, s, NS))
        if not newc:
            continue
        newc.sort(key=lambda x: (x[0], x[1], x[2]))
        merged = set()
        out = []
        for c, hidx, s, NS in newc:
            h = beam[hidx]
            sess = h[1]
            if NS is not None and NS != sess[s]:
                l = list(sess)
                l[s] = NS
                ns = tuple(l)
            else:
                ns = sess
            if ns in merged:
                continue
            om = h[3]
            if isorig:
                om = dict(om)
                om[k] = s
            merged.add(ns)
            out.append((c, ns, (k, s, h[2]), om))
            if len(out) >= max(1, K):
                break
        beam = out
    best = beam[0] if beam else (0.0, init, None, {})
    assign = {}
    node = best[2]
    while node is not None:
        k, s, node = node
        assign[k] = s
    assignments = {}
    if nS > 0:
        for k, (typ, nd, off, ln, si, i, t) in enumerate(E):
            if typ == 6 or si >= 0:
                continue
            s = assign.get(k)
            if s is not None:
                assignments[str(i)] = sids[s]
    names = {0: "active", 1: "active", 2: "down", 3: "committed", 4: "aborted", 5: "active"}
    sessions = {}
    for s in range(nS):
        S = best[1][s]
        du = S[2] if S[0] == 3 else S[3]
        sessions[sids[s]] = {"status": names.get(S[0], "active"), "durable": int(du)}
    return assignments, sessions


def solve(state, params):
    t_start = time.process_time()
    inp = state.get("input") or {}
    if not isinstance(inp, dict):
        inp = {}
    raw = inp.get("events") or []
    recs = []
    for k, ev in enumerate(raw):
        if not isinstance(ev, dict):
            continue
        i = _toint(ev.get("i"))
        if i is None:
            i = k
        t = _toint(ev.get("t"))
        if t is None:
            t = 0
        sid = ev.get("sid")
        if sid is not None:
            sid = str(sid)
        recs.append((t, i, str(ev.get("node")), str(ev.get("type")), _toint(ev.get("off")),
                     _toint(ev.get("len")), sid))
    recs.sort(key=lambda z: (z[0], z[1]))
    n = len(recs)
    T = [r[0] for r in recs]
    IDX = [r[1] for r in recs]
    ND = [r[2] for r in recs]
    TY = [r[3] for r in recs]
    OFF = [r[4] if r[4] is not None else 0 for r in recs]
    LEN = [r[5] if r[5] is not None else 0 for r in recs]
    SIDR = [r[6] if r[3] != "crash" else None for r in recs]
    ENDOFF = [0] * n
    for k in range(n):
        if TY[k] == "write":
            ENDOFF[k] = OFF[k] + LEN[k]
        elif TY[k] in ("checkpoint", "commit", "recover"):
            ENDOFF[k] = OFF[k]
    SG = [(TY[k], ND[k], OFF[k], LEN[k]) for k in range(n)]

    sids = []
    sidx = {}
    open_t = {}
    for k in range(n):
        if TY[k] == "open" and SIDR[k] is not None and SIDR[k] not in sidx:
            sidx[SIDR[k]] = len(sids)
            sids.append(SIDR[k])
            open_t[sidx[SIDR[k]]] = T[k]
    for k in range(n):
        if TY[k] != "crash" and SIDR[k] is not None and SIDR[k] not in sidx:
            sidx[SIDR[k]] = len(sids)
            sids.append(SIDR[k])
            open_t[sidx[SIDR[k]]] = T[k]
    ns = len(sids)
    anon = [k for k in range(n) if TY[k] != "crash" and SIDR[k] is None]
    if ns == 0:
        state["output"] = {"assignments": {}, "sessions": {}}
        return state

    # ---------------- phase 1: beam tracking ----------------
    try:
        beam_asg, beam_sess = _beam(inp, t_start, 0.30)
    except Exception:
        beam_asg, beam_sess = {}, {}

    crash_k = [k for k in range(n) if TY[k] == "crash"]
    CT = [T[k] for k in crash_k]
    CN = [ND[k] for k in crash_k]
    nc = len(crash_k)
    node_crash_t = {}
    for k in crash_k:
        node_crash_t.setdefault(ND[k], []).append(T[k])

    gaps = [T[k + 1] - T[k] for k in range(n - 1)]
    mg = statistics.median(gaps) if gaps else 1
    W = max(3, int(3 * mg + 1))
    lab = {}
    for k in range(n):
        if SIDR[k] is not None and TY[k] in RANK:
            lab.setdefault(SIDR[k], []).append(k)
    maxinv = 0
    for s, ks in lab.items():
        for a in range(len(ks)):
            for b in range(a + 1, min(len(ks), a + 6)):
                ka = ks[a]
                kb = ks[b]
                if ND[ka] != ND[kb] or SG[ka] == SG[kb]:
                    continue
                if (OFF[kb], RANK[TY[kb]]) < (OFF[ka], RANK[TY[ka]]):
                    ct = node_crash_t.get(ND[ka], [])
                    j = bisect.bisect_left(ct, T[ka] - 2)
                    if j < len(ct) and ct[j] <= T[kb] + 2:
                        continue
                    if T[kb] - T[ka] <= 40:
                        maxinv = max(maxinv, T[kb] - T[ka])
    W = max(W, int(maxinv * 1.3) + 1)

    def new_state():
        return ["P", None, 0, 0, 0, None, 0, 0, -1, set(), 0, None]

    def do_crash(S, t, node):
        c = 0.0
        pk = S[8]
        if pk >= 0 and t - T[pk] > W:
            c += V_COST
            S[8] = -1
            pk = -1
        if S[0] == "A" and S[1] == node:
            S[0] = "D"
            S[4] = t
            S[5] = node
            S[6] = S[2]
            S[7] = S[3]
            S[2] = S[3]
            S[11] = None
            if pk >= 0:
                off = OFF[pk]
                if off > S[3]:
                    c += MISS
                    S[3] = off
                elif off < S[3]:
                    c += V_COST
                S[0] = "A"
                S[1] = ND[pk]
                S[2] = off
                S[8] = -1
                c += REORD
        return c

    def step(S, k):
        c = 0.0
        t = T[k]
        ty = TY[k]
        pk = S[8]
        if pk >= 0 and t - T[pk] > W:
            c += V_COST
            S[8] = -1
        sig = SG[k]
        seen = S[9]
        st = S[0]
        if ty == "open":
            if st == "P":
                S[0] = "A"
                S[1] = ND[k]
                seen.add(sig)
                return c
            return c + (DUP if sig in seen else V_COST)
        if st == "P":
            return c + V_COST
        if st == "C" or st == "X":
            if sig in seen:
                return c + DUP
            if t - S[10] <= W:
                return c + REORD
            return c + V_COST
        off = OFF[k]
        if st == "D":
            if ty == "recover":
                if off == S[3]:
                    pass
                elif off > S[3]:
                    c += MISS
                    S[3] = off
                else:
                    if sig in seen:
                        return c + DUP
                    c += V_COST
                    S[3] = off
                S[0] = "A"
                S[1] = ND[k]
                S[2] = off
                S[11] = None
                seen.add(sig)
                return c
            if t - S[4] <= W and ND[k] == S[5]:
                pc = S[6]
                if ty == "write" and off == pc:
                    S[6] = pc + LEN[k]
                    seen.add(sig)
                    return c + REORD
                if ty == "checkpoint" and off == pc:
                    S[7] = pc
                    S[3] = pc
                    S[2] = pc
                    seen.add(sig)
                    return c + REORD
                if ty == "commit" and off == pc:
                    S[0] = "C"
                    S[3] = pc
                    S[2] = pc
                    S[10] = t
                    seen.add(sig)
                    return c + REORD
                if ty == "abort":
                    S[0] = "X"
                    S[10] = t
                    seen.add(sig)
                    return c + REORD
            if sig in seen:
                return c + DUP
            c += MISS
            S[0] = "A"
            S[1] = ND[k]
            S[2] = S[3]
            S[11] = (t, S[3], ND[k])
        if ty == "recover":
            if sig in seen:
                return c + DUP
            inf = S[11]
            if inf is not None and ND[k] == inf[2] and ND[k] == S[1] and off == inf[1] \
                    and t - inf[0] <= W + 2:
                S[11] = None
                seen.add(sig)
                return c - MISS + REORD
            if S[8] < 0:
                S[8] = k
                seen.add(sig)
                return c
            return c + V_COST
        if ND[k] != S[1]:
            if sig in seen:
                return c + DUP
            c += V_COST
            S[1] = ND[k]
        cur = S[2]
        if ty == "write":
            if off == cur:
                S[2] = cur + LEN[k]
            elif off > cur:
                c += MISS
                S[2] = off + LEN[k]
            else:
                if sig in seen:
                    return c + DUP
                c += V_COST
                S[2] = off + LEN[k]
        elif ty == "checkpoint":
            if off == cur:
                S[3] = cur
            elif off > cur:
                c += MISS
                S[2] = off
                S[3] = off
            else:
                if sig in seen:
                    return c + DUP
                c += V_COST
        elif ty == "commit":
            if off > cur:
                c += MISS
            elif off < cur:
                if sig in seen:
                    return c + DUP
                c += V_COST
            S[0] = "C"
            S[2] = off
            S[3] = off
            S[10] = t
        elif ty == "abort":
            S[0] = "X"
            S[2] = S[3]
            S[10] = t
        else:
            c += V_COST
        seen.add(sig)
        return c

    def fix_order(seq):
        seq = list(seq)
        for a in range(1, len(seq)):
            j = a
            while j > 0:
                ka = seq[j - 1]
                kb = seq[j]
                tya = TY[ka]
                tyb = TY[kb]
                if tya not in RANK or tyb not in RANK:
                    break
                if ND[ka] != ND[kb] or T[kb] - T[ka] > W or SG[ka] == SG[kb]:
                    break
                if (OFF[kb], RANK[tyb]) >= (OFF[ka], RANK[tya]):
                    break
                ct = node_crash_t.get(ND[ka])
                if ct:
                    q = bisect.bisect_left(ct, T[ka])
                    if q < len(ct) and ct[q] <= T[kb]:
                        break
                seq[j - 1] = kb
                seq[j] = ka
                j -= 1
        return seq

    def snap(S, ci, c):
        return (S[0], S[1], S[2], S[3], S[4], S[5], S[6], S[7], S[8], S[10], ci, c, S[11])

    def simulate(seq, prev=None):
        F = fix_order(seq)
        p = 0
        if prev is not None:
            PF = prev[0]
            m = min(len(PF), len(F))
            while p < m and PF[p] == F[p]:
                p += 1
        if prev is not None and p > 0:
            snaps = prev[1][:p]
            AP = prev[2][:p]
            if p < len(prev[1]):
                sn = prev[1][p]
            else:
                sn = prev[3]
            S = list(sn[:9])
            S.append({SG[F[q]] for q in range(p) if AP[q]})
            S.append(sn[9])
            S.append(sn[12])
            ci = sn[10]
            c = sn[11]
        else:
            p = 0
            snaps = []
            AP = []
            S = new_state()
            c = 0.0
            ci = 0
            if F:
                ci = bisect.bisect_left(CT, T[F[0]] - 1)
        seen = S[9]
        for j in range(p, len(F)):
            k = F[j]
            t = T[k]
            snaps.append(snap(S, ci, c))
            while ci < nc and (CT[ci] < t or (CT[ci] == t and crash_k[ci] < k)):
                if S[0] == "A" or S[8] >= 0:
                    c += do_crash(S, CT[ci], CN[ci])
                ci += 1
            c += step(S, k)
            AP.append(SG[k] in seen)
        endsnap = snap(S, ci, c)
        while ci < nc:
            if S[0] == "A" or S[8] >= 0:
                c += do_crash(S, CT[ci], CN[ci])
            ci += 1
        if S[8] >= 0:
            c += V_COST
        return c, (F, snaps, AP, endsnap), S

    cands = {}
    for k in anon:
        cl = [s for s in range(ns) if open_t[s] <= T[k]]
        if not cl:
            cl = list(range(ns))
        cands[k] = cl

    lab_by_s = [[] for _ in range(ns)]
    for k in range(n):
        if TY[k] != "crash" and SIDR[k] is not None:
            lab_by_s[sidx[SIDR[k]]].append(k)
    labT = [[T[k] for k in lst] for lst in lab_by_s]

    # ---------------- greedy fallback ----------------
    assign = {}
    missing = [k for k in anon if beam_asg.get(str(IDX[k])) not in sidx]
    if missing:
        def copy_state(S):
            X = list(S)
            X[9] = set(S[9])
            return X
        states = [new_state() for _ in range(ns)]
        last_act = [-1] * ns
        for k in range(n):
            ty = TY[k]
            if ty == "crash":
                for s in range(ns):
                    if states[s][0] == "A" or states[s][8] >= 0:
                        do_crash(states[s], T[k], ND[k])
                continue
            if SIDR[k] is not None:
                s = sidx[SIDR[k]]
                step(states[s], k)
                last_act[s] = k
                continue
            bsid = beam_asg.get(str(IDX[k]))
            if bsid in sidx:
                bs = sidx[bsid]
            else:
                best = None
                bs = cands[k][0]
                for s in cands[k]:
                    X = copy_state(states[s])
                    c = step(X, k)
                    lst = lab_by_s[s]
                    q = bisect.bisect_right(labT[s], T[k])
                    if q < len(lst) and TY[lst[q]] != "open":
                        c += 0.5 * step(copy_state(X), lst[q])
                    rec = last_act[s] if ND[k] == states[s][1] else -5
                    key = (c, -rec, s)
                    if best is None or key < best:
                        best = key
                        bs = s
            assign[k] = bs
            step(states[bs], k)
            last_act[bs] = k
    else:
        for k in anon:
            assign[k] = sidx[beam_asg[str(IDX[k])]]
    seed_assign = dict(assign)

    # ---------------- phase 2: annealing seeded by the beam ----------------
    sess_ev = [list(lab_by_s[s]) for s in range(ns)]
    for k in anon:
        bisect.insort(sess_ev[assign[k]], k)
    cache = []
    cost = []
    for s in range(ns):
        rr = simulate(sess_ev[s])
        cost.append(rr[0])
        cache.append(rr[1])
    total = sum(cost)
    seed_total = total
    best_total = total
    best_assign = dict(assign)
    rng = random.Random(1234567)
    na = len(anon)
    anon_pos = {k: p for p, k in enumerate(anon)}
    deadline = t_start + 0.75
    T0 = 1.0
    T1 = 0.05
    it = 0
    if na > 0 and ns > 1:
        sa_start = time.process_time()
        span = max(1e-6, deadline - sa_start)
        temp = T0
        while True:
            if (it & 15) == 0:
                now = time.process_time()
                if now >= deadline:
                    break
                frac = (now - sa_start) / span
                temp = T0 * (T1 / T0) ** frac
            it += 1
            r = rng.random()
            moves = []
            k = anon[rng.randrange(na)]
            a = assign[k]
            if r < 0.6:
                cl = cands[k]
                if len(cl) < 2:
                    continue
                if rng.random() < 0.75:
                    fit = []
                    nfit = []
                    nk = ND[k]
                    ok_ = OFF[k]
                    tyk = TY[k]
                    for s in cl:
                        if s == a:
                            continue
                        lst = sess_ev[s]
                        q = bisect.bisect_left(lst, k)
                        if q == 0:
                            continue
                        kp = lst[q - 1]
                        if ND[kp] == nk:
                            nfit.append(s)
                            if tyk in RANK and ENDOFF[kp] == ok_:
                                fit.append(s)
                        elif tyk == "recover" and (TY[kp] in RANK or TY[kp] == "recover"):
                            if ENDOFF[kp] >= ok_:
                                fit.append(s)
                    if fit and rng.random() < 0.7:
                        pool = fit
                    else:
                        pool = nfit or fit or cl
                    b = pool[rng.randrange(len(pool))]
                else:
                    b = cl[rng.randrange(len(cl))]
                if b == a:
                    continue
                moves.append((k, b))
            elif r < 0.85:
                p = anon_pos[k]
                lo = max(0, p - 15)
                hi = min(na - 1, p + 15)
                k2 = anon[rng.randint(lo, hi)]
                b = assign[k2]
                if b == a or b not in cands[k] or a not in cands[k2]:
                    continue
                moves.append((k, b))
                moves.append((k2, a))
            else:
                b = rng.randrange(ns)
                if b == a:
                    continue
                p = anon_pos[k]
                L = rng.randint(3, 40)
                for q in range(p, min(na, p + L)):
                    kk = anon[q]
                    sa = assign[kk]
                    if sa == a and b in cands[kk]:
                        moves.append((kk, b))
                    elif sa == b and a in cands[kk]:
                        moves.append((kk, a))
                if not moves:
                    continue
            touched = set()
            for kk, nb in moves:
                touched.add(assign[kk])
                touched.add(nb)
            newl = {}
            for s in touched:
                newl[s] = list(sess_ev[s])
            for kk, nb in moves:
                lst = newl[assign[kk]]
                del lst[bisect.bisect_left(lst, kk)]
                bisect.insort(newl[nb], kk)
            newc = {}
            newcache = {}
            delta = 0.0
            for s in touched:
                rr = simulate(newl[s], cache[s])
                newc[s] = rr[0]
                newcache[s] = rr[1]
                delta += rr[0] - cost[s]
            accept = delta <= 0
            if not accept:
                x = delta / temp
                if x < 50 and rng.random() < math.exp(-x):
                    accept = True
            if accept:
                for s in touched:
                    sess_ev[s] = newl[s]
                    cost[s] = newc[s]
                    cache[s] = newcache[s]
                for kk, nb in moves:
                    assign[kk] = nb
                total += delta
                if total < best_total - 1e-9:
                    best_total = total
                    best_assign = dict(assign)

    stmap = {"C": "committed", "X": "aborted", "A": "active", "D": "down", "P": "active"}
    use_sa = best_total < seed_total - SWITCH_MARGIN
    final = best_assign if use_sa else seed_assign
    sess_ev = [list(lab_by_s[s]) for s in range(ns)]
    for k in anon:
        bisect.insort(sess_ev[final[k]], k)
    out_sessions = {}
    for s in range(ns):
        sid = sids[s]
        if (not use_sa) and sid in beam_sess and not missing:
            out_sessions[sid] = beam_sess[sid]
        else:
            S = simulate(sess_ev[s])[2]
            out_sessions[sid] = {"status": stmap.get(S[0], "active"), "durable": int(S[3])}
    assignments = {}
    for k in anon:
        assignments[str(IDX[k])] = sids[final[k]]
    state["output"] = {"assignments": assignments, "sessions": out_sessions}
    state["used_sa"] = bool(use_sa)
    state["sa_iters"] = it
    return state
